        private static void TryApplyPatchStep(string stepName, Action applyStep)
        {
            try
            {
                applyStep?.Invoke();
            }
            catch (Exception ex)
            {
                ModLogger.Error("BattleMapSpawnHandoffPatch.Apply step failed. Step=" + (stepName ?? "unknown"), ex);
            }
        }

