        private static bool HasDeferredClientCreateMissilePayload(int missileIndex, int shooterAgentIndex = int.MinValue)
        {
            if (missileIndex < 0)
                return false;

            lock (DeferredClientCreateMissilePayloads)
            {
                return DeferredClientCreateMissilePayloads.Any(candidate =>
                    candidate?.Message != null &&
                    candidate.Message.MissileIndex == missileIndex &&
                    (shooterAgentIndex == int.MinValue || candidate.Message.AgentIndex == shooterAgentIndex));
            }
        }

        private static bool AreDeferredClientCreateMissileMessagesEquivalent(
            CreateMissile left,
            CreateMissile right)
        {
            return left != null &&
                   right != null &&
                   left.MissileIndex == right.MissileIndex &&
                   left.AgentIndex == right.AgentIndex;
        }

        private static bool AreDeferredClientHandleMissileCollisionReactionMessagesEquivalent(
            HandleMissileCollisionReaction left,
            HandleMissileCollisionReaction right)
        {
            return left != null &&
                   right != null &&
                   left.MissileIndex == right.MissileIndex &&
                   left.AttackerAgentIndex == right.AttackerAgentIndex &&
                   left.AttachedAgentIndex == right.AttachedAgentIndex &&
                   left.CollisionReaction == right.CollisionReaction &&
                   left.AttachedToShield == right.AttachedToShield &&
                   left.AttachedBoneIndex == right.AttachedBoneIndex &&
                   GetMissionObjectIdValue(left.AttachedMissionObjectId) == GetMissionObjectIdValue(right.AttachedMissionObjectId) &&
                   left.ForcedSpawnIndex == right.ForcedSpawnIndex;
        }

        private static bool HasDeferredClientSpawnWeaponWithNewEntityPayload(MissionObjectId missionObjectId)
        {
            int missionObjectIdValue = GetMissionObjectIdValue(missionObjectId);
            if (missionObjectIdValue < 0)
                return false;

            lock (DeferredClientSpawnWeaponWithNewEntityPayloads)
            {
                return DeferredClientSpawnWeaponWithNewEntityPayloads.Any(
                    candidate => candidate?.Message?.ForcedIndex == missionObjectIdValue);
            }
        }

        private static int GetMissionObjectIdValue(MissionObjectId missionObjectId)
        {
            return missionObjectId.Id;
        }

        private static bool TryRemapExactSiegeMissionObjectIdMessage(
            object message,
            string missionObjectIdMemberName,
            SiegeMissionObjectIdBridgeTarget target,
            string messageName)
        {
            if (message == null || string.IsNullOrWhiteSpace(missionObjectIdMemberName))
                return false;

            Mission mission = Mission.Current;
            if (!SiegeMissionObjectIdBridge.IsExactSiegeClientContext(mission))
                return false;

            if (!TryGetMissionObjectIdMemberValue(
                    message,
                    missionObjectIdMemberName,
                    out MissionObjectId serverMissionObjectId,
                    out string readDiagnostics))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    serverMissionObjectId,
                    "read-failed",
                    readDiagnostics);
                return false;
            }

            if (!SiegeMissionObjectIdBridge.TryTranslateMissionObjectId(
                    mission,
                    serverMissionObjectId,
                    target,
                    out MissionObjectId localMissionObjectId,
                    out string bridgeDiagnostics))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    serverMissionObjectId,
                    "not-mapped",
                    bridgeDiagnostics);
                return false;
            }

            if (GetMissionObjectIdValue(localMissionObjectId) == GetMissionObjectIdValue(serverMissionObjectId))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    localMissionObjectId,
                    "mapped-noop",
                    "Bridge={" + bridgeDiagnostics + "}");
                return true;
            }

            if (!TrySetMissionObjectIdMemberValue(
                    message,
                    missionObjectIdMemberName,
                    localMissionObjectId,
                    out string writeDiagnostics))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    localMissionObjectId,
                    "write-failed",
                    writeDiagnostics + " Bridge={" + bridgeDiagnostics + "}");
                return false;
            }

            TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                messageName,
                missionObjectIdMemberName,
                serverMissionObjectId,
                localMissionObjectId,
                "remapped",
                "Bridge={" + bridgeDiagnostics + "}");
            return true;
        }

        private static bool TryRemapExactSiegeLocalMissionObjectIdMessage(
            object message,
            string missionObjectIdMemberName,
            SiegeMissionObjectIdBridgeTarget target,
            string messageName)
        {
            if (message == null || string.IsNullOrWhiteSpace(missionObjectIdMemberName))
                return false;

            Mission mission = Mission.Current;
            if (!SiegeMissionObjectIdBridge.IsExactSiegeClientContext(mission))
                return false;

            if (!TryGetMissionObjectIdMemberValue(
                    message,
                    missionObjectIdMemberName,
                    out MissionObjectId localMissionObjectId,
                    out string readDiagnostics))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    MissionObjectId.Invalid,
                    localMissionObjectId,
                    "reverse-read-failed",
                    readDiagnostics);
                return false;
            }

            if (!SiegeMissionObjectIdBridge.TryTranslateLocalMissionObjectId(
                    mission,
                    localMissionObjectId,
                    target,
                    out MissionObjectId serverMissionObjectId,
                    out string bridgeDiagnostics))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    localMissionObjectId,
                    "reverse-not-mapped",
                    bridgeDiagnostics);
                return false;
            }

            if (GetMissionObjectIdValue(serverMissionObjectId) == GetMissionObjectIdValue(localMissionObjectId))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    localMissionObjectId,
                    "reverse-mapped-noop",
                    "Bridge={" + bridgeDiagnostics + "}");
                return true;
            }

            if (!TrySetMissionObjectIdMemberValue(
                    message,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    out string writeDiagnostics))
            {
                TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                    messageName,
                    missionObjectIdMemberName,
                    serverMissionObjectId,
                    localMissionObjectId,
                    "reverse-write-failed",
                    writeDiagnostics + " Bridge={" + bridgeDiagnostics + "}");
                return false;
            }

            TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
                messageName,
                missionObjectIdMemberName,
                serverMissionObjectId,
                localMissionObjectId,
                "reverse-remapped",
                "Bridge={" + bridgeDiagnostics + "}");
            return true;
        }

        private static bool TryGetMissionObjectIdMemberValue(
            object message,
            string memberName,
            out MissionObjectId missionObjectId,
            out string diagnostics)
        {
            missionObjectId = MissionObjectId.Invalid;
            diagnostics = string.Empty;
            if (message == null || string.IsNullOrWhiteSpace(memberName))
            {
                diagnostics = "invalid-arguments";
                return false;
            }

            Type messageType = message.GetType();
            PropertyInfo property = messageType.GetProperty(
                memberName,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            if (property != null &&
                property.PropertyType == typeof(MissionObjectId) &&
                property.GetIndexParameters().Length == 0)
            {
                try
                {
                    missionObjectId = (MissionObjectId)property.GetValue(message, null);
                    diagnostics = "property:" + property.Name;
                    return true;
                }
                catch (Exception ex)
                {
                    diagnostics = "property-exception:" + ex.GetType().Name + ":" + ex.Message;
                    return false;
                }
            }

            FieldInfo field = TryResolveMissionObjectIdField(messageType, memberName);
            if (field != null)
            {
                try
                {
                    missionObjectId = (MissionObjectId)field.GetValue(message);
                    diagnostics = "field:" + field.Name;
                    return true;
                }
                catch (Exception ex)
                {
                    diagnostics = "field-exception:" + ex.GetType().Name + ":" + ex.Message;
                    return false;
                }
            }

            diagnostics = "member-not-found Type=" + messageType.FullName + " Member=" + memberName;
            return false;
        }

        private static bool TrySetMissionObjectIdMemberValue(
            object message,
            string memberName,
            MissionObjectId missionObjectId,
            out string diagnostics)
        {
            diagnostics = string.Empty;
            if (message == null || string.IsNullOrWhiteSpace(memberName))
            {
                diagnostics = "invalid-arguments";
                return false;
            }

            Type messageType = message.GetType();
            PropertyInfo property = messageType.GetProperty(
                memberName,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            MethodInfo setter = property?.GetSetMethod(nonPublic: true);
            if (property != null &&
                property.PropertyType == typeof(MissionObjectId) &&
                property.GetIndexParameters().Length == 0 &&
                setter != null)
            {
                try
                {
                    setter.Invoke(message, new object[] { missionObjectId });
                    diagnostics = "property-setter:" + property.Name;
                    return true;
                }
                catch (Exception ex)
                {
                    diagnostics = "property-setter-exception:" + ex.GetType().Name + ":" + ex.Message;
                }
            }

            FieldInfo field = TryResolveMissionObjectIdField(messageType, memberName);
            if (field != null)
            {
                try
                {
                    field.SetValue(message, missionObjectId);
                    diagnostics = "field:" + field.Name;
                    return true;
                }
                catch (Exception ex)
                {
                    diagnostics = AppendExactSiegeMissionObjectIdBridgeDetail(
                        diagnostics,
                        "field-exception:" + ex.GetType().Name + ":" + ex.Message);
                    return false;
                }
            }

            diagnostics = AppendExactSiegeMissionObjectIdBridgeDetail(
                diagnostics,
                "member-not-found Type=" + messageType.FullName + " Member=" + memberName);
            return false;
        }

        private static FieldInfo TryResolveMissionObjectIdField(Type messageType, string memberName)
        {
            if (messageType == null || string.IsNullOrWhiteSpace(memberName))
                return null;

            FieldInfo field = messageType.GetField(
                memberName,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            if (field != null && field.FieldType == typeof(MissionObjectId))
                return field;

            field = messageType.GetField(
                "<" + memberName + ">k__BackingField",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            return field != null && field.FieldType == typeof(MissionObjectId)
                ? field
                : null;
        }

        private static string AppendExactSiegeMissionObjectIdBridgeDetail(string current, string detail)
        {
            if (string.IsNullOrWhiteSpace(current))
                return detail ?? string.Empty;

            if (string.IsNullOrWhiteSpace(detail))
                return current;

            return current + " " + detail;
        }

        private static void TryLogExactSiegeMissionObjectIdBridgeDiagnostic(
            string messageName,
            string memberName,
            MissionObjectId serverMissionObjectId,
            MissionObjectId localMissionObjectId,
            string stage,
            string detail)
        {
            if (!ExperimentalFeatures.EnableExactSiegeMissionObjectSyncDiagnostics)
                return;

            string diagnosticKey =
                "id-bridge|" +
                (messageName ?? "unknown") + "|" +
                (memberName ?? "unknown") + "|" +
                GetMissionObjectIdValue(serverMissionObjectId) + "|" +
                GetMissionObjectIdValue(localMissionObjectId) + "|" +
                (stage ?? "unknown");

            int remainingBudgetAfterReserve;
            lock (ExactSiegeMissionObjectSyncDiagnosticsLock)
            {
                if (!LoggedExactSiegeMissionObjectSyncDiagnosticKeys.Add(diagnosticKey))
                    return;

                if (_remainingExactSiegeMissionObjectSyncDiagnosticBudget <= 0)
                {
                    if (!_exactSiegeMissionObjectSyncDiagnosticBudgetExhaustedLogged)
                    {
                        _exactSiegeMissionObjectSyncDiagnosticBudgetExhaustedLogged = true;
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: exact siege mission object id bridge diagnostics budget exhausted.");
                    }

                    return;
                }

                remainingBudgetAfterReserve = --_remainingExactSiegeMissionObjectSyncDiagnosticBudget;
            }

            ModLogger.Info(
                "BattleMapSpawnHandoffPatch: exact siege mission object id bridge diagnostic. " +
                "Message=" + (messageName ?? "unknown") +
                " Member=" + (memberName ?? "unknown") +
                " Stage=" + (stage ?? "unknown") +
                " ServerMissionObjectId=" + GetMissionObjectIdValue(serverMissionObjectId) +
                " LocalMissionObjectId=" + GetMissionObjectIdValue(localMissionObjectId) +
                " Detail=" + (detail ?? string.Empty) +
                " RemainingBudget=" + remainingBudgetAfterReserve);
        }

        private static bool IsValidMissionObjectId(MissionObjectId missionObjectId)
        {
            return GetMissionObjectIdValue(missionObjectId) != GetMissionObjectIdValue(MissionObjectId.Invalid);
        }

        private static MissionObject TryGetLocalMissionObject(MissionObjectId missionObjectId)
        {
            if (!IsValidMissionObjectId(missionObjectId))
                return null;

            return Mission.MissionNetworkHelper.GetMissionObjectFromMissionObjectId(missionObjectId);
        }

        private static bool ShouldSuppressUnmappedExactSiegeMissionObjectVisibility(
            Mission mission,
            SetMissionObjectVisibility setMissionObjectVisibility,
            out string reason)
        {
            reason = string.Empty;
            if (mission == null || setMissionObjectVisibility == null)
            {
                reason = "skip-null";
                return false;
            }

            if (!SiegeMissionObjectIdBridge.IsExactSiegeClientContext(mission))
            {
                reason = "skip-context";
                return false;
            }

            MissionObject localMissionObject;
            try
            {
                localMissionObject = TryGetLocalMissionObject(setMissionObjectVisibility.MissionObjectId);
            }
            catch (Exception ex)
            {
                reason = "skip-lookup-exception:" + ex.GetType().Name + ":" + ex.Message;
                return false;
            }

            if (localMissionObject == null)
            {
                reason = "skip-local-object-missing";
                return false;
            }

            if (localMissionObject is DeploymentPoint ||
                localMissionObject is SiegeWeapon ||
                localMissionObject is UsableMachine)
            {
                reason = "skip-siege-object Actual=" + localMissionObject.GetType().FullName;
                return false;
            }

            reason =
                "suppress-local-id-collision MissionObjectId=" +
                GetMissionObjectIdValue(setMissionObjectVisibility.MissionObjectId) +
                " Visible=" + setMissionObjectVisibility.Visible +
                " Actual=" + localMissionObject.GetType().FullName;
            return true;
        }

        private static bool ShouldSuppressUnmappedExactSiegeSynchronizeMissionObject(
            Mission mission,
            SynchronizeMissionObject synchronizeMissionObject,
            out string reason)
        {
            reason = string.Empty;
            if (mission == null || synchronizeMissionObject == null)
            {
                reason = "skip-null";
                return false;
            }

            if (!SiegeMissionObjectIdBridge.IsExactSiegeClientContext(mission))
            {
                reason = "skip-context";
                return false;
            }

            MissionObject localMissionObject = null;
            try
            {
                localMissionObject = TryGetLocalMissionObject(synchronizeMissionObject.MissionObjectId);
            }
            catch (Exception ex)
            {
                reason = "suppress-lookup-exception:" + ex.GetType().Name + ":" + ex.Message;
                return true;
            }

            reason =
                "suppress-unmapped-synchronize MissionObjectId=" +
                GetMissionObjectIdValue(synchronizeMissionObject.MissionObjectId) +
                " RecordTypeIndex=" + synchronizeMissionObject.RecordTypeIndex +
                " LocalActual=" + (localMissionObject?.GetType().FullName ?? "null");
            return true;
        }

        private static SpawnedItemEntity TryGetLocalSpawnedItemEntity(MissionObjectId missionObjectId)
        {
            return TryGetLocalMissionObject(missionObjectId) as SpawnedItemEntity;
        }

        private static void TryLogExactSiegeMissionObjectSyncDiagnostic(
            Mission mission,
            SynchronizeMissionObject synchronizeMissionObject,
            string stage,
            Exception exception = null,
            string extraDetails = null)
        {
            if (!ExperimentalFeatures.EnableExactSiegeMissionObjectSyncDiagnostics ||
                mission == null ||
                synchronizeMissionObject == null)
            {
                return;
            }

            BattleScenarioContextMessage scenarioContext =
                BattleSnapshotRuntimeState.GetCurrent()?.ScenarioContext ??
                BattleSnapshotRuntimeState.GetState()?.ScenarioContext;
            if (!SceneRuntimeClassifier.IsExactCampaignBattleScene(mission.SceneName ?? string.Empty) ||
                !ExactCampaignSiegeAssaultWithDeploymentRuntime.IsExactSiegeWithDeploymentScenario(scenarioContext))
            {
                return;
            }

            int missionObjectIdValue = GetMissionObjectIdValue(synchronizeMissionObject.MissionObjectId);
            string diagnosticKey =
                (stage ?? "unknown") + "|" +
                missionObjectIdValue + "|" +
                (exception?.GetType().FullName ?? "no-exception");

            int remainingBudgetAfterReserve;
            lock (ExactSiegeMissionObjectSyncDiagnosticsLock)
            {
                if (!LoggedExactSiegeMissionObjectSyncDiagnosticKeys.Add(diagnosticKey))
                    return;

                if (_remainingExactSiegeMissionObjectSyncDiagnosticBudget <= 0)
                {
                    if (!_exactSiegeMissionObjectSyncDiagnosticBudgetExhaustedLogged)
                    {
                        _exactSiegeMissionObjectSyncDiagnosticBudgetExhaustedLogged = true;
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: exact siege SynchronizeMissionObject diagnostics budget exhausted. " +
                            "Budget=" + ExactSiegeMissionObjectSyncDiagnosticBudget +
                            " Scene=" + (mission.SceneName ?? "null") + ".");
                    }

                    return;
                }

                _remainingExactSiegeMissionObjectSyncDiagnosticBudget--;
                remainingBudgetAfterReserve = _remainingExactSiegeMissionObjectSyncDiagnosticBudget;
            }

            MissionObject localMissionObject = TryGetLocalMissionObject(synchronizeMissionObject.MissionObjectId);
            string localMissionObjectSummary = BuildLocalMissionObjectDiagnosticSummary(localMissionObject);
            string contractSummary = BuildExactSiegeClientContractDiagnosticSummary(mission, scenarioContext);
            string exceptionSummary = exception == null
                ? "none"
                : exception.GetType().FullName + ":" + exception.Message;

            ModLogger.Info(
                "BattleMapSpawnHandoffPatch: exact siege SynchronizeMissionObject diagnostic. " +
                "Stage=" + (stage ?? "unknown") +
                " MissionObjectId=" + missionObjectIdValue +
                " MissionState=" + mission.CurrentState +
                " MissionMode=" + mission.Mode +
                " LocalMissionObject={" + localMissionObjectSummary + "}" +
                " Contract={" + contractSummary + "}" +
                " Exception=" + exceptionSummary +
                " Extra={" + (extraDetails ?? "none") + "}" +
                " RemainingBudget=" + remainingBudgetAfterReserve + ".");
        }

        private static string BuildExactSiegeClientContractDiagnosticSummary(
            Mission mission,
            BattleScenarioContextMessage scenarioContext)
        {
            bool hasSiegePreparationHandler = mission.GetMissionBehavior<SiegeMissionPreparationHandler>() != null;
            bool hasSiegeEnginesLogic = mission.GetMissionBehavior<MissionSiegeEnginesLogic>() != null;
            bool hasSiegeDeploymentHandler = mission.GetMissionBehavior<SiegeDeploymentHandler>() != null;
            bool hasSiegeDeploymentController = mission.GetMissionBehavior<SiegeDeploymentMissionController>() != null;
            bool requireDeploymentBridge =
                ExactCampaignSiegeAssaultWithDeploymentRuntime.ShouldInjectWrappedBattleClientDeploymentBehaviors(
                    mission,
                    scenarioContext,
                    out string deploymentBridgePolicy);

            return
                "RequireDeploymentBridge=" + requireDeploymentBridge +
                " DeploymentBridgePolicy=" + (deploymentBridgePolicy ?? "unknown") +
                " HasSiegePreparationHandler=" + hasSiegePreparationHandler +
                " HasSiegeEnginesLogic=" + hasSiegeEnginesLogic +
                " HasSiegeDeploymentHandler=" + hasSiegeDeploymentHandler +
                " HasSiegeDeploymentController=" + hasSiegeDeploymentController;
        }

        private static string BuildLocalMissionObjectDiagnosticSummary(MissionObject missionObject)
        {
            if (missionObject == null)
                return "null";

            string entityName = "null";
            try
            {
                WeakGameEntity gameEntity = missionObject.GameEntity;
                entityName = gameEntity.IsValid
                    ? (gameEntity.Name ?? "null")
                    : "invalid";
            }
            catch (Exception ex)
            {
                entityName = "unavailable:" + ex.GetType().Name;
            }

            return
                "Type=" + missionObject.GetType().FullName +
                " RuntimeId=" + GetMissionObjectIdValue(missionObject.Id) +
                " Entity=" + entityName;
        }

        private static void TryTraceClientProjectileLaunchDiagnostics(Mission mission, CreateMissile createMissile, Agent shooterAgent)
        {
            if (!ExperimentalFeatures.EnableExactCreateAgentCorridorDiagnostics ||
                mission == null ||
                createMissile == null ||
                shooterAgent == null ||
                shooterAgent.IsMount)
            {
                return;
            }

            try
            {
                MissionWeapon launchWeapon = ResolveCreateMissileWeapon(createMissile, shooterAgent);
                if (!IsThrownProjectileLaunchWeapon(launchWeapon))
                    return;

                if (!IsControlledHeroProjectileLaunchDiagnosticsTarget(shooterAgent, out string entryId, out RosterEntryState entryState, out string targetReason))
                    return;

                string key =
                    "client|" +
                    createMissile.MissileIndex + "|" +
                    shooterAgent.Index + "|" +
                    createMissile.WeaponIndex + "|" +
                    (launchWeapon.Item?.StringId ?? "null") + "|" +
                    FormatVec3(createMissile.Position) + "|" +
                    FormatFloat(createMissile.Speed);
                if (LoggedProjectileLaunchDiagnosticKeys.Count >= ProjectileLaunchDiagnosticBudget ||
                    !LoggedProjectileLaunchDiagnosticKeys.Add(key))
                {
                    return;
                }

                string details = BuildProjectileLaunchDiagnosticDetails(
                    "client-create-missile",
                    mission,
                    shooterAgent,
                    entryId,
                    entryState,
                    targetReason,
                    createMissile.MissileIndex,
                    createMissile.WeaponIndex,
                    launchWeapon,
                    createMissile.Position,
                    createMissile.Direction,
                    createMissile.Speed,
                    createMissile.Orientation,
                    createMissile.HasRigidBody,
                    createMissile.IsPrimaryWeaponShot,
                    createMissile.MissionObjectToIgnoreId);

                ModLogger.Info("BattleMapSpawnHandoffPatch: projectile launch diagnostics. " + details);
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent("projectile-launch-client-create-missile", details);
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: projectile launch diagnostics failed open: " + ex.Message);
            }
        }

        private static MissionWeapon ResolveCreateMissileWeapon(CreateMissile createMissile, Agent shooterAgent)
        {
            if (createMissile != null &&
                createMissile.WeaponIndex != EquipmentIndex.None &&
                shooterAgent?.Equipment != null)
            {
                try
                {
                    return shooterAgent.Equipment[createMissile.WeaponIndex];
                }
                catch
                {
                }
            }

            return createMissile?.Weapon ?? MissionWeapon.Invalid;
        }

        private static bool IsControlledHeroProjectileLaunchDiagnosticsTarget(
            Agent agent,
            out string entryId,
            out RosterEntryState entryState,
            out string reason)
        {
            entryId = null;
            entryState = null;
            reason = "not-controlled-hero";

            if (agent == null || agent.IsMount)
                return false;

            bool localControlled = IsLocalMissionPeerControlledAgent(agent) ||
                                   ReferenceEquals(Agent.Main, agent) ||
                                   ReferenceEquals(Mission.Current?.MainAgent, agent);
            bool resolvedEntry =
                CoopMissionSpawnLogic.TryResolveAuthoritativeTrackedEntryId(agent, out entryId) ||
                CoopMissionSpawnLogic.TryResolveSelectableEntryId(agent, out entryId);
            if (resolvedEntry)
                entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);

            bool heroEntry = IsProjectileLaunchHeroEntry(entryState);
            if (!localControlled && !heroEntry)
                return false;

            reason =
                (localControlled ? "local-controlled" : "remote-or-server-observed") +
                "|HeroEntry=" + heroEntry +
                "|EntryResolved=" + resolvedEntry;
            return true;
        }

        private static bool IsProjectileLaunchHeroEntry(RosterEntryState entryState)
        {
            return entryState != null &&
                   (entryState.IsHero ||
                    !string.IsNullOrWhiteSpace(entryState.HeroId) ||
                    string.Equals(entryState.OriginalCharacterId, "main_hero", StringComparison.OrdinalIgnoreCase));
        }

        private static bool IsThrownProjectileLaunchWeapon(MissionWeapon weapon)
        {
            try
            {
                if (weapon.IsEmpty)
                    return false;

                ItemObject item = weapon.Item;
                if (item?.ItemType == ItemObject.ItemTypeEnum.Thrown)
                    return true;

                WeaponComponentData usage = weapon.CurrentUsageItem ?? item?.PrimaryWeapon;
                if (usage == null)
                    return false;

                return usage.RelevantSkill == DefaultSkills.Throwing ||
                       usage.WeaponClass == WeaponClass.Javelin ||
                       usage.WeaponClass == WeaponClass.ThrowingAxe ||
                       usage.WeaponClass == WeaponClass.ThrowingKnife ||
                       usage.WeaponClass == WeaponClass.Stone ||
                       usage.WeaponClass == WeaponClass.SlingStone;
            }
            catch
            {
                return false;
            }
        }

        private static string BuildProjectileLaunchDiagnosticDetails(
            string stage,
            Mission mission,
            Agent shooterAgent,
            string entryId,
            RosterEntryState entryState,
            string targetReason,
            int missileIndex,
            EquipmentIndex weaponIndex,
            MissionWeapon launchWeapon,
            Vec3 position,
            Vec3 direction,
            float speed,
            Mat3 orientation,
            bool hasRigidBody,
            bool isPrimaryWeaponShot,
            MissionObjectId missionObjectToIgnoreId)
        {
            Vec3 agentPosition = shooterAgent?.Position ?? Vec3.Zero;
            Vec3 offset = position - agentPosition;
            Vec3 lookDirection = ResolveAgentLookDirection(shooterAgent);
            Vec3 normalizedDirection = NormalizeVec3(direction);
            float offsetLookDot = DotSafe(offset, lookDirection);
            float directionLookDot = DotSafe(normalizedDirection, lookDirection);
            float offsetLength = SafeLength(offset);
            bool startsBehindLook = offsetLookDot < -0.10f;

            EquipmentIndex primaryWieldedIndex = EquipmentIndex.None;
            EquipmentIndex offhandWieldedIndex = EquipmentIndex.None;
            string missionWeapons = "(unavailable)";
            string spawnWeapons = "(unavailable)";
            string currentWeaponOffset = "(unavailable)";
            try
            {
                primaryWieldedIndex = shooterAgent.GetPrimaryWieldedItemIndex();
                offhandWieldedIndex = shooterAgent.GetOffhandWieldedItemIndex();
                missionWeapons = BuildMissionEquipmentWeaponSummary(shooterAgent.Equipment);
                spawnWeapons = BuildEquipmentSummary(
                    shooterAgent.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);
                currentWeaponOffset = FormatVec3(shooterAgent.GetCurWeaponOffset());
            }
            catch
            {
            }

            WeaponComponentData usage = null;
            try
            {
                usage = launchWeapon.CurrentUsageItem ?? launchWeapon.Item?.PrimaryWeapon;
            }
            catch
            {
            }

            return
                "Stage=" + stage +
                " Scene=" + (mission?.SceneName ?? "null") +
                " MissileIndex=" + missileIndex +
                " AgentIndex=" + (shooterAgent?.Index ?? -1) +
                " EntryId=" + (entryId ?? "null") +
                " TargetReason=" + (targetReason ?? "unknown") +
                " EntryHero=" + (entryState?.IsHero ?? false) +
                " OriginalCharacterId=" + (entryState?.OriginalCharacterId ?? "null") +
                " HeroId=" + (entryState?.HeroId ?? "null") +
                " CharacterId=" + (shooterAgent?.Character?.StringId ?? "null") +
                " Controller=" + (shooterAgent?.Controller.ToString() ?? "null") +
                " HasMount=" + (shooterAgent?.HasMount ?? false) +
                " MountAgentIndex=" + (shooterAgent?.MountAgent?.Index ?? -1) +
                " WeaponIndex=" + weaponIndex +
                " PrimaryWieldedIndex=" + primaryWieldedIndex +
                " OffhandWieldedIndex=" + offhandWieldedIndex +
                " LaunchItem=" + (launchWeapon.Item?.StringId ?? "null") +
                " LaunchItemType=" + (launchWeapon.Item?.ItemType.ToString() ?? "null") +
                " LaunchUsage=" + (usage?.WeaponClass.ToString() ?? "null") +
                " LaunchRelevantSkill=" + (usage?.RelevantSkill?.StringId ?? "null") +
                " HasRigidBody=" + hasRigidBody +
                " IsPrimaryWeaponShot=" + isPrimaryWeaponShot +
                " MissionObjectToIgnoreId=" + GetMissionObjectIdValue(missionObjectToIgnoreId) +
                " AgentPosition=" + FormatVec3(agentPosition) +
                " AgentLook=" + FormatVec3(lookDirection) +
                " MissilePosition=" + FormatVec3(position) +
                " MissileDirection=" + FormatVec3(normalizedDirection) +
                " MissileSpeed=" + FormatFloat(speed) +
                " Offset=" + FormatVec3(offset) +
                " OffsetLength=" + FormatFloat(offsetLength) +
                " OffsetLookDot=" + FormatFloat(offsetLookDot) +
                " DirectionLookDot=" + FormatFloat(directionLookDot) +
                " StartsBehindLook=" + startsBehindLook +
                " OrientationF=" + FormatVec3(orientation.f) +
                " CurWeaponOffset=" + currentWeaponOffset +
                " MissionWeapons={" + missionWeapons + "}" +
                " SpawnWeapons={" + spawnWeapons + "}";
        }

        private static Vec3 ResolveAgentLookDirection(Agent agent)
        {
            if (agent == null)
                return Vec3.Forward;

            try
            {
                Vec3 look = agent.LookDirection;
                if (look.LengthSquared > 0.0001f)
                    return NormalizeVec3(look);
            }
            catch
            {
            }

            try
            {
                Vec3 frameForward = agent.Frame.rotation.f;
                if (frameForward.LengthSquared > 0.0001f)
                    return NormalizeVec3(frameForward);
            }
            catch
            {
            }

            return Vec3.Forward;
        }

        private static Vec3 NormalizeVec3(Vec3 value)
        {
            try
            {
                if (value.LengthSquared <= 0.0001f)
                    return Vec3.Zero;

                value.Normalize();
                return value;
            }
            catch
            {
                return Vec3.Zero;
            }
        }

        private static float DotSafe(Vec3 left, Vec3 right)
        {
            try
            {
                return Vec3.DotProduct(left, right);
            }
            catch
            {
                return 0f;
            }
        }

        private static float SafeLength(Vec3 value)
        {
            try
            {
                return value.Length;
            }
            catch
            {
                return 0f;
            }
        }

        private static string FormatVec3(Vec3 value)
        {
            return "(" +
                   FormatFloat(value.x) + "," +
                   FormatFloat(value.y) + "," +
                   FormatFloat(value.z) + ")";
        }

        private static string FormatFloat(float value)
        {
            return value.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture);
        }

        private static bool MissionHasLocalMissile(int missileIndex)
        {
            if (missileIndex < 0)
                return false;

            Mission mission = Mission.Current;
            if (mission == null || MissionMissilesDictionaryField == null)
                return false;

            try
            {
                object missilesDictionary = MissionMissilesDictionaryField.GetValue(mission);
                if (missilesDictionary is IDictionary dictionary)
                    return dictionary.Contains(missileIndex);
            }
            catch
            {
            }

            return false;
        }

        private static bool TryDeferExactSiegeAmbushClientCreateMissileForIndexReuse(
            Mission mission,
            CreateMissile createMissile,
            bool registerDeferredPayload)
        {
            if (mission == null ||
                createMissile == null ||
                createMissile.MissileIndex < 0 ||
                !GameNetwork.IsClient)
            {
                return false;
            }

            BattleScenarioContextMessage scenarioContext =
                BattleSnapshotRuntimeState.GetScenarioContext() ??
                BattleSnapshotRuntimeState.GetCurrent()?.ScenarioContext ??
                BattleSnapshotRuntimeState.GetState()?.ScenarioContext;
            if (!SiegeAmbushScenarioContract.IsSiegeAmbushScenario(scenarioContext))
                return false;

            int missileIndex = createMissile.MissileIndex;
            if (!MissionHasLocalMissile(missileIndex))
            {
                lock (ClientMissileIndicesAwaitingReuseRemoval)
                {
                    ClientMissileIndicesAwaitingReuseRemoval.Remove(missileIndex);
                }

                return false;
            }

            RemoveDeferredClientMissileCollisionPayloadsForIndex(missileIndex);
            if (registerDeferredPayload)
            {
                RegisterDeferredClientCreateMissilePayload(
                    createMissile,
                    "reused-index-awaiting-local-removal");
            }

            bool shouldRequestRemoval;
            lock (ClientMissileIndicesAwaitingReuseRemoval)
            {
                shouldRequestRemoval = ClientMissileIndicesAwaitingReuseRemoval.Add(missileIndex);
            }

            if (shouldRequestRemoval)
            {
                try
                {
                    mission.RemoveMissileAsClient(missileIndex);
                    if (ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics)
                    {
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: deferred exact SiegeAmbush CreateMissile " +
                            "until reused local missile index is removed. " +
                            "MissileIndex=" + missileIndex +
                            " AgentIndex=" + createMissile.AgentIndex);
                    }
                }
                catch (Exception ex)
                {
                    lock (ClientMissileIndicesAwaitingReuseRemoval)
                    {
                        ClientMissileIndicesAwaitingReuseRemoval.Remove(missileIndex);
                    }

                    if (ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics)
                    {
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: exact SiegeAmbush reused missile removal " +
                            "will be retried. MissileIndex=" + missileIndex +
                            " Error=" + ex.Message);
                    }
                }
            }

            return true;
        }

        private static bool TryGetLocalMissileShooterAgentIndex(
            Mission mission,
            int missileIndex,
            out int shooterAgentIndex)
        {
            shooterAgentIndex = -1;
            if (mission == null ||
                missileIndex < 0 ||
                MissionMissilesDictionaryField == null)
            {
                return false;
            }

            try
            {
                if (!(MissionMissilesDictionaryField.GetValue(mission) is IDictionary missilesDictionary))
                    return false;

                object missile = missilesDictionary[missileIndex];
                if (missile == null)
                    return false;

                PropertyInfo shooterAgentProperty = missile.GetType().GetProperty(
                    "ShooterAgent",
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                if (shooterAgentProperty == null)
                    return false;

                Agent shooterAgent = shooterAgentProperty.GetValue(missile) as Agent;
                shooterAgentIndex = shooterAgent?.Index ?? -1;
                return true;
            }
            catch
            {
                shooterAgentIndex = -1;
                return false;
            }
        }

        private static bool DoesLocalMissileMatchCollisionShooter(
            Mission mission,
            HandleMissileCollisionReaction message,
            out int localShooterAgentIndex)
        {
            localShooterAgentIndex = -1;
            return message != null &&
                   TryGetLocalMissileShooterAgentIndex(
                       mission,
                       message.MissileIndex,
                       out localShooterAgentIndex) &&
                   localShooterAgentIndex == message.AttackerAgentIndex;
        }

        private static bool TryDeferClientThrownProjectileBecomeInvisibleForVisualGrace(
            Mission mission,
            HandleMissileCollisionReaction handleMissileCollisionReaction)
        {
            if (_clientProjectileVisualGraceReplayDepth > 0 ||
                mission == null ||
                handleMissileCollisionReaction == null ||
                handleMissileCollisionReaction.CollisionReaction != Mission.MissileCollisionReaction.BecomeInvisible ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return false;
            }

            try
            {
                if (!TryResolveMissionMissileItem(
                        mission,
                        handleMissileCollisionReaction.MissileIndex,
                        out ItemObject missileItem) ||
                    !IsClientThrownProjectileVisualGraceItem(missileItem))
                {
                    return false;
                }

                Agent attackerAgent = handleMissileCollisionReaction.AttackerAgentIndex >= 0
                    ? Mission.MissionNetworkHelper.GetAgentFromIndex(
                        handleMissileCollisionReaction.AttackerAgentIndex,
                        canBeNull: true)
                    : null;
                if (!IsLocalProjectileVisualGraceAttacker(attackerAgent))
                    return false;

                if (!TryResolveUnsafeClientProjectileVisualGraceCollisionReason(
                        handleMissileCollisionReaction,
                        out string collisionReason))
                {
                    return false;
                }

                DateTime holdUntilUtc = DateTime.UtcNow + ClientThrownProjectileBecomeInvisibleVisualGrace;
                RegisterDeferredClientHandleMissileCollisionReactionPayload(
                    handleMissileCollisionReaction,
                    ClientThrownProjectileVisualGraceDeferralReasonPrefix + ":" + collisionReason,
                    holdUntilUtc,
                    missileItem?.StringId);

                string logKey =
                    handleMissileCollisionReaction.MissileIndex + "|" +
                    handleMissileCollisionReaction.AttackerAgentIndex + "|" +
                    handleMissileCollisionReaction.AttachedAgentIndex + "|" +
                    (missileItem?.StringId ?? "null") + "|" +
                    collisionReason;
                if (LoggedClientProjectileVisualGraceKeys.Count < ClientProjectileVisualGraceDiagnosticBudget &&
                    LoggedClientProjectileVisualGraceKeys.Add(logKey))
                {
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: deferred client thrown projectile BecomeInvisible for visual grace. " +
                        "MissileIndex=" + handleMissileCollisionReaction.MissileIndex +
                        " MissileItem=" + (missileItem?.StringId ?? "null") +
                        " AttackerAgentIndex=" + handleMissileCollisionReaction.AttackerAgentIndex +
                        " AttachedAgentIndex=" + handleMissileCollisionReaction.AttachedAgentIndex +
                        " AttachedToShield=" + handleMissileCollisionReaction.AttachedToShield +
                        " AttachedBoneIndex=" + handleMissileCollisionReaction.AttachedBoneIndex +
                        " CollisionReason=" + collisionReason +
                        " HoldMilliseconds=" + (int)ClientThrownProjectileBecomeInvisibleVisualGrace.TotalMilliseconds);
                }

                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: client thrown projectile visual grace failed open: " + ex.Message);
                return false;
            }
        }

        private static bool IsDeferredClientThrownProjectileVisualGracePayload(
            DeferredClientHandleMissileCollisionReactionPayload deferredPayload)
        {
            return deferredPayload?.DeferralReason != null &&
                   deferredPayload.DeferralReason.StartsWith(
                       ClientThrownProjectileVisualGraceDeferralReasonPrefix,
                       StringComparison.Ordinal);
        }

        private static bool IsDeferredClientSiegeEngineProjectileVisualGracePayload(
            DeferredClientHandleMissileCollisionReactionPayload deferredPayload)
        {
            return deferredPayload?.DeferralReason != null &&
                   deferredPayload.DeferralReason.StartsWith(
                       ClientSiegeEngineProjectileVisualGraceDeferralReasonPrefix,
                       StringComparison.Ordinal);
        }

        private static bool IsDeferredClientProjectileVisualGracePayload(
            DeferredClientHandleMissileCollisionReactionPayload deferredPayload)
        {
            return IsDeferredClientThrownProjectileVisualGracePayload(deferredPayload) ||
                   IsDeferredClientSiegeEngineProjectileVisualGracePayload(deferredPayload);
        }

        private static string GetDeferredClientProjectileVisualGraceKind(
            DeferredClientHandleMissileCollisionReactionPayload deferredPayload)
        {
            if (IsDeferredClientSiegeEngineProjectileVisualGracePayload(deferredPayload))
                return "siege-engine projectile";

            if (IsDeferredClientThrownProjectileVisualGracePayload(deferredPayload))
                return "thrown projectile";

            return "projectile";
        }

        private static string NormalizeMissileItemId(string itemId)
        {
            return string.IsNullOrWhiteSpace(itemId)
                ? null
                : itemId.Trim();
        }

        private static bool ShouldDropDeferredClientProjectileVisualGracePayloadBeforeReplay(
            Mission mission,
            DeferredClientHandleMissileCollisionReactionPayload deferredPayload,
            DateTime nowUtc)
        {
            if (!IsDeferredClientProjectileVisualGracePayload(deferredPayload))
                return false;

            if (IsDeferredClientSiegeEngineProjectileVisualGracePayload(deferredPayload) &&
                deferredPayload.DeferredUtc != DateTime.MinValue &&
                nowUtc - deferredPayload.DeferredUtc > ClientSiegeEngineProjectileVisualGraceMaxAge)
            {
                return true;
            }

            string expectedItemId = NormalizeMissileItemId(deferredPayload.MissileItemId);
            if (expectedItemId == null)
                return false;

            HandleMissileCollisionReaction message = deferredPayload.Message;
            if (message == null)
                return true;

            if (!TryResolveMissionMissileItem(mission, message.MissileIndex, out ItemObject currentMissileItem))
                return true;

            string currentItemId = NormalizeMissileItemId(currentMissileItem?.StringId);
            return !string.Equals(expectedItemId, currentItemId, StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsLocalProjectileVisualGraceAttacker(Agent attackerAgent)
        {
            if (attackerAgent == null || attackerAgent.IsMount)
                return false;

            return IsLocalMissionPeerControlledAgent(attackerAgent) ||
                   ReferenceEquals(Agent.Main, attackerAgent) ||
                   ReferenceEquals(Mission.Current?.MainAgent, attackerAgent);
        }

        private static bool TryResolveUnsafeClientProjectileVisualGraceCollisionReason(
            HandleMissileCollisionReaction handleMissileCollisionReaction,
            out string reason)
        {
            reason = "unknown";
            if (handleMissileCollisionReaction == null)
                return false;

            if (handleMissileCollisionReaction.AttachedAgentIndex < 0)
            {
                reason = "no-attached-agent";
                return true;
            }

            Agent attachedAgent = Mission.MissionNetworkHelper.GetAgentFromIndex(
                handleMissileCollisionReaction.AttachedAgentIndex,
                canBeNull: true);
            if (attachedAgent == null)
            {
                reason = "attached-agent-missing";
                return true;
            }

            bool attachedAgentActive;
            bool attachedAgentIsMount;
            try
            {
                attachedAgentActive = attachedAgent.IsActive();
                attachedAgentIsMount = attachedAgent.IsMount;
            }
            catch
            {
                reason = "attached-agent-state-unavailable";
                return true;
            }

            if (!attachedAgentActive)
            {
                reason = "attached-agent-inactive";
                return true;
            }

            if (attachedAgentIsMount)
            {
                reason = "attached-agent-is-mount";
                return true;
            }

            return false;
        }

        private static bool IsClientThrownProjectileVisualGraceItem(ItemObject item)
        {
            if (item == null || IsBallistaProjectileItem(item))
                return false;

            try
            {
                WeaponComponentData usage = item.PrimaryWeapon;
                if (usage == null)
                    return false;

                return usage.WeaponClass == WeaponClass.Javelin ||
                       usage.WeaponClass == WeaponClass.ThrowingAxe ||
                       usage.WeaponClass == WeaponClass.ThrowingKnife;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryDeferClientSiegeEngineProjectileUnsafeCollisionForVisualGrace(
            Mission mission,
            HandleMissileCollisionReaction handleMissileCollisionReaction)
        {
            if (_clientProjectileVisualGraceReplayDepth > 0 ||
                mission == null ||
                handleMissileCollisionReaction == null ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return false;
            }

            Mission.MissileCollisionReaction originalReaction = handleMissileCollisionReaction.CollisionReaction;
            if (originalReaction != Mission.MissileCollisionReaction.BecomeInvisible &&
                originalReaction != Mission.MissileCollisionReaction.Stick &&
                originalReaction != Mission.MissileCollisionReaction.BounceBack &&
                originalReaction != Mission.MissileCollisionReaction.PassThrough)
            {
                return false;
            }

            try
            {
                if (!TryResolveMissionMissileItem(
                        mission,
                        handleMissileCollisionReaction.MissileIndex,
                        out ItemObject missileItem) ||
                    !IsSiegeEngineProjectileItem(missileItem))
                {
                    return false;
                }

                if (originalReaction == Mission.MissileCollisionReaction.PassThrough &&
                    !IsBallistaProjectileItem(missileItem))
                {
                    return false;
                }

                string collisionReason = ResolveClientSiegeEngineProjectileVisualGraceCollisionReason(
                    handleMissileCollisionReaction,
                    missileItem,
                    originalReaction);
                HandleMissileCollisionReaction deferredMessage =
                    originalReaction == Mission.MissileCollisionReaction.BecomeInvisible
                        ? handleMissileCollisionReaction
                        : CreateBecomeInvisibleMissileCollisionReaction(handleMissileCollisionReaction);
                TimeSpan visualGrace = ResolveClientSiegeEngineProjectileBecomeInvisibleVisualGrace(missileItem);
                DateTime holdUntilUtc = DateTime.UtcNow + visualGrace;
                RemoveDeferredClientSiegeEngineProjectileVisualGracePayloads(
                    handleMissileCollisionReaction.MissileIndex);
                RegisterDeferredClientHandleMissileCollisionReactionPayload(
                    deferredMessage,
                    ClientSiegeEngineProjectileVisualGraceDeferralReasonPrefix + ":" + collisionReason,
                    holdUntilUtc,
                    missileItem?.StringId);

                if (ExperimentalFeatures.EnableExactCreateAgentCorridorDiagnostics)
                {
                    string logKey =
                        handleMissileCollisionReaction.MissileIndex + "|" +
                        handleMissileCollisionReaction.AttackerAgentIndex + "|" +
                        handleMissileCollisionReaction.AttachedAgentIndex + "|" +
                        (missileItem?.StringId ?? "null") + "|" +
                        originalReaction + "|" +
                        collisionReason;
                    if (LoggedClientProjectileVisualGraceKeys.Count < ClientProjectileVisualGraceDiagnosticBudget &&
                        LoggedClientProjectileVisualGraceKeys.Add(logKey))
                    {
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: deferred client siege-engine projectile collision for visual grace. " +
                            "MissileIndex=" + handleMissileCollisionReaction.MissileIndex +
                            " MissileItem=" + (missileItem?.StringId ?? "null") +
                            " OriginalReaction=" + originalReaction +
                            " DeferredReaction=" + deferredMessage.CollisionReaction +
                            " AttackerAgentIndex=" + handleMissileCollisionReaction.AttackerAgentIndex +
                            " AttachedAgentIndex=" + handleMissileCollisionReaction.AttachedAgentIndex +
                            " AttachedToShield=" + handleMissileCollisionReaction.AttachedToShield +
                            " AttachedBoneIndex=" + handleMissileCollisionReaction.AttachedBoneIndex +
                            " CollisionReason=" + collisionReason +
                            " HoldMilliseconds=" + (int)visualGrace.TotalMilliseconds);
                    }
                }

                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: client siege-engine projectile visual grace failed open: " + ex.Message);
                return false;
            }
        }

        private static HandleMissileCollisionReaction CreateBecomeInvisibleMissileCollisionReaction(
            HandleMissileCollisionReaction source)
        {
            return new HandleMissileCollisionReaction(
                source.MissileIndex,
                Mission.MissileCollisionReaction.BecomeInvisible,
                MatrixFrame.Identity,
                isAttachedFrameLocal: false,
                source.AttackerAgentIndex,
                source.AttachedAgentIndex,
                source.AttachedToShield,
                source.AttachedBoneIndex,
                source.AttachedMissionObjectId,
                Vec3.Zero,
                Vec3.Zero,
                forcedSpawnIndex: 0);
        }

        private static string ResolveClientSiegeEngineProjectileVisualGraceCollisionReason(
            HandleMissileCollisionReaction handleMissileCollisionReaction,
            ItemObject missileItem,
            Mission.MissileCollisionReaction originalReaction)
        {
            string itemId = missileItem?.StringId ?? "unknown";
            switch (originalReaction)
            {
                case Mission.MissileCollisionReaction.Stick:
                    return "native-stick-drop-risk:" + itemId;
                case Mission.MissileCollisionReaction.BounceBack:
                    return "native-bounceback-drop-risk:" + itemId;
                case Mission.MissileCollisionReaction.PassThrough:
                    return "ballista-pass-through-visibility-guard:" + itemId;
                case Mission.MissileCollisionReaction.BecomeInvisible:
                    if (handleMissileCollisionReaction.AttachedAgentIndex < 0)
                        return "server-downgraded-no-attached-agent:" + itemId;
                    return "server-downgraded:" + itemId;
                default:
                    return "unknown:" + itemId;
            }
        }

        private static bool ShouldUseServerExactBattleProjectileStickSuppression(Mission mission)
        {
            if (!GameNetwork.IsServer || mission == null)
                return false;

            if (!MissionMultiplayerCoopBattleMode.IsBattleMapSceneName(mission.SceneName))
                return false;

            return BattleSnapshotRuntimeState.GetState() != null;
        }

        private static bool ShouldUseExactSiegeBallistaProjectileGuard(Mission mission)
        {
            return mission != null &&
                SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty) &&
                BattleSnapshotRuntimeState.GetState() != null;
        }

        private static bool IsBallistaProjectileItem(ItemObject item)
        {
            return IsBallistaProjectileItemId(item?.StringId);
        }

        private static bool IsBallistaProjectileItemId(string itemId)
        {
            return string.Equals(itemId, "ballista_projectile", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(itemId, "ballista_projectile_burning", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsSiegeEngineProjectileItem(ItemObject item)
        {
            return IsSiegeEngineProjectileItemId(item?.StringId);
        }

        private static bool IsSiegeEngineProjectileItemId(string itemId)
        {
            return IsBallistaProjectileItemId(itemId) ||
                   string.Equals(itemId, "boulder_projectile", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(itemId, "pot_projectile", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(itemId, "grapeshot_projectile", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(itemId, "grapeshot_fire_projectile", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(itemId, "boulder", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(itemId, "pot", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(itemId, "grapeshot_stack", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(itemId, "grapeshot_fire_stack", StringComparison.OrdinalIgnoreCase);
        }

        private static TimeSpan ResolveClientSiegeEngineProjectileBecomeInvisibleVisualGrace(ItemObject item)
        {
            string itemId = item?.StringId;
            if (string.Equals(itemId, "grapeshot_projectile", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(itemId, "grapeshot_fire_projectile", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(itemId, "grapeshot_stack", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(itemId, "grapeshot_fire_stack", StringComparison.OrdinalIgnoreCase))
            {
                return TimeSpan.FromMilliseconds(300);
            }

            if (IsBallistaProjectileItemId(itemId))
                return TimeSpan.FromMilliseconds(650);

            if (string.Equals(itemId, "boulder_projectile", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(itemId, "pot_projectile", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(itemId, "boulder", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(itemId, "pot", StringComparison.OrdinalIgnoreCase))
            {
                return TimeSpan.FromMilliseconds(850);
            }

            return TimeSpan.FromMilliseconds(650);
        }

        private static bool IsSuppressibleServerProjectileStickItem(ItemObject item)
        {
            if (item == null)
                return false;

            if (IsSiegeEngineProjectileItem(item))
                return false;

            try
            {
                switch (item.ItemType)
                {
                    case ItemObject.ItemTypeEnum.Arrows:
                    case ItemObject.ItemTypeEnum.Bolts:
                    case ItemObject.ItemTypeEnum.Thrown:
                        return true;
                }
            }
            catch
            {
            }

            return false;
        }

        private static bool IsTroopProjectileStickItem(ItemObject item)
        {
            if (item == null || IsSiegeEngineProjectileItem(item))
                return false;

            try
            {
                switch (item.ItemType)
                {
                    case ItemObject.ItemTypeEnum.Arrows:
                    case ItemObject.ItemTypeEnum.Bolts:
                    case ItemObject.ItemTypeEnum.Thrown:
                        return true;
                }
            }
            catch
            {
            }

            return false;
        }

        private static bool IsExactSiegeWeaponUsageRangedCompatible(ItemObject item, WeaponComponentData usage)
        {
            if (usage == null)
                return false;

            if (usage.IsRangedWeapon)
                return true;

            if (usage.RelevantSkill == DefaultSkills.Throwing)
                return true;

            switch (usage.WeaponClass)
            {
                case WeaponClass.Javelin:
                case WeaponClass.ThrowingAxe:
                case WeaponClass.ThrowingKnife:
                case WeaponClass.Stone:
                case WeaponClass.SlingStone:
                    return true;
            }

            try
            {
                return item?.ItemType == ItemObject.ItemTypeEnum.Thrown;
            }
            catch
            {
                return false;
            }
        }

        private static bool ShouldAllowExactSiegeTroopProjectileStickBroadcast(
            Mission mission,
            ItemObject missileItem,
            Agent attachedAgent,
            bool attachedToShield,
            sbyte attachedBoneIndex,
            out string reason)
        {
            reason = "unknown";

            if (mission == null ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                reason = "not-exact-siege";
                return false;
            }

            if (!IsTroopProjectileStickItem(missileItem))
            {
                reason = IsBallistaProjectileItem(missileItem)
                    ? "siege-engine-projectile"
                    : "non-troop-projectile";
                return false;
            }

            if (attachedAgent == null)
            {
                reason = "world-or-mission-object-stick";
                return true;
            }

            bool attachedAgentActive;
            bool attachedAgentIsMount;
            try
            {
                attachedAgentActive = attachedAgent.IsActive();
                attachedAgentIsMount = attachedAgent.IsMount;
            }
            catch
            {
                reason = "attached-agent-state-unavailable";
                return false;
            }

            if (!attachedAgentActive)
            {
                reason = "attached-agent-inactive";
                return false;
            }

            if (attachedAgentIsMount)
            {
                reason = "attached-agent-is-mount";
                return false;
            }

            if (!attachedToShield && attachedBoneIndex < 0)
            {
                reason = "invalid-attached-bone";
                return false;
            }

            reason = "exact-siege-troop-projectile";
            return true;
        }

        private static bool IsShieldItem(ItemObject item)
        {
            if (item == null)
                return false;

            try
            {
                return item.PrimaryWeapon?.IsShield == true;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryResolveMissionMissileItem(Mission mission, int missileIndex, out ItemObject item)
        {
            item = null;
            if (mission == null || missileIndex < 0 || MissionMissilesDictionaryField == null)
                return false;

            try
            {
                if (!(MissionMissilesDictionaryField.GetValue(mission) is IDictionary missilesDictionary))
                    return false;

                object missile = missilesDictionary[missileIndex];
                if (missile == null)
                    return false;

                PropertyInfo weaponProperty = missile.GetType().GetProperty(
                    "Weapon",
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                if (weaponProperty == null || !(weaponProperty.GetValue(missile) is MissionWeapon missileWeapon) || missileWeapon.IsEmpty)
                    return false;

                item = missileWeapon.Item;
                return item != null;
            }
            catch
            {
                return false;
            }
        }

