                            attachedWeaponIndex + "|" +
                            forcedSpawnIndex + "|" +
                            ((agent.Character as BasicCharacterObject)?.StringId ?? "null");
                        if (!string.Equals(_lastSuppressedServerInvalidCorpseAttachedWeaponIndexKey, invalidIndexLogKey, StringComparison.Ordinal))
                        {
                            _lastSuppressedServerInvalidCorpseAttachedWeaponIndexKey = invalidIndexLogKey;
                            ModLogger.Info(
                                "BattleMapSpawnHandoffPatch: suppressed server SpawnAttachedWeaponOnCorpse because native provided invalid attached weapon index. " +
                                "AgentIndex=" + agent.Index +
                                " CharacterId=" + ((agent.Character as BasicCharacterObject)?.StringId ?? "null") +
                                " AttachedWeaponIndex=" + attachedWeaponIndex +
                                " ForcedSpawnIndex=" + forcedSpawnIndex);
                        }
                    }

                    return false;
                }

                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: server SpawnAttachedWeaponOnCorpse prefix failed open: " + ex.Message);
                return true;
            }
        }

        private static bool Mission_SpawnAttachedWeaponOnSpawnedWeapon_ServerPrefix(
            Mission __instance,
            SpawnedItemEntity spawnedWeapon,
            int attachmentIndex,
            int forcedSpawnIndex)
        {
            try
            {
                if (!ShouldUseServerExactBattleProjectileStickSuppression(__instance) ||
                    spawnedWeapon == null)
                {
                    return true;
                }

                if (attachmentIndex < 0)
                {
                    if (ExperimentalFeatures.EnableExactCreateAgentCorridorDiagnostics)
                    {
                        string invalidIndexLogKey =
                            GetMissionObjectIdValue(spawnedWeapon.Id) + "|" +
                            attachmentIndex + "|" +
                            forcedSpawnIndex + "|" +
                            (spawnedWeapon.WeaponCopy.Item?.StringId ?? "null");
                        if (!string.Equals(_lastSuppressedServerInvalidSpawnedWeaponAttachmentIndexKey, invalidIndexLogKey, StringComparison.Ordinal))
                        {
                            _lastSuppressedServerInvalidSpawnedWeaponAttachmentIndexKey = invalidIndexLogKey;
                            ModLogger.Info(
                                "BattleMapSpawnHandoffPatch: suppressed server SpawnAttachedWeaponOnSpawnedWeapon because native provided invalid attachment index. " +
                                "SpawnedWeaponId=" + GetMissionObjectIdValue(spawnedWeapon.Id) +
                                " ParentItem=" + (spawnedWeapon.WeaponCopy.Item?.StringId ?? "null") +
                                " AttachmentIndex=" + attachmentIndex +
                                " ForcedSpawnIndex=" + forcedSpawnIndex);
                        }
                    }

                    return false;
                }

                ItemObject parentItem = spawnedWeapon.WeaponCopy.Item;
                if (!IsShieldItem(parentItem))
                    return true;

                MissionWeapon attachedWeapon = spawnedWeapon.WeaponCopy.GetAttachedWeapon(attachmentIndex);
                if (attachedWeapon.IsEmpty)
                    return true;

                ItemObject attachedItem = attachedWeapon.Item;
                if (!IsSuppressibleServerProjectileStickItem(attachedItem))
                    return true;

                string logKey =
                    "spawned-weapon|" +
                    GetMissionObjectIdValue(spawnedWeapon.Id) + "|" +
                    (parentItem?.StringId ?? "null") + "|" +
                    attachmentIndex + "|" +
                    (attachedItem?.StringId ?? "null") + "|" +
                    forcedSpawnIndex;
                if (!string.Equals(_lastSuppressedServerSpawnedWeaponAttachmentKey, logKey, StringComparison.Ordinal))
                {
                    _lastSuppressedServerSpawnedWeaponAttachmentKey = logKey;
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: suppressed server SpawnAttachedWeaponOnSpawnedWeapon for dropped shield in exact battle. " +
                        "SpawnedWeaponId=" + GetMissionObjectIdValue(spawnedWeapon.Id) +
                        " ParentItem=" + (parentItem?.StringId ?? "null") +
                        " AttachmentIndex=" + attachmentIndex +
                        " AttachedItem=" + (attachedItem?.StringId ?? "null") +
                        " ForcedSpawnIndex=" + forcedSpawnIndex);
                }

                return false;
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: server SpawnAttachedWeaponOnSpawnedWeapon prefix failed open: " + ex.Message);
                return true;
            }
        }

        private static bool ShouldSuppressExactSiegeEngineProjectileNativeDropBroadcast(
            Mission mission,
            Mission.MissileCollisionReaction collisionReaction,
            ItemObject missileItem,
            out string reason)
        {
            reason = "unknown";

            if (mission == null ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                reason = "not-exact-siege";
                return false;
            }

            if (!IsSiegeEngineProjectileItem(missileItem))
            {
                reason = "non-siege-engine-projectile";
                return false;
            }

            reason = "native-siege-engine-projectile-reaction-allowed:" + collisionReaction;
            return false;
        }

        private static void TryLogSuppressedServerSiegeEngineProjectileNativeDrop(
            int missileIndex,
            ItemObject missileItem,
            Mission.MissileCollisionReaction originalReaction,
            Agent attackerAgent,
            Agent attachedAgent,
            bool attachedToShield,
            sbyte attachedBoneIndex,
            MissionObject attachedMissionObject,
            int forcedSpawnIndex,
            string suppressionReason)
        {
            if (!ExperimentalFeatures.EnableExactCreateAgentCorridorDiagnostics)
                return;

            string logKey =
                missileIndex + "|" +
                (missileItem?.StringId ?? "null") + "|" +
                originalReaction + "|" +
                (attachedAgent?.Index ?? -1) + "|" +
                attachedToShield + "|" +
                attachedBoneIndex + "|" +
                GetMissionObjectIdValue(attachedMissionObject?.Id ?? MissionObjectId.Invalid);
            if (string.Equals(_lastSuppressedServerSiegeEngineProjectileNativeDropKey, logKey, StringComparison.Ordinal))
                return;

            _lastSuppressedServerSiegeEngineProjectileNativeDropKey = logKey;
            ModLogger.Info(
                "BattleMapSpawnHandoffPatch: suppressed server siege-engine projectile native drop reaction and downgraded to BecomeInvisible. " +
                "MissileIndex=" + missileIndex +
                " MissileItem=" + (missileItem?.StringId ?? "null") +
                " OriginalReaction=" + originalReaction +
                " AttackerAgent=" + (attackerAgent?.Index ?? -1) +
                " AttachedAgent=" + (attachedAgent?.Index ?? -1) +
                " AttachedAgentIsMount=" + (attachedAgent?.IsMount ?? false) +
                " AttachedToShield=" + attachedToShield +
                " AttachedBoneIndex=" + attachedBoneIndex +
                " AttachedMissionObjectId=" + GetMissionObjectIdValue(attachedMissionObject?.Id ?? MissionObjectId.Invalid) +
                " SuppressionReason=" + (suppressionReason ?? "unknown") +
                " ForcedSpawnIndex=" + forcedSpawnIndex);
        }

        private static bool Mission_HandleMissileCollisionReaction_ServerPrefix(
            Mission __instance,
            int missileIndex,
            ref Mission.MissileCollisionReaction collisionReaction,
            Agent attackerAgent,
            Agent attachedAgent,
            bool attachedToShield,
            sbyte attachedBoneIndex,
            MissionObject attachedMissionObject,
            int forcedSpawnIndex)
        {
            try
            {
                if (!ShouldUseServerExactBattleProjectileStickSuppression(__instance))
                {
                    return true;
                }

                bool hasMissileItem = TryResolveMissionMissileItem(__instance, missileIndex, out ItemObject missileItem);

                Mission.MissileCollisionReaction originalCollisionReaction = collisionReaction;
                if (hasMissileItem &&
                    ShouldSuppressExactSiegeEngineProjectileNativeDropBroadcast(
                        __instance,
                        collisionReaction,
                        missileItem,
                        out string siegeEngineSuppressionReason))
                {
                    collisionReaction = Mission.MissileCollisionReaction.BecomeInvisible;
                    TryLogSuppressedServerSiegeEngineProjectileNativeDrop(
                        missileIndex,
                        missileItem,
                        originalCollisionReaction,
                        attackerAgent,
                        attachedAgent,
                        attachedToShield,
                        attachedBoneIndex,
                        attachedMissionObject,
                        forcedSpawnIndex,
                        siegeEngineSuppressionReason);
                    return true;
                }

                if (collisionReaction != Mission.MissileCollisionReaction.Stick)
                {
                    return true;
                }

                if (!hasMissileItem || !IsSuppressibleServerProjectileStickItem(missileItem))
                {
                    return true;
                }

                if (ShouldAllowExactSiegeTroopProjectileStickBroadcast(
                        __instance,
                        missileItem,
                        attachedAgent,
                        attachedToShield,
                        attachedBoneIndex,
                        out string suppressionReason))
                {
                    return true;
                }

                collisionReaction = Mission.MissileCollisionReaction.BecomeInvisible;

                string logKey =
                    missileIndex + "|" +
                    (missileItem?.StringId ?? "null") + "|" +
                    (attachedAgent?.Index ?? -1) + "|" +
                    (attachedAgent?.RiderAgent?.Index ?? -1) + "|" +
                    attachedToShield + "|" +
                    attachedBoneIndex + "|" +
                    GetMissionObjectIdValue(attachedMissionObject?.Id ?? MissionObjectId.Invalid);
                if (!string.Equals(_lastSuppressedServerProjectileStickKey, logKey, StringComparison.Ordinal))
                {
                    _lastSuppressedServerProjectileStickKey = logKey;
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: suppressed server projectile stick reaction and downgraded to BecomeInvisible. " +
                        "MissileIndex=" + missileIndex +
                        " MissileItem=" + (missileItem?.StringId ?? "null") +
                        " AttackerAgent=" + (attackerAgent?.Index ?? -1) +
                        " AttachedAgent=" + (attachedAgent?.Index ?? -1) +
                        " AttachedAgentIsMount=" + (attachedAgent?.IsMount ?? false) +
                        " RiderAgent=" + (attachedAgent?.RiderAgent?.Index ?? -1) +
                        " AttachedToShield=" + attachedToShield +
                        " AttachedBoneIndex=" + attachedBoneIndex +
                        " SuppressionReason=" + (suppressionReason ?? "unknown") +
                        " ForcedSpawnIndex=" + forcedSpawnIndex);
                }

                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: server HandleMissileCollisionReaction projectile prefix failed open: " + ex.Message);
                return true;
            }
        }

