        private static void TryReplayDeferredClientSetWeaponAmmoData(
            Mission mission,
            string source,
            string snapshotReadinessSummary)
        {
            if (_missionNetworkComponentHandleServerEventSetWeaponAmmoDataMethod == null)
                return;

            List<DeferredClientSetWeaponAmmoDataPayload> deferredPayloads;
            lock (DeferredClientSetWeaponAmmoDataPayloads)
            {
                if (DeferredClientSetWeaponAmmoDataPayloads.Count <= 0)
                    return;

                deferredPayloads = DeferredClientSetWeaponAmmoDataPayloads
                    .OrderBy(candidate => candidate.Sequence)
                    .ToList();
            }

            MissionNetworkComponent missionNetworkComponent = mission.GetMissionBehavior<MissionNetworkComponent>();
            if (missionNetworkComponent == null)
                return;

            DateTime nowUtc = DateTime.UtcNow;
            foreach (DeferredClientSetWeaponAmmoDataPayload deferredPayload in deferredPayloads)
            {
                SetWeaponAmmoData setWeaponAmmoData = deferredPayload?.Message;
                if (setWeaponAmmoData == null)
                    continue;

                if (deferredPayload.LastAttemptUtc != DateTime.MinValue &&
                    nowUtc - deferredPayload.LastAttemptUtc < TimeSpan.FromMilliseconds(100))
                {
                    continue;
                }

                Agent agent = Mission.MissionNetworkHelper.GetAgentFromIndex(setWeaponAmmoData.AgentIndex, canBeNull: true);
                if (agent == null || !agent.IsActive())
                    continue;

                if (IsPermanentExactSiegeClientWeaponStateUnsafe(
                        mission,
                        agent,
                        setWeaponAmmoData.WeaponEquipmentIndex,
                        out string permanentUnsafeReason))
                {
                    RemoveDeferredClientSetWeaponAmmoDataPayload(
                        setWeaponAmmoData.AgentIndex,
                        setWeaponAmmoData);
                    LogSuppressedExactSiegeUnsafeWeaponState(
                        nameof(SetWeaponAmmoData),
                        setWeaponAmmoData.AgentIndex,
                        setWeaponAmmoData.WeaponEquipmentIndex,
                        permanentUnsafeReason,
                        source);
                    continue;
                }

                if (IsPermanentExactSiegeClientWeaponAmmoStateUnsafe(
                        mission,
                        agent,
                        setWeaponAmmoData,
                        out string permanentAmmoUnsafeReason))
                {
                    RemoveDeferredClientSetWeaponAmmoDataPayload(
                        setWeaponAmmoData.AgentIndex,
                        setWeaponAmmoData);
                    LogSuppressedExactSiegeUnsafeWeaponState(
                        nameof(SetWeaponAmmoData),
                        setWeaponAmmoData.AgentIndex,
                        setWeaponAmmoData.WeaponEquipmentIndex,
                        permanentAmmoUnsafeReason,
                        source);
                    continue;
                }

                if (!IsExactSiegeClientWeaponAmmoDataNativeSafe(
                        mission,
                        agent,
                        setWeaponAmmoData,
                        out string exactSiegeUnsafeReason))
                {
                    if (IsPermanentExactSiegeClientWeaponAmmoNativeUnsafeReason(exactSiegeUnsafeReason))
                    {
                        RemoveDeferredClientSetWeaponAmmoDataPayload(
                            setWeaponAmmoData.AgentIndex,
                            setWeaponAmmoData);
                        LogSuppressedExactSiegeUnsafeWeaponState(
                            nameof(SetWeaponAmmoData),
                            setWeaponAmmoData.AgentIndex,
                            setWeaponAmmoData.WeaponEquipmentIndex,
                            exactSiegeUnsafeReason,
                            source);
                        continue;
                    }

                    deferredPayload.LastAttemptUtc = nowUtc;
                    deferredPayload.Attempts++;
                    LogDeferredExactSiegeUnsafeWeaponAmmoData(
                        setWeaponAmmoData,
                        exactSiegeUnsafeReason,
                        deferredPayload.Attempts,
                        source);
                    continue;
                }

                deferredPayload.LastAttemptUtc = nowUtc;
                deferredPayload.Attempts++;
                try
                {
                    _missionNetworkComponentHandleServerEventSetWeaponAmmoDataMethod.Invoke(
                        missionNetworkComponent,
                        new object[] { setWeaponAmmoData });

                    RemoveDeferredClientSetWeaponAmmoDataPayload(
                        setWeaponAmmoData.AgentIndex,
                        setWeaponAmmoData);
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: replayed deferred client SetWeaponAmmoData after battle snapshot apply. " +
                        "AgentIndex=" + setWeaponAmmoData.AgentIndex +
                        " WeaponEquipmentIndex=" + setWeaponAmmoData.WeaponEquipmentIndex +
                        " AmmoEquipmentIndex=" + setWeaponAmmoData.AmmoEquipmentIndex +
                        " Attempts=" + deferredPayload.Attempts +
                        " Source=" + (source ?? "unknown"));
                }
                catch (Exception ex)
                {
                    if (deferredPayload.Attempts == 1 || deferredPayload.Attempts % 20 == 0)
                    {
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: deferred client SetWeaponAmmoData replay failed open. " +
                            "AgentIndex=" + setWeaponAmmoData.AgentIndex +
                            " WeaponEquipmentIndex=" + setWeaponAmmoData.WeaponEquipmentIndex +
                            " AmmoEquipmentIndex=" + setWeaponAmmoData.AmmoEquipmentIndex +
                            " Attempts=" + deferredPayload.Attempts +
                            " SnapshotReadiness=" + (snapshotReadinessSummary ?? "unknown") +
                            " Message=" + ex.GetBaseException().Message);
                    }
                }
            }
        }

        private static bool IsExactSiegeClientWeaponAmmoDataNativeSafe(
            Mission mission,
            Agent agent,
            SetWeaponAmmoData setWeaponAmmoData,
            out string reason)
        {
            reason = null;
            if (mission == null ||
                GameNetwork.IsServer ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return true;
            }

            if (CoopMissionSpawnLogic.ShouldUseFieldMaterializedSiegeReplayRuntime(mission))
                return true;

            if (setWeaponAmmoData == null)
                return true;

            if (agent == null)
            {
                reason = "agent-missing";
                return false;
            }

            if (!agent.IsActive())
            {
                reason = "agent-inactive";
                return false;
            }

            EquipmentIndex weaponEquipmentIndex = setWeaponAmmoData.WeaponEquipmentIndex;
            if ((int)weaponEquipmentIndex < (int)EquipmentIndex.Weapon0 ||
                (int)weaponEquipmentIndex > (int)EquipmentIndex.Weapon3)
            {
                return true;
            }

            MissionEquipment missionEquipment = agent.Equipment;
            if (missionEquipment == null)
            {
                reason = "mission-equipment-null";
                return false;
            }

            MissionWeapon missionWeapon = missionEquipment[weaponEquipmentIndex];
            ItemObject weaponItem = missionWeapon.Item;
            if (weaponItem == null)
            {
                reason = "mission-weapon-slot-empty:" + weaponEquipmentIndex;
                return false;
            }

            int weaponsCount;
            try
            {
                weaponsCount = missionWeapon.WeaponsCount;
            }
            catch (Exception ex)
            {
                reason = "mission-weapon-usages-unavailable:" + ex.GetType().Name;
                return false;
            }

            if (weaponsCount <= 0)
            {
                reason = "mission-weapon-usages-empty:" + weaponItem.StringId;
                return false;
            }

            if (missionWeapon.CurrentUsageIndex < 0 || missionWeapon.CurrentUsageIndex >= weaponsCount)
            {
                reason =
                    "mission-weapon-usage-index-invalid:" +
                    weaponItem.StringId +
                    ":Usage=" + missionWeapon.CurrentUsageIndex +
                    ":Count=" + weaponsCount;
                return false;
            }

            WeaponComponentData primaryWeapon = weaponItem.PrimaryWeapon;
            if (primaryWeapon == null)
            {
                reason = "mission-weapon-primary-null:" + weaponItem.StringId;
                return false;
            }

            if (!IsExactSiegeWeaponUsageRangedCompatible(weaponItem, primaryWeapon))
            {
                reason = "mission-weapon-not-ranged:" + weaponItem.StringId;
                return false;
            }

            WeaponComponentData currentUsageWeapon = missionWeapon.CurrentUsageItem;
            if (currentUsageWeapon == null)
            {
                reason = "mission-weapon-current-usage-null:" + weaponItem.StringId;
                return false;
            }

            if (!IsExactSiegeWeaponUsageRangedCompatible(weaponItem, currentUsageWeapon))
            {
                reason = "mission-weapon-current-usage-not-ranged:" + weaponItem.StringId;
                return false;
            }

            if (setWeaponAmmoData.Ammo < 0)
            {
                reason = "ammo-negative:" + setWeaponAmmoData.Ammo;
                return false;
            }

            if (!DoesWeaponUsageRequireSeparateAmmo(weaponItem, currentUsageWeapon))
                return true;

            EquipmentIndex ammoEquipmentIndex = setWeaponAmmoData.AmmoEquipmentIndex;
            if ((int)ammoEquipmentIndex < (int)EquipmentIndex.Weapon0 ||
                (int)ammoEquipmentIndex > (int)EquipmentIndex.Weapon3)
            {
                reason = "ammo-slot-invalid:" + ammoEquipmentIndex;
                return false;
            }

            MissionWeapon ammoMissionWeapon = missionEquipment[ammoEquipmentIndex];
            ItemObject ammoItem = ammoMissionWeapon.Item;
            if (ammoItem == null)
            {
                reason = "ammo-slot-empty:" + ammoEquipmentIndex;
                return false;
            }

            WeaponComponentData ammoUsageWeapon = ammoMissionWeapon.CurrentUsageItem ?? ammoItem.PrimaryWeapon;
            if (ammoUsageWeapon == null)
            {
                reason = "ammo-current-usage-null:" + ammoItem.StringId;
                return false;
            }

            if (!IsCompatibleAmmoForWeapon(weaponItem, currentUsageWeapon, ammoItem, ammoUsageWeapon))
            {
                reason =
                    "ammo-slot-incompatible" +
                    ":Weapon=" + weaponItem.StringId +
                    ":WeaponClass=" + currentUsageWeapon.WeaponClass +
                    ":Ammo=" + ammoItem.StringId +
                    ":AmmoClass=" + ammoUsageWeapon.WeaponClass;
                return false;
            }

            short maxAmmo = ammoUsageWeapon.MaxDataValue;
            if (maxAmmo > 0 && setWeaponAmmoData.Ammo > maxAmmo)
            {
                reason =
                    "ammo-value-above-max" +
                    ":Ammo=" + setWeaponAmmoData.Ammo +
                    ":Max=" + maxAmmo +
                    ":AmmoItem=" + ammoItem.StringId;
                return false;
            }

            return true;
        }

        private static bool IsPermanentExactSiegeClientWeaponAmmoNativeUnsafeReason(string reason)
        {
            return !string.IsNullOrWhiteSpace(reason) &&
                   reason.StartsWith("ammo-slot-invalid:", StringComparison.Ordinal);
        }

        private static bool DoesWeaponUsageRequireSeparateAmmo(ItemObject weaponItem, WeaponComponentData weaponUsage)
        {
            if (weaponUsage == null)
                return false;

            if (weaponUsage.WeaponClass == WeaponClass.Bow ||
                weaponUsage.WeaponClass == WeaponClass.Crossbow)
            {
                return true;
            }

            if (weaponItem == null)
                return false;

            switch (weaponItem.ItemType)
            {
                case ItemObject.ItemTypeEnum.Bow:
                case ItemObject.ItemTypeEnum.Crossbow:
                case ItemObject.ItemTypeEnum.Sling:
                    return true;
                default:
                    return false;
            }
        }

        private static bool IsCompatibleAmmoForWeapon(
            ItemObject weaponItem,
            WeaponComponentData weaponUsage,
            ItemObject ammoItem,
            WeaponComponentData ammoUsage)
        {
            if (weaponUsage == null || ammoItem == null || ammoUsage == null)
                return false;

            if (weaponUsage.WeaponClass == WeaponClass.Bow ||
                weaponItem?.ItemType == ItemObject.ItemTypeEnum.Bow)
            {
                return ammoItem.ItemType == ItemObject.ItemTypeEnum.Arrows ||
                    ammoUsage.WeaponClass == WeaponClass.Arrow;
            }

            if (weaponUsage.WeaponClass == WeaponClass.Crossbow ||
                weaponItem?.ItemType == ItemObject.ItemTypeEnum.Crossbow)
            {
                return ammoItem.ItemType == ItemObject.ItemTypeEnum.Bolts ||
                    ammoUsage.WeaponClass == WeaponClass.Bolt;
            }

            if (weaponItem?.ItemType == ItemObject.ItemTypeEnum.Sling)
            {
                return ammoItem.ItemType == ItemObject.ItemTypeEnum.SlingStones ||
                    ammoUsage.WeaponClass == WeaponClass.SlingStone ||
                    ammoUsage.WeaponClass == WeaponClass.Stone;
            }

            return ammoUsage.IsAmmo ||
                ammoItem.ItemType == ItemObject.ItemTypeEnum.Arrows ||
                ammoItem.ItemType == ItemObject.ItemTypeEnum.Bolts ||
                ammoItem.ItemType == ItemObject.ItemTypeEnum.SlingStones;
        }

        private static void LogDeferredExactSiegeUnsafeWeaponAmmoData(
            SetWeaponAmmoData setWeaponAmmoData,
            string reason,
            int attempts,
            string source)
        {
            if (setWeaponAmmoData == null)
                return;

            string key =
                setWeaponAmmoData.AgentIndex + "|" +
                setWeaponAmmoData.WeaponEquipmentIndex + "|" +
                setWeaponAmmoData.AmmoEquipmentIndex + "|" +
                (reason ?? "unknown");
            bool shouldLog =
                !string.Equals(_lastDeferredExactSiegeUnsafeWeaponAmmoDataKey, key, StringComparison.Ordinal) ||
                attempts <= 1 ||
                attempts % 20 == 0;
            if (!shouldLog)
                return;

            _lastDeferredExactSiegeUnsafeWeaponAmmoDataKey = key;
            ModLogger.Info(
                "BattleMapSpawnHandoffPatch: deferred client SetWeaponAmmoData because exact siege mission weapon slot is not native-safe. " +
                "AgentIndex=" + setWeaponAmmoData.AgentIndex +
                " WeaponEquipmentIndex=" + setWeaponAmmoData.WeaponEquipmentIndex +
                " AmmoEquipmentIndex=" + setWeaponAmmoData.AmmoEquipmentIndex +
                " Attempts=" + attempts +
                " Reason=" + (reason ?? "unknown") +
                " Source=" + (source ?? "unknown"));
        }

        private static bool IsExactSiegeClientWeaponReloadPhaseNativeSafe(
            Mission mission,
            Agent agent,
            SetWeaponReloadPhase setWeaponReloadPhase,
            out string reason)
        {
            reason = null;
            if (setWeaponReloadPhase == null)
                return true;

            return IsExactSiegeClientWeaponStateNativeSafe(
                mission,
                agent,
                setWeaponReloadPhase.EquipmentIndex,
                out reason);
        }

        private static bool TryApplyLocalTerminalReloadPhaseAsManagedStateOnly(
            Mission mission,
            Agent agent,
            SetWeaponReloadPhase setWeaponReloadPhase,
            out string reason)
        {
            reason = null;
            if (GameNetwork.IsServer ||
                mission == null ||
                agent == null ||
                setWeaponReloadPhase == null ||
                agent.IsMount ||
                !agent.IsHuman ||
                !agent.IsActive() ||
                agent.Equipment == null)
            {
                return false;
            }

            if (!SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
                return false;

            if (!IsLocalMissionPeerControlledAgent(agent))
                return false;

            EquipmentIndex equipmentIndex = setWeaponReloadPhase.EquipmentIndex;
            if (equipmentIndex < EquipmentIndex.Weapon0 || equipmentIndex > EquipmentIndex.Weapon3)
                return false;

            EquipmentIndex currentMainHandIndex;
            try
            {
                currentMainHandIndex = agent.GetPrimaryWieldedItemIndex();
            }
            catch
            {
                return false;
            }

            if (currentMainHandIndex != equipmentIndex)
                return false;

            MissionWeapon missionWeapon;
            ItemObject item;
            WeaponComponentData usage;
            try
            {
                missionWeapon = agent.Equipment[equipmentIndex];
                item = missionWeapon.Item;
                if (missionWeapon.IsEmpty || item == null)
                    return false;

                usage = missionWeapon.CurrentUsageItem ?? item.PrimaryWeapon;
                if (usage == null)
                    return false;
            }
            catch
            {
                return false;
            }

            bool isBow = IsBowWeaponUsage(item, usage);
            short reloadPhase = setWeaponReloadPhase.ReloadPhase;
            bool terminalReloadPhase = isBow && reloadPhase == 1;
            if (!terminalReloadPhase)
                return false;

            bool isReloadLastPhase =
                IsAgentInReloadLastPhase(agent, channelNo: 1, out string actionSummary);
            bool recentlyCompletedReloadLastPhase = false;
            if (!isReloadLastPhase)
            {
                if ((missionWeapon.ReloadPhase != 0 && missionWeapon.ReloadPhase != 1) ||
                    missionWeapon.Amount <= 0 ||
                    missionWeapon.Ammo <= 0)
                {
                    return false;
                }

                recentlyCompletedReloadLastPhase =
                    TryConsumePendingLocalControlledBowTerminalReloadCompletion(
                        agent,
                        equipmentIndex,
                        item.StringId ?? "null");
                if (!recentlyCompletedReloadLastPhase)
                    return false;
            }

            try
            {
                agent.Equipment.SetReloadPhaseOfSlot(equipmentIndex, reloadPhase);
            }
            catch (Exception ex)
            {
                reason = "managed-state-only-apply-failed:" + ex.GetType().Name;
                return false;
            }

            _pendingLocalControlledBowTerminalReloadCompletion = null;
            reason =
                (recentlyCompletedReloadLastPhase
                    ? "local-terminal-reload-recently-completed"
                    : "local-terminal-reload-last-phase") +
                "|AgentIndex=" + agent.Index +
                "|EquipmentIndex=" + equipmentIndex +
                "|CurrentMain=" + currentMainHandIndex +
                "|ReloadPhase=" + reloadPhase +
                "|Item=" + (item.StringId ?? "null") +
                "|Usage=" + usage.WeaponClass +
                "|IsBow=" + isBow +
                "|Amount=" + missionWeapon.Amount +
                "|Ammo=" + missionWeapon.Ammo +
                "|Action1={" + actionSummary + "}";
            return true;
        }

        private static bool TryDeferUnmappedExactSiegeMissionObjectMessage(
            GameNetworkMessage message,
            string missionObjectIdMemberName,
            SiegeMissionObjectIdBridgeTarget target,
            string messageName,
            MethodInfo handlerMethod)
        {
            Mission mission = Mission.Current;
            if (message == null ||
                !SiegeMissionObjectIdBridge.IsExactSiegeClientContext(mission))
            {
                return false;
            }

            if (TryRemapExactSiegeMissionObjectIdMessage(
                    message,
                    missionObjectIdMemberName,
                    target,
                    messageName) &&
                IsExactSiegeMissionObjectMessageTargetReady(
                    message,
                    missionObjectIdMemberName,
                    messageName))
            {
                return false;
            }

            RegisterDeferredClientExactSiegeMissionObjectMessage(
                message,
                missionObjectIdMemberName,
                target,
                messageName,
                handlerMethod);
            return true;
        }

        private static bool IsExactSiegeMissionObjectMessageTargetReady(
            GameNetworkMessage message,
            string missionObjectIdMemberName,
            string messageName)
        {
            if (!TryGetMissionObjectIdMemberValue(
                    message,
                    missionObjectIdMemberName,
                    out MissionObjectId missionObjectId,
                    out _))
            {
                return false;
            }

            MissionObject localMissionObject = TryGetLocalMissionObject(missionObjectId);
            if (localMissionObject == null)
                return false;

            if (!string.Equals(messageName, "SyncObjectHitpoints", StringComparison.Ordinal) &&
                !string.Equals(messageName, "SyncObjectDestructionLevel", StringComparison.Ordinal))
            {
                return true;
            }

            WeakGameEntity gameEntity = localMissionObject.GameEntity;
            return gameEntity.IsValid &&
                   gameEntity.GetFirstScriptOfType<DestructableComponent>() != null;
        }

        private static bool TryConsumePendingLocalControlledBowTerminalReloadCompletion(
            Agent agent,
            EquipmentIndex equipmentIndex,
            string itemId)
        {
            string normalizedItemId = itemId ?? "null";
            PendingLocalControlledBowTerminalReloadCompletion pending =
                _pendingLocalControlledBowTerminalReloadCompletion;
            if (pending != null)
            {
                double elapsedSeconds = (DateTime.UtcNow - pending.ArmedUtc).TotalSeconds;
                bool matches =
                    DoesPendingLocalControlledBowTerminalReloadCompletionMatch(
                        pending,
                        agent,
                        equipmentIndex,
                        normalizedItemId) &&
                    elapsedSeconds >= 0.0d &&
                    elapsedSeconds < LocalControlledBowTerminalReloadCompletionTimeoutSeconds;
                if (matches)
                {
                    _pendingLocalControlledBowTerminalReloadCompletion = null;
                    return true;
                }

                TryRevertPendingLocalControlledBowTerminalReloadCompletion();
            }

            LocalControlledRangedReloadCompletionState trackedState =
                _localControlledRangedReloadCompletionState;
            return trackedState != null &&
                   ReferenceEquals(trackedState.Agent, agent) &&
                   trackedState.AgentIndex == agent.Index &&
                   trackedState.EquipmentIndex == equipmentIndex &&
                   string.Equals(trackedState.ItemId, normalizedItemId, StringComparison.Ordinal) &&
                   trackedState.IsReloadLastPhase &&
                   trackedState.ActionProgress >= LocalControlledRangedReloadCompletionMinimumProgress;
        }

        private static bool DoesPendingLocalControlledBowTerminalReloadCompletionMatch(
            PendingLocalControlledBowTerminalReloadCompletion pending,
            Agent agent,
            EquipmentIndex equipmentIndex,
            string itemId)
        {
            return pending != null &&
                   ReferenceEquals(pending.Agent, agent) &&
                   pending.AgentIndex == agent.Index &&
                   pending.EquipmentIndex == equipmentIndex &&
                   string.Equals(pending.ItemId, itemId ?? "null", StringComparison.Ordinal);
        }

        private static void TryRevertPendingLocalControlledBowTerminalReloadCompletion()
        {
            PendingLocalControlledBowTerminalReloadCompletion pending =
                _pendingLocalControlledBowTerminalReloadCompletion;
            _pendingLocalControlledBowTerminalReloadCompletion = null;
            if (pending?.Agent?.Equipment == null)
                return;

            try
            {
                if (pending.EquipmentIndex < EquipmentIndex.Weapon0 ||
                    pending.EquipmentIndex > EquipmentIndex.Weapon3)
                {
                    return;
                }

                MissionWeapon missionWeapon = pending.Agent.Equipment[pending.EquipmentIndex];
                ItemObject item = missionWeapon.Item;
                if (missionWeapon.IsEmpty ||
                    item == null ||
                    !string.Equals(item.StringId ?? "null", pending.ItemId, StringComparison.Ordinal) ||
                    missionWeapon.ReloadPhase != 1 ||
                    missionWeapon.Ammo > 0)
                {
                    return;
                }

                pending.Agent.Equipment.SetReloadPhaseOfSlot(pending.EquipmentIndex, 0);
            }
            catch
            {
            }
        }

        private static bool TryMaskLocalCrossbowAttackDownForTerminalWeaponState(
            Mission mission,
            Agent agent,
            EquipmentIndex payloadEquipmentIndex,
            string messageName,
            string terminalStateSummary,
            out string reason)
        {
            reason = null;
            if (_delayedLocalControlledWeaponStateReplayDepth > 0 ||
                GameNetwork.IsServer ||
                mission == null ||
                agent == null ||
                agent.IsMount ||
                !agent.IsHuman ||
                !agent.IsActive() ||
                agent.Equipment == null)
            {
                return false;
            }

            if (!SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
                return false;

            if (!IsLocalMissionPeerControlledAgent(agent))
                return false;

            if (payloadEquipmentIndex < EquipmentIndex.Weapon0 || payloadEquipmentIndex > EquipmentIndex.Weapon3)
                return false;

            if (!TryGetAgentPrimaryWieldedItemIndex(agent, out EquipmentIndex currentMainHandIndex) ||
                currentMainHandIndex < EquipmentIndex.Weapon0 ||
                currentMainHandIndex > EquipmentIndex.Weapon3)
            {
                return false;
            }

            if (!TryGetAgentMissionWeaponUsage(
                    agent,
                    currentMainHandIndex,
                    out MissionWeapon missionWeapon,
                    out ItemObject item,
                    out WeaponComponentData usage) ||
                !IsCrossbowWeaponUsage(item, usage))
            {
                return false;
            }

            string payloadSlotSummary = "current-main-crossbow";
            if (payloadEquipmentIndex != currentMainHandIndex)
            {
                if (!TryGetAgentMissionWeaponUsage(
                        agent,
                        payloadEquipmentIndex,
                        out _,
                        out ItemObject payloadItem,
                        out WeaponComponentData payloadUsage) ||
                    !IsBoltAmmoUsage(payloadItem, payloadUsage))
                {
                    return false;
                }

                payloadSlotSummary = "bolt-ammo-slot:" + (payloadItem.StringId ?? "null");
            }

            if (!IsAgentInReloadLastPhase(agent, channelNo: 1, out string actionSummary))
                return false;

            Agent.MovementControlFlag movementFlags = agent.MovementFlags;
            if ((movementFlags & Agent.MovementControlFlag.AttackDown) != Agent.MovementControlFlag.AttackDown)
                return false;

            Agent.MovementControlFlag maskedMovementFlags =
                movementFlags & ~Agent.MovementControlFlag.AttackDown;
            if (maskedMovementFlags == movementFlags)
                return false;

            try
            {
                agent.MovementFlags = maskedMovementFlags;
            }
            catch (Exception ex)
            {
                reason = "crossbow-attackdown-mask-failed:" + ex.GetType().Name;
                return false;
            }

            reason =
                "local-crossbow-terminal-weapon-state-attackdown-masked" +
                "|AgentIndex=" + agent.Index +
                "|Message=" + (messageName ?? "unknown") +
                "|PayloadEquipmentIndex=" + payloadEquipmentIndex +
                "|CurrentMain=" + currentMainHandIndex +
                "|Item=" + (item.StringId ?? "null") +
                "|Usage=" + usage.WeaponClass +
                "|Ammo=" + missionWeapon.Ammo +
                "|PayloadSlot=" + payloadSlotSummary +
                "|MovementFlagsBefore=" + movementFlags +
                "|MovementFlagsAfter=" + maskedMovementFlags +
                "|TerminalState={" + (terminalStateSummary ?? "(none)") + "}" +
                "|Action1={" + actionSummary + "}";
            return true;
        }

        private static bool IsAgentInReloadLastPhase(
            Agent agent,
            int channelNo,
            out string actionSummary)
        {
            actionSummary = null;
            if (agent == null)
                return false;

            try
            {
                string actionType = agent.GetCurrentActionType(channelNo).ToString();
                string actionStage = agent.GetCurrentActionStage(channelNo).ToString();
                string action = agent.GetCurrentAction(channelNo).ToString();
                actionSummary =
                    "Channel=" + channelNo +
                    " Action=" + action +
                    " Type=" + actionType +
                    " Stage=" + actionStage +
                    " Progress=" + agent.GetCurrentActionProgress(channelNo).ToString("0.000");
                return string.Equals(actionType, "Reload", StringComparison.Ordinal) &&
                       string.Equals(actionStage, "ReloadLastPhase", StringComparison.Ordinal);
            }
            catch
            {
                return false;
            }
        }

