        private static void TryLogLocalControlledWeaponStateDiagnostics(
            Mission mission,
            Agent agent,
            int agentIndex,
            string messageName,
            EquipmentIndex equipmentIndex,
            string payloadSummary,
            string disposition,
            string source)
        {
            if (!CoopDebugConfig.PossessionDiagnostics ||
                GameNetwork.IsServer ||
                mission == null ||
                agent == null ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty) ||
                !IsLocalMissionPeerControlledAgent(agent))
            {
                return;
            }

            EquipmentIndex currentMainHandIndex = EquipmentIndex.None;
            EquipmentIndex currentOffHandIndex = EquipmentIndex.None;
            try
            {
                currentMainHandIndex = agent.GetPrimaryWieldedItemIndex();
                currentOffHandIndex = agent.GetOffhandWieldedItemIndex();
            }
            catch
            {
            }

            CoopMissionSpawnLogic.TryBuildClientPossessionLifecycleDiagnostics(
                mission,
                agentIndex,
                agent,
                messageName,
                out string lifecycleSummary);

            string summary =
                "Message=" + (messageName ?? "weapon-state-message") +
                " Disposition=" + (disposition ?? "unknown") +
                " AgentIndex=" + agentIndex +
                " CharacterId=" + (agent.Character?.StringId ?? "null") +
                " TeamSide=" + (agent.Team?.Side.ToString() ?? "null") +
                " Controller=" + agent.Controller +
                " IsActive=" + agent.IsActive() +
                " Health=" + agent.Health.ToString("0.0") +
                " PayloadEquipmentIndex=" + equipmentIndex +
                " Payload={" + (payloadSummary ?? "(none)") + "}" +
                " CurrentMain=" + currentMainHandIndex +
                " CurrentOffhand=" + currentOffHandIndex +
                " CurrentMainWeapon=" + (agent.WieldedWeapon.Item?.StringId ?? "none") +
                " CurrentOffhandWeapon=" + (agent.WieldedOffhandWeapon.Item?.StringId ?? "none") +
                " PayloadSlot={" + BuildAgentMissionWeaponSlotDiagnostics(agent, equipmentIndex) + "}" +
                " MainSlot={" + BuildAgentMissionWeaponSlotDiagnostics(agent, currentMainHandIndex) + "}" +
                " OffhandSlot={" + BuildAgentMissionWeaponSlotDiagnostics(agent, currentOffHandIndex) + "}" +
                " RuntimeState={" + BuildLocalControlledAgentRuntimeDiagnostics(agent) + "}" +
                " Lifecycle={" + (lifecycleSummary ?? "(none)") + "}" +
                " Source=" + (source ?? "unknown");

            ModLogger.Info(
                "BattleMapSpawnHandoffPatch: local controlled weapon-state diagnostics. " +
                summary);
            ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                "client-local-controlled-weapon-state-diagnostics",
                summary);
        }

        private static string BuildLocalControlledAgentRuntimeDiagnostics(Agent agent)
        {
            if (agent == null)
                return "State=no-agent";

            try
            {
                return
                    "IsPlayerControlled=" + agent.IsPlayerControlled +
                    " IsAIControlled=" + agent.IsAIControlled +
                    " CombatActionsEnabled=" + agent.CombatActionsEnabled +
                    " MovementFlags=" + agent.MovementFlags +
                    " EventControlFlags=" + agent.EventControlFlags +
                    " Action0={" + BuildAgentActionChannelDiagnostics(agent, 0) + "}" +
                    " Action1={" + BuildAgentActionChannelDiagnostics(agent, 1) + "}";
            }
            catch (Exception ex)
            {
                return "State=failed Error=" + BuildCompactExceptionDiagnostics(ex);
            }
        }

        private static string BuildAgentActionChannelDiagnostics(Agent agent, int channelNo)
        {
            if (agent == null)
                return "Channel=" + channelNo + " State=no-agent";

            try
            {
                ActionIndexCache action = agent.GetCurrentAction(channelNo);
                return
                    "Channel=" + channelNo +
                    " ActionIndex=" + action.Index +
                    " Action=" + action +
                    " Type=" + agent.GetCurrentActionType(channelNo) +
                    " Stage=" + agent.GetCurrentActionStage(channelNo) +
                    " Direction=" + agent.GetCurrentActionDirection(channelNo) +
                    " Progress=" + agent.GetCurrentActionProgress(channelNo).ToString("0.000") +
                    " Priority=" + agent.GetCurrentActionPriority(channelNo) +
                    " Weight=" + agent.GetActionChannelWeight(channelNo).ToString("0.000") +
                    " AnimFlags=" + agent.GetCurrentAnimationFlag(channelNo);
            }
            catch (Exception ex)
            {
                return "Channel=" + channelNo + " State=failed Error=" + BuildCompactExceptionDiagnostics(ex);
            }
        }

        private static void TryApplyLocalControlledRangedTerminalReloadCompletion(Mission mission)
        {
            if (!GameNetwork.IsClient ||
                mission == null ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                ClearLocalControlledRangedReloadCompletionState();
                return;
            }

            try
            {
                MissionPeer localMissionPeer = GameNetwork.MyPeer?.GetComponent<MissionPeer>();
                Agent agent = localMissionPeer?.ControlledAgent ?? Agent.Main;
                if (agent == null ||
                    agent.IsMount ||
                    !agent.IsHuman ||
                    !agent.IsActive() ||
                    agent.Equipment == null ||
                    !IsLocalMissionPeerControlledAgent(agent))
                {
                    ClearLocalControlledRangedReloadCompletionState();
                    return;
                }

                if (!TryGetAgentPrimaryWieldedItemIndex(agent, out EquipmentIndex equipmentIndex) ||
                    equipmentIndex < EquipmentIndex.Weapon0 ||
                    equipmentIndex > EquipmentIndex.Weapon3 ||
                    !TryGetAgentMissionWeaponUsage(
                        agent,
                        equipmentIndex,
                        out MissionWeapon missionWeapon,
                        out ItemObject item,
                        out WeaponComponentData usage))
                {
                    ClearLocalControlledRangedReloadCompletionState();
                    return;
                }

                bool isThrown = IsThrownProjectileLaunchWeapon(missionWeapon);
                bool isCrossbow = IsCrossbowWeaponUsage(item, usage);
                bool isBow = IsBowWeaponUsage(item, usage);
                if (!isThrown && !isCrossbow && !isBow)
                {
                    ClearLocalControlledRangedReloadCompletionState();
                    return;
                }

                string itemId = item.StringId ?? "null";
                PendingLocalControlledBowTerminalReloadCompletion pendingBowCompletion =
                    _pendingLocalControlledBowTerminalReloadCompletion;
                if (pendingBowCompletion != null)
                {
                    double elapsedSeconds =
                        (DateTime.UtcNow - pendingBowCompletion.ArmedUtc).TotalSeconds;
                    bool pendingMatches =
                        DoesPendingLocalControlledBowTerminalReloadCompletionMatch(
                            pendingBowCompletion,
                            agent,
                            equipmentIndex,
                            itemId);
                    if (!pendingMatches || elapsedSeconds < 0.0d)
                    {
                        TryRevertPendingLocalControlledBowTerminalReloadCompletion();
                    }
                    else if (elapsedSeconds >= LocalControlledBowTerminalReloadCompletionTimeoutSeconds)
                    {
                        TryRevertPendingLocalControlledBowTerminalReloadCompletion();
                    }
                }

                bool isReloadLastPhase =
                    agent.GetCurrentActionType(1) == Agent.ActionCodeType.Reload &&
                    agent.GetCurrentActionStage(1) == Agent.ActionStage.ReloadLastPhase;
                var currentState = new LocalControlledRangedReloadCompletionState
                {
                    Agent = agent,
                    AgentIndex = agent.Index,
                    EquipmentIndex = equipmentIndex,
                    ItemId = itemId,
                    IsReloadLastPhase = isReloadLastPhase,
                    ActionProgress = agent.GetCurrentActionProgress(1)
                };

                LocalControlledRangedReloadCompletionState previousState =
                    _localControlledRangedReloadCompletionState;
                _localControlledRangedReloadCompletionState = currentState;
                bool sameTrackedWeapon =
                    previousState != null &&
                    ReferenceEquals(previousState.Agent, currentState.Agent) &&
                    previousState.AgentIndex == currentState.AgentIndex &&
                    previousState.EquipmentIndex == currentState.EquipmentIndex &&
                    string.Equals(previousState.ItemId, currentState.ItemId, StringComparison.Ordinal);
                if (!sameTrackedWeapon ||
                    !previousState.IsReloadLastPhase ||
                    currentState.IsReloadLastPhase ||
                    previousState.ActionProgress < LocalControlledRangedReloadCompletionMinimumProgress)
                {
                    return;
                }

                if (isThrown && missionWeapon.ReloadPhase == 0 && missionWeapon.Amount > 0)
                {
                    agent.SetWeaponReloadPhaseAsClient(equipmentIndex, 1);
                }
                else if (isBow &&
                         missionWeapon.ReloadPhase == 0 &&
                         missionWeapon.Amount > 0)
                {
                    agent.Equipment.SetReloadPhaseOfSlot(equipmentIndex, 1);
                    _pendingLocalControlledBowTerminalReloadCompletion =
                        new PendingLocalControlledBowTerminalReloadCompletion
                        {
                            Agent = agent,
                            AgentIndex = agent.Index,
                            EquipmentIndex = equipmentIndex,
                            ItemId = itemId,
                            ArmedUtc = DateTime.UtcNow
                        };
                }
                else if (isCrossbow &&
                         missionWeapon.ReloadPhase == 1 &&
                         missionWeapon.Amount > 0 &&
                         missionWeapon.Ammo <= 0)
                {
                    _pendingLocalControlledCrossbowTerminalAttackDownGuard =
                        new PendingLocalControlledCrossbowTerminalAttackDownGuard
                        {
                            AgentIndex = agent.Index,
                            EquipmentIndex = equipmentIndex,
                            ItemId = item.StringId ?? "null",
                            ArmedUtc = DateTime.UtcNow
                        };
                }
                else
                {
                    return;
                }
            }
            catch
            {
                ClearLocalControlledRangedReloadCompletionState();
            }
        }

        private static void ClearLocalControlledRangedReloadCompletionState()
        {
            TryRevertPendingLocalControlledBowTerminalReloadCompletion();
            _localControlledRangedReloadCompletionState = null;
        }

        private static string BuildCompactExceptionDiagnostics(Exception ex)
        {
            if (ex == null)
                return "unknown";

            string message = ex.Message ?? string.Empty;
            message = message.Replace('\r', ' ').Replace('\n', ' ');
            if (message.Length > 160)
                message = message.Substring(0, 160);

            return ex.GetType().Name + ":" + message;
        }

        private static string BuildAgentMissionWeaponSlotDiagnostics(Agent agent, EquipmentIndex equipmentIndex)
        {
            if (agent?.Equipment == null)
                return "Slot=" + equipmentIndex + " State=no-equipment";

            if (equipmentIndex < EquipmentIndex.Weapon0 || equipmentIndex > EquipmentIndex.Weapon3)
                return "Slot=" + equipmentIndex + " State=not-weapon-slot";

            try
            {
                MissionWeapon missionWeapon = agent.Equipment[equipmentIndex];
                if (missionWeapon.IsEmpty || missionWeapon.Item == null)
                    return "Slot=" + equipmentIndex + " State=empty";

                ItemObject item = missionWeapon.Item;
                WeaponComponentData usage = missionWeapon.CurrentUsageItem ?? item.PrimaryWeapon;
                return
                    "Slot=" + equipmentIndex +
                    " Item=" + (item.StringId ?? "null") +
                    " ItemType=" + item.ItemType +
                    " Usage=" + (usage?.WeaponClass.ToString() ?? "null") +
                    " UsageId=" + (usage?.ItemUsage ?? "null") +
                    " RelevantSkill=" + (usage?.RelevantSkill?.StringId ?? "null") +
                    " CurrentUsageIndex=" + missionWeapon.CurrentUsageIndex +
                    " ReloadPhase=" + missionWeapon.ReloadPhase +
                    " ReloadPhaseCount=" + missionWeapon.ReloadPhaseCount +
                    " Amount=" + missionWeapon.Amount +
                    " Ammo=" + missionWeapon.Ammo;
            }
            catch (Exception ex)
            {
                return "Slot=" + equipmentIndex + " State=error:" + ex.GetType().Name;
            }
        }

        private static void TryReplayDeferredClientSetWeaponReloadPhase(
            Mission mission,
            string source,
            string snapshotReadinessSummary)
        {
            if (_missionNetworkComponentHandleServerEventSetWeaponReloadPhaseMethod == null)
                return;

            List<DeferredClientSetWeaponReloadPhasePayload> deferredPayloads;
            lock (DeferredClientSetWeaponReloadPhasePayloads)
            {
                if (DeferredClientSetWeaponReloadPhasePayloads.Count <= 0)
                    return;

                deferredPayloads = DeferredClientSetWeaponReloadPhasePayloads
                    .OrderBy(candidate => candidate.Sequence)
                    .ToList();
            }

            MissionNetworkComponent missionNetworkComponent = mission.GetMissionBehavior<MissionNetworkComponent>();
            if (missionNetworkComponent == null)
                return;

            DateTime nowUtc = DateTime.UtcNow;
            foreach (DeferredClientSetWeaponReloadPhasePayload deferredPayload in deferredPayloads)
            {
                SetWeaponReloadPhase setWeaponReloadPhase = deferredPayload?.Message;
                if (setWeaponReloadPhase == null)
                    continue;

                if (deferredPayload.LastAttemptUtc != DateTime.MinValue &&
                    nowUtc - deferredPayload.LastAttemptUtc < TimeSpan.FromMilliseconds(100))
                {
                    continue;
                }

                Agent agent = Mission.MissionNetworkHelper.GetAgentFromIndex(setWeaponReloadPhase.AgentIndex, canBeNull: true);
                if (agent == null || !agent.IsActive())
                    continue;

                if (IsPermanentExactSiegeClientWeaponStateUnsafe(
                        mission,
                        agent,
                        setWeaponReloadPhase.EquipmentIndex,
                        out string permanentUnsafeReason))
                {
                    RemoveDeferredClientSetWeaponReloadPhasePayload(
                        setWeaponReloadPhase.AgentIndex,
                        setWeaponReloadPhase);
                    LogSuppressedExactSiegeUnsafeWeaponState(
                        nameof(SetWeaponReloadPhase),
                        setWeaponReloadPhase.AgentIndex,
                        setWeaponReloadPhase.EquipmentIndex,
                        permanentUnsafeReason,
                        source);
                    continue;
                }

                if (!IsExactSiegeClientWeaponReloadPhaseNativeSafe(
                        mission,
                        agent,
                        setWeaponReloadPhase,
                        out string exactSiegeUnsafeReason))
                {
                    deferredPayload.LastAttemptUtc = nowUtc;
                    deferredPayload.Attempts++;
                    LogDeferredExactSiegeUnsafeWeaponReloadPhase(
                        setWeaponReloadPhase,
                        exactSiegeUnsafeReason,
                        deferredPayload.Attempts,
                        source);
                    continue;
                }

                deferredPayload.LastAttemptUtc = nowUtc;
                deferredPayload.Attempts++;
                try
                {
                    _missionNetworkComponentHandleServerEventSetWeaponReloadPhaseMethod.Invoke(
                        missionNetworkComponent,
                        new object[] { setWeaponReloadPhase });
                    RemoveDeferredClientSetWeaponReloadPhasePayload(
                        setWeaponReloadPhase.AgentIndex,
                        setWeaponReloadPhase);
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: replayed deferred client SetWeaponReloadPhase after battle snapshot apply. " +
                        "AgentIndex=" + setWeaponReloadPhase.AgentIndex +
                        " EquipmentIndex=" + setWeaponReloadPhase.EquipmentIndex +
                        " Attempts=" + deferredPayload.Attempts +
                        " Source=" + (source ?? "unknown"));
                }
                catch (Exception ex)
                {
                    if (deferredPayload.Attempts == 1 || deferredPayload.Attempts % 20 == 0)
                    {
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: deferred client SetWeaponReloadPhase replay failed open. " +
                            "AgentIndex=" + setWeaponReloadPhase.AgentIndex +
                            " EquipmentIndex=" + setWeaponReloadPhase.EquipmentIndex +
                            " Attempts=" + deferredPayload.Attempts +
                            " SnapshotReadiness=" + (snapshotReadinessSummary ?? "unknown") +
                            " Message=" + ex.GetBaseException().Message);
                    }
                }
            }
        }

