        private static void MissionNetworkComponent_HandleServerEventCreateAgent_Postfix(GameNetworkMessage baseMessage)
        {
            try
            {
                if (!(baseMessage is CreateAgent createAgent))
                    return;

                Mission mission = Mission.Current;
                if (!ShouldRunAgentMaterializationHandoff(mission))
                    return;

                Agent agent = Mission.MissionNetworkHelper.GetAgentFromIndex(createAgent.AgentIndex, canBeNull: true);
                if (agent == null || !agent.IsActive() || agent.IsMount || agent.Team == null || agent.Team.Side == BattleSideEnum.None)
                    return;

                TryEnsureExactSiegeAgentOriginBanner(
                    mission,
                    agent);
                ExactTransferContractRuntimeCache.ObserveClientMaterialized(
                    agent.Index,
                    agent,
                    "battle-map handoff CreateAgent");
                CoopMissionSpawnLogic.ObserveClientCreateAgentPostfix(
                    agent,
                    "battle-map handoff CreateAgent postfix");
                if (createAgent.MountAgentIndex >= 0)
                    CoopMissionSpawnLogic.TryTrackClientMountedHeroMountAgentIndex(agent, createAgent.MountAgentIndex);
                CoopMissionSpawnLogic.TryTrackClientMountedHeroMountAgentIndex(agent);
                bool snapshotReadyForExactVisual =
                    CoopMissionNetworkBridge.IsClientCurrentBattleSnapshotApplied(out string snapshotReadinessSummary);
                bool exactVisualApplied = snapshotReadyForExactVisual &&
                    CoopMissionSpawnLogic.TryFinalizeClientExactCampaignVisualForAgent(
                        mission,
                        agent,
                        preferredEntryId: null,
                        source: "battle-map handoff CreateAgent",
                        allowImmediateApply: false);
                bool troopExactVisualApplied = false;
                if (!exactVisualApplied && snapshotReadyForExactVisual)
                {
                    troopExactVisualApplied = CoopMissionSpawnLogic.TryFinalizeClientExactCampaignTroopVisualForPeerAgent(
                        mission,
                        agent,
                        "battle-map handoff CreateAgent",
                        includeWeaponsForClientRefresh: true,
                        allowImmediateApply: false);
                }
                ExactCreateAgentCorridorDiagnostics.ObserveClientCreateAgentPostfix(
                    createAgent,
                    agent,
                    snapshotReadyForExactVisual,
                    snapshotReadinessSummary,
                    exactVisualApplied || troopExactVisualApplied,
                    "battle-map handoff CreateAgent");
                CoopMissionSpawnLogic.TraceClientMountedHeroNetworkContract(
                    agent,
                    "client-create-agent",
                    "battle-map handoff CreateAgent",
                    "PayloadMissionWeapons={" + BuildMissionEquipmentWeaponSummary(createAgent.MissionEquipment) + "}" +
                    " PayloadMount={" + BuildEquipmentSummary(createAgent.SpawnEquipment, EquipmentIndex.Horse, EquipmentIndex.HorseHarness) + "}" +
                    " PayloadMountAgentIndex=" + createAgent.MountAgentIndex +
                    " PayloadIsPlayerAgent=" + createAgent.IsPlayerAgent +
                    " SnapshotReadyForExactVisual=" + snapshotReadyForExactVisual +
                    " SnapshotReadinessReason=" + (snapshotReadinessSummary ?? "unknown") +
                    " ExactVisualApplied=" + exactVisualApplied +
                    " TroopExactVisualApplied=" + troopExactVisualApplied);
                if (!exactVisualApplied && !troopExactVisualApplied)
                    return;

                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: applied client exact visuals during CreateAgent handoff. " +
                    "AgentIndex=" + agent.Index +
                    " TeamSide=" + agent.Team.Side +
                    " TroopId=" + (agent.Character?.StringId ?? "null") +
                    " ExactVisualApplied=" + exactVisualApplied +
                    " TroopExactVisualApplied=" + troopExactVisualApplied +
                    " Mission=" + (mission.SceneName ?? "null"));
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: local CreateAgent exact visual finalization failed: " + ex.Message);
            }
        }

        private static Exception MissionNetworkComponent_HandleServerEventCreateAgent_Finalizer(
            Exception __exception,
            GameNetworkMessage baseMessage)
        {
            if (__exception == null)
                return null;

            try
            {
                if (!(baseMessage is CreateAgent createAgent))
                    return __exception;

                Mission mission = Mission.Current;
                if (!ShouldRunAgentMaterializationHandoff(mission))
                    return __exception;

                string failureReason = "create-agent-handler-exception:" + __exception.GetType().Name;
                CoopMissionSpawnLogic.ReportStrictExactHeroTransferFailure(
                    createAgent.AgentIndex,
                    "battle-map handoff CreateAgent finalizer",
                    failureReason);
                ExactTransferContractRuntimeCache.ReportClientFailure(
                    createAgent.AgentIndex,
                    ExactTransferFailureReason.CreateAgentHandlerException,
                    failureReason,
                    "battle-map handoff CreateAgent finalizer");
                ExactCreateAgentCorridorDiagnostics.ObserveClientCreateAgentException(
                    createAgent,
                    __exception,
                    "battle-map handoff CreateAgent finalizer");
                string payloadSummary =
                    "AgentIndex=" + createAgent.AgentIndex +
                    " MountAgentIndex=" + createAgent.MountAgentIndex +
                    " PayloadIsPlayerAgent=" + createAgent.IsPlayerAgent +
                    " ExceptionType=" + __exception.GetType().FullName +
                    " ExceptionMessage=" + __exception.Message;
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: CreateAgent handler threw during battle-map handoff. " +
                    payloadSummary);
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                    "client-create-agent-handler-exception",
                    payloadSummary + " Source=battle-map handoff CreateAgent finalizer");
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: CreateAgent finalizer failed open: " + ex.Message);
            }

            return __exception;
        }

        private static bool TryHandleStrictExactHeroCreateAgentViaContract(
            Mission mission,
            CreateAgent createAgent,
            out bool strictExactCandidate)
        {
            strictExactCandidate = false;
            if (mission == null || createAgent == null)
                return false;

            if (!CoopMissionSpawnLogic.TryResolveClientStrictExactHeroCreateAgentContract(
                    createAgent,
                    out string entryId,
                    out RosterEntryState entryState,
                    out ExactTransferSpawnContract contract,
                    out ExactTransferValidationResult validation,
                    out string resolutionSource))
            {
                return false;
            }

            strictExactCandidate = true;
            if (contract == null || validation == null || !validation.IsValid)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: strict exact CreateAgent adapter skipped because contract validation failed. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " EntryId=" + (entryId ?? "null") +
                    " ResolutionSource=" + (resolutionSource ?? "null") +
                    " " + ExactTransferContractRuntimeCache.BuildValidationSummary(entryId));
                return false;
            }

            if (contract.SpawnPolicy == null ||
                !contract.SpawnPolicy.UseStrictExactHeroPath ||
                !contract.SpawnPolicy.ForbidSurrogatePrimaryMaterialization)
            {
                return false;
            }

            BasicCharacterObject character = ResolveStrictExactHeroCreateAgentCharacter(createAgent, contract);
            if (character == null)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: strict exact CreateAgent adapter skipped because contract character could not be resolved. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " EntryId=" + (entryId ?? "null") +
                    " PayloadCharacter=" + (createAgent.Character?.StringId ?? "null"));
                return false;
            }

            Team teamFromTeamIndex = ResolveCreateAgentMissionTeam(mission, createAgent.TeamIndex);
            if (teamFromTeamIndex == null)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: strict exact CreateAgent adapter skipped because mission team was unavailable. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " TeamIndex=" + createAgent.TeamIndex +
                    " EntryId=" + (entryId ?? "null"));
                return false;
            }

            Formation formation = ResolveCreateAgentFormationForProjection(
                mission,
                teamFromTeamIndex,
                createAgent,
                character);

            Banner banner = ResolveStrictExactHeroCreateAgentBanner(teamFromTeamIndex, formation);
            Equipment createTimeSpawnEquipment = ResolveStrictExactHeroCreateAgentSpawnEquipment(contract, createAgent);
            if (createTimeSpawnEquipment != null && createAgent.MountAgentIndex < 0)
            {
                createTimeSpawnEquipment[EquipmentIndex.Horse] = default;
                createTimeSpawnEquipment[EquipmentIndex.HorseHarness] = default;
            }
            MissionEquipment createTimeMissionEquipment = ResolveStrictExactHeroCreateAgentMissionEquipment(
                createTimeSpawnEquipment,
                banner,
                createAgent);
            if (createTimeSpawnEquipment == null || createTimeMissionEquipment == null)
                return false;

            TaleWorlds.Localization.TextObject originalTroopName = null;
            bool hasTemporaryNameOverride =
                CoopMissionSpawnLogic.TryApplyEntryNameToSpawnCharacter(character, entryState, out originalTroopName);
            try
            {
                AgentBuildData buildData = new AgentBuildData(character)
                    .Monster(createAgent.Monster)
                    .TroopOrigin(new BasicBattleAgentOrigin(character))
                    .Equipment(createTimeSpawnEquipment)
                    .EquipmentSeed(createAgent.BodyPropertiesSeed)
                    .InitialPosition(createAgent.Position)
                    .InitialDirection(createAgent.Direction.Normalized())
                    .MissionEquipment(createTimeMissionEquipment)
                    .Team(teamFromTeamIndex)
                    .Index(createAgent.AgentIndex)
                    .MountIndex(createAgent.MountAgentIndex)
                    .IsFemale(contract.Body?.IsFemale ?? createAgent.IsFemale)
                    .ClothingColor1(createAgent.ClothingColor1)
                    .ClothingColor2(createAgent.ClothingColor2)
                    .BodyProperties(contract.Body.BodyProperties);
                if (contract?.Body?.Age is int exactAge)
                    buildData.Age(exactAge);
                if (formation != null)
                    buildData.Formation(formation);
                if (banner != null)
                    buildData.Banner(banner);

                Agent agent = mission.SpawnAgent(buildData);
                if (agent == null)
                {
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: strict exact CreateAgent adapter returned null agent. " +
                        "AgentIndex=" + createAgent.AgentIndex +
                        " EntryId=" + (entryId ?? "null"));
                    return false;
                }

                CoopMissionSpawnLogic.TryApplyEntryIdentityToAgent(agent, entryState);
                ExactTransferContractRuntimeCache.ObserveClientMaterialized(
                    agent.Index,
                    agent,
                    "battle-map handoff strict exact CreateAgent");
                if (createAgent.MountAgentIndex >= 0)
                    CoopMissionSpawnLogic.TryTrackClientMountedHeroMountAgentIndex(agent, createAgent.MountAgentIndex, entryId);
                CoopMissionSpawnLogic.TryTrackClientMountedHeroMountAgentIndex(agent);

                string payloadSummary =
                    "EntryId=" + (entryId ?? "null") +
                    " ResolutionSource=" + (resolutionSource ?? "null") +
                    " PayloadCharacter=" + (createAgent.Character?.StringId ?? "null") +
                    " ContractCharacter=" + (character.StringId ?? "null") +
                    " MountAgentIndex=" + createAgent.MountAgentIndex +
                    " DismountedPayload=" + (createAgent.MountAgentIndex < 0) +
                    " FormationIndex=" + createAgent.FormationIndex +
                    " StrippedRemotePeer=True" +
                    " CanonicalizedCharacter=False";
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: handled strict exact CreateAgent via contract adapter. " +
                    "AgentIndex=" + agent.Index +
                    " TeamSide=" + agent.Team?.Side +
                    " " + payloadSummary +
                    " " + ExactTransferContractRuntimeCache.BuildRuntimeStateSummary(entryId));
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                    "client-create-agent-contract-adapter",
                    "AgentIndex=" + agent.Index +
                    " " + payloadSummary +
                    " Source=battle-map handoff strict exact CreateAgent");
                return true;
            }
            catch (Exception ex)
            {
                string failureReason = "strict-create-agent-adapter-exception:" + ex.GetType().Name;
                ExactTransferContractRuntimeCache.ReportClientFailure(
                    createAgent.AgentIndex,
                    ExactTransferFailureReason.CreateAgentHandlerException,
                    failureReason,
                    "battle-map handoff strict exact CreateAgent");
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: strict exact CreateAgent adapter failed. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " EntryId=" + (entryId ?? "null") +
                    " ResolutionSource=" + (resolutionSource ?? "null") +
                    " Message=" + ex.Message);
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                    "client-create-agent-contract-adapter-failed",
                    "AgentIndex=" + createAgent.AgentIndex +
                    " EntryId=" + (entryId ?? "null") +
                    " FailureReason=" + failureReason +
                    " Message=" + ex.Message +
                    " Source=battle-map handoff strict exact CreateAgent");
                return false;
            }
            finally
            {
                CoopMissionSpawnLogic.RestoreSpawnCharacterName(character, hasTemporaryNameOverride, originalTroopName);
            }
        }

        private static bool TryHandleExactSiegeTroopCreateAgentViaSnapshot(
            Mission mission,
            CreateAgent createAgent)
        {
            if (mission == null ||
                createAgent == null ||
                GameNetwork.IsServer ||
                createAgent.IsPlayerAgent ||
                createAgent.Peer != null ||
                createAgent.MountAgentIndex >= 0 ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return false;
            }

            if (!TryResolveExactSiegeTroopCreateAgentEntry(
                    mission,
                    createAgent,
                    out string entryId,
                    out RosterEntryState entryState,
                    out string resolutionState,
                    out string payloadComparisonSummary))
            {
                return false;
            }

            BasicCharacterObject character =
                BattleSnapshotRuntimeState.TryResolveCharacterObject(entryId) ??
                createAgent.Character;
            if (character == null)
                return false;

            Team teamFromTeamIndex = ResolveCreateAgentMissionTeam(mission, createAgent.TeamIndex);
            if (teamFromTeamIndex == null)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: exact siege troop CreateAgent adapter skipped because mission team was unavailable. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " TeamIndex=" + createAgent.TeamIndex +
                    " EntryId=" + (entryId ?? "null") +
                    " PayloadCharacter=" + (createAgent.Character?.StringId ?? "null"));
                return false;
            }

            Formation formation = ResolveCreateAgentFormationForProjection(
                mission,
                teamFromTeamIndex,
                createAgent,
                character);
            Banner banner = ResolveStrictExactHeroCreateAgentBanner(teamFromTeamIndex, formation);
            Equipment createTimeSpawnEquipment = CoopMissionSpawnLogic.BuildSnapshotEquipmentForExactRuntime(
                entryState,
                includeWeapons: true,
                honorExactVisualContracts: false,
                includeArmorVisuals: true,
                includeMountVisuals: false);
            if (createTimeSpawnEquipment == null)
                return false;

            createTimeSpawnEquipment[EquipmentIndex.Horse] = default;
            createTimeSpawnEquipment[EquipmentIndex.HorseHarness] = default;
            MissionEquipment createTimeMissionEquipment = new MissionEquipment(createTimeSpawnEquipment, banner);

            Vec2 initialDirection = createAgent.Direction;
            if (initialDirection.LengthSquared <= 0.001f)
                initialDirection = teamFromTeamIndex.Side == BattleSideEnum.Attacker
                    ? new Vec2(1f, 0f)
                    : new Vec2(-1f, 0f);

            TaleWorlds.Localization.TextObject originalTroopName = null;
            bool hasTemporaryNameOverride =
                CoopMissionSpawnLogic.TryApplyEntryNameToSpawnCharacter(character, entryState, out originalTroopName);
            try
            {
                AgentBuildData buildData = new AgentBuildData(character)
                    .Monster(createAgent.Monster)
                    .TroopOrigin(new BasicBattleAgentOrigin(character))
                    .Controller(AgentControllerType.AI)
                    .Equipment(createTimeSpawnEquipment)
                    .EquipmentSeed(createAgent.BodyPropertiesSeed)
                    .InitialPosition(createAgent.Position)
                    .InitialDirection(initialDirection.Normalized())
                    .MissionEquipment(createTimeMissionEquipment)
                    .Team(teamFromTeamIndex)
                    .Index(createAgent.AgentIndex)
                    .MountIndex(-1)
                    .IsFemale(createAgent.IsFemale)
                    .ClothingColor1(createAgent.ClothingColor1)
                    .ClothingColor2(createAgent.ClothingColor2)
                    .BodyProperties(createAgent.BodyPropertiesValue);
                if (formation != null)
                    buildData.Formation(formation);
                if (banner != null)
                    buildData.Banner(banner);

                Agent agent = mission.SpawnAgent(buildData);
                if (agent == null)
                {
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: exact siege troop CreateAgent adapter returned null agent. " +
                        "AgentIndex=" + createAgent.AgentIndex +
                        " EntryId=" + (entryId ?? "null"));
                    return false;
                }

                CoopMissionSpawnLogic.TryApplyEntryIdentityToAgent(agent, entryState);
                CoopMissionSpawnLogic.ObserveClientAuthoritativeMaterializedAgentEntry(
                    agent.Index,
                    entryId,
                    "battle-map exact siege troop CreateAgent adapter");
                CoopMissionSpawnLogic.ObserveClientCreateAgentPostfix(
                    agent,
                    "battle-map exact siege troop CreateAgent adapter");
                ExactTransferContractRuntimeCache.ObserveClientMaterialized(
                    agent.Index,
                    agent,
                    "battle-map exact siege troop CreateAgent adapter");

                if (ExperimentalFeatures.EnableExactBattleAgentContractDiagnostics)
                {
                    string payloadSummary =
                        "EntryId=" + (entryId ?? "null") +
                        " ResolutionState=" + (resolutionState ?? "null") +
                        " PayloadCharacter=" + (createAgent.Character?.StringId ?? "null") +
                        " SnapshotCharacter=" + (character.StringId ?? "null") +
                        " MountAgentIndex=" + createAgent.MountAgentIndex +
                        " FormationIndex=" + createAgent.FormationIndex +
                        " PayloadCompare=" + (payloadComparisonSummary ?? "null") +
                        " ExactWeapons={" + BuildEquipmentSummary(
                            createTimeSpawnEquipment,
                            EquipmentIndex.Weapon0,
                            EquipmentIndex.Weapon1,
                            EquipmentIndex.Weapon2,
                            EquipmentIndex.Weapon3) + "}" +
                        " ExactMount={" + BuildEquipmentSummary(
                            createTimeSpawnEquipment,
                            EquipmentIndex.Horse,
                            EquipmentIndex.HorseHarness) + "}";
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: handled exact siege troop CreateAgent via snapshot adapter. " +
                        "AgentIndex=" + agent.Index +
                        " TeamSide=" + agent.Team?.Side +
                        " " + payloadSummary);
                    ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                        "client-create-agent-exact-siege-troop-snapshot-adapter",
                        "AgentIndex=" + agent.Index +
                        " " + payloadSummary +
                        " Source=battle-map exact siege troop CreateAgent adapter");
                }
                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: exact siege troop CreateAgent adapter failed. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " EntryId=" + (entryId ?? "null") +
                    " ResolutionState=" + (resolutionState ?? "null") +
                    " Message=" + ex.Message);
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                    "client-create-agent-exact-siege-troop-snapshot-adapter-failed",
                    "AgentIndex=" + createAgent.AgentIndex +
                    " EntryId=" + (entryId ?? "null") +
                    " ResolutionState=" + (resolutionState ?? "null") +
                    " Message=" + ex.Message +
                    " Source=battle-map exact siege troop CreateAgent adapter");
                return false;
            }
            finally
            {
                CoopMissionSpawnLogic.RestoreSpawnCharacterName(character, hasTemporaryNameOverride, originalTroopName);
            }
        }

        private static bool TryResolveExactSiegeTroopCreateAgentEntry(
            Mission mission,
            CreateAgent createAgent,
            out string entryId,
            out RosterEntryState entryState,
            out string resolutionState,
            out string payloadComparisonSummary)
        {
            entryId = null;
            entryState = null;
            resolutionState = null;
            payloadComparisonSummary = null;

            if (mission == null ||
                createAgent == null ||
                createAgent.MountAgentIndex >= 0 ||
                createAgent.Character == null)
            {
                return false;
            }

            BattleSideEnum expectedSide = ResolveCreateAgentPayloadBattleSideForPatch(createAgent.TeamIndex);
            if (CoopMissionSpawnLogic.TryResolveAuthoritativeTrackedEntryId(
                    createAgent.AgentIndex,
                    createAgent.Character.StringId,
                    expectedSide,
                    out entryId))
            {
                resolutionState = "authoritative-agent-index";
                payloadComparisonSummary =
                    "PayloadCompare={State=authoritative-agent-index,EntryId=" + (entryId ?? "null") + "}";
            }
            else if (CoopMissionSpawnLogic.ShouldUseFieldMaterializedSiegeReplayRuntime(mission))
            {
                return false;
            }
            else if (!ExactCreateAgentCorridorDiagnostics.TryResolveClientCreateAgentPayloadEntryId(
                         createAgent,
                         out entryId,
                         out resolutionState,
                         out payloadComparisonSummary))
            {
                return false;
            }

            if (!IsExactSiegeTroopCreateAgentResolutionAllowed(resolutionState) ||
                string.IsNullOrWhiteSpace(entryId))
            {
                return false;
            }

            entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
            if (entryState == null || IsExactHeroEntry(entryState))
                return false;

            if (expectedSide != BattleSideEnum.None &&
                !DoesRosterEntryStateMatchBattleSide(entryState, expectedSide))
            {
                return false;
            }

            if (entryState.IsMounted &&
                !ShouldAllowDismountedExactSiegeTroopCreateAgent(
                    mission,
                    ResolveCreateAgentMissionTeam(mission, createAgent.TeamIndex),
                    createAgent.Character,
                    createAgent))
            {
                return false;
            }

            return true;
        }

        private static bool ShouldAllowDismountedExactSiegeTroopCreateAgent(
            Mission mission,
            Team team,
            BasicCharacterObject character,
            CreateAgent createAgent)
        {
            if (mission == null ||
                createAgent == null ||
                character == null ||
                createAgent.MountAgentIndex >= 0)
            {
                return false;
            }

            if (ShouldUseDismountedSiegeCreateAgentFormation(mission, team, character))
                return true;

            return ShouldRunExactSiegeAssaultWithDeploymentMaterializationHandoff(mission);
        }

        private static bool IsExactSiegeTroopCreateAgentResolutionAllowed(string resolutionState)
        {
            return string.Equals(resolutionState, "resolved-strong", StringComparison.Ordinal) ||
                   string.Equals(resolutionState, "resolved-layout", StringComparison.Ordinal) ||
                   string.Equals(resolutionState, "resolved-character", StringComparison.Ordinal) ||
                   string.Equals(resolutionState, "authoritative-agent-index", StringComparison.Ordinal);
        }

        private static bool TryHandleMountedHeroCreateAgentViaPayloadAdapter(
            Mission mission,
            CreateAgent createAgent,
            out bool mountedHeroPayloadCandidate)
        {
            mountedHeroPayloadCandidate = IsMountedHeroTemplatePayload(createAgent);
            if (!mountedHeroPayloadCandidate || mission == null || createAgent == null)
                return false;

            Team teamFromTeamIndex = ResolveCreateAgentMissionTeam(mission, createAgent.TeamIndex);
            if (teamFromTeamIndex == null)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: mounted hero CreateAgent payload adapter skipped because mission team was unavailable. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " TeamIndex=" + createAgent.TeamIndex +
                    " PayloadCharacter=" + (createAgent.Character?.StringId ?? "null"));
                return false;
            }

            bool resolvedStrictExactContract = TryResolveMountedHeroCreateAgentContractForPayloadAdapter(
                createAgent,
                out string entryId,
                out RosterEntryState entryState,
                out ExactTransferSpawnContract contract,
                out ExactTransferValidationResult validation,
                out string resolutionSource);
            bool exactVisualHybridEligible =
                resolvedStrictExactContract &&
                entryState != null &&
                contract != null &&
                HasOnlyStrictHeroWeapon2RiskValidationFailure(validation);
            BasicCharacterObject createTimeCharacter = createAgent.Character;
            if (resolvedStrictExactContract && contract != null)
                createTimeCharacter = ResolveStrictExactHeroCreateAgentCharacter(createAgent, contract) ?? createTimeCharacter;

            Formation formation = ResolveCreateAgentFormationForProjection(
                mission,
                teamFromTeamIndex,
                createAgent,
                createTimeCharacter);
            Banner banner = ResolveStrictExactHeroCreateAgentBanner(teamFromTeamIndex, formation);
            Equipment createTimeSpawnEquipment =
                exactVisualHybridEligible
                    ? BuildMountedHeroExactVisualHybridSpawnEquipment(contract, createAgent)
                    : createAgent.SpawnEquipment?.Clone(false);
            MissionEquipment createTimeMissionEquipment =
                exactVisualHybridEligible
                    ? BuildMountedHeroExactVisualHybridMissionEquipment(createTimeSpawnEquipment, createAgent, banner)
                    : createAgent.MissionEquipment ??
                      (createTimeSpawnEquipment != null ? new MissionEquipment(createTimeSpawnEquipment, banner) : null);
            if (createTimeSpawnEquipment == null || createTimeMissionEquipment == null || createTimeCharacter == null)
                return false;

            TaleWorlds.Localization.TextObject originalTroopName = null;
            bool hasTemporaryNameOverride =
                CoopMissionSpawnLogic.TryApplyEntryNameToSpawnCharacter(createTimeCharacter, entryState, out originalTroopName);
            try
            {
                AgentBuildData buildData = new AgentBuildData(createTimeCharacter)
                    .Monster(createAgent.Monster)
                    .TroopOrigin(new BasicBattleAgentOrigin(createTimeCharacter))
                    .Equipment(createTimeSpawnEquipment)
                    .EquipmentSeed(createAgent.BodyPropertiesSeed)
                    .InitialPosition(createAgent.Position)
                    .InitialDirection(createAgent.Direction.Normalized())
                    .MissionEquipment(createTimeMissionEquipment)
                    .Team(teamFromTeamIndex)
                    .Index(createAgent.AgentIndex)
                    .MountIndex(createAgent.MountAgentIndex)
                    .IsFemale(contract?.Body?.HasExactBodyProperties == true ? contract.Body.IsFemale : createAgent.IsFemale)
                    .ClothingColor1(createAgent.ClothingColor1)
                    .ClothingColor2(createAgent.ClothingColor2)
                    .BodyProperties(contract?.Body?.HasExactBodyProperties == true ? contract.Body.BodyProperties : createAgent.BodyPropertiesValue);
                if (contract?.Body?.Age is int exactAge)
                    buildData.Age(exactAge);
                if (formation != null)
                    buildData.Formation(formation);
                if (banner != null)
                    buildData.Banner(banner);

                Agent agent = mission.SpawnAgent(buildData);
                if (agent == null)
                    return false;

                CoopMissionSpawnLogic.TryApplyEntryIdentityToAgent(agent, entryState);
                if (resolvedStrictExactContract)
                    ExactTransferContractRuntimeCache.ObserveClientMaterialized(
                        agent.Index,
                        agent,
                        "battle-map mounted-hero payload adapter");
                if (createAgent.MountAgentIndex >= 0)
                    CoopMissionSpawnLogic.TryTrackClientMountedHeroMountAgentIndex(
                        agent,
                        createAgent.MountAgentIndex,
                        entryId);
                CoopMissionSpawnLogic.TryTrackClientMountedHeroMountAgentIndex(agent);

                string payloadSummary =
                    "EntryId=" + (entryId ?? "null") +
                    " ResolutionSource=" + (resolutionSource ?? "null") +
                    "PayloadCharacter=" + (createAgent.Character?.StringId ?? "null") +
                    " ContractCharacter=" + (createTimeCharacter?.StringId ?? "null") +
                    " MountAgentIndex=" + createAgent.MountAgentIndex +
                    " FormationIndex=" + createAgent.FormationIndex +
                    " ExactVisualHybridEligible=" + exactVisualHybridEligible +
                    " PayloadMissionWeapons={" + BuildMissionEquipmentWeaponSummary(createTimeMissionEquipment) + "}" +
                    " PayloadMount={" + BuildEquipmentSummary(createTimeSpawnEquipment, EquipmentIndex.Horse, EquipmentIndex.HorseHarness) + "}" +
                    " Source=battle-map payload mounted hero CreateAgent";
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: handled mounted hero CreateAgent via payload adapter. " +
                    "AgentIndex=" + agent.Index +
                    " TeamSide=" + (agent.Team?.Side.ToString() ?? "None") +
                    " " + payloadSummary);
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                    "client-create-agent-payload-mounted-hero-adapter",
                    "AgentIndex=" + agent.Index + " " + payloadSummary);
                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: mounted hero CreateAgent payload adapter failed. " +
                    "AgentIndex=" + createAgent.AgentIndex +
                    " PayloadCharacter=" + (createAgent.Character?.StringId ?? "null") +
                    " Message=" + ex.Message);
                return false;
            }
            finally
            {
                CoopMissionSpawnLogic.RestoreSpawnCharacterName(createTimeCharacter, hasTemporaryNameOverride, originalTroopName);
            }
        }

        private static bool HasOnlyStrictHeroWeapon2RiskValidationFailure(ExactTransferValidationResult validation)
        {
            return validation != null &&
                   !validation.IsValid &&
                   validation.Errors.Count > 0 &&
                   validation.Errors.All(error =>
                       string.Equals(
                           error,
                           "strict hero path still has live weapon2 risk",
                           StringComparison.Ordinal));
        }

        private static bool TryResolveMountedHeroCreateAgentContractForPayloadAdapter(
            CreateAgent createAgent,
            out string entryId,
            out RosterEntryState entryState,
            out ExactTransferSpawnContract contract,
            out ExactTransferValidationResult validation,
            out string resolutionSource)
        {
            if (CoopMissionSpawnLogic.TryResolveClientStrictExactHeroCreateAgentContract(
                    createAgent,
                    out entryId,
                    out entryState,
                    out contract,
                    out validation,
                    out resolutionSource))
            {
                return true;
            }

            entryId = null;
            entryState = null;
            contract = null;
            validation = null;
            resolutionSource = null;

            if (!TryResolveMountedHeroCreateAgentEntryFromPayloadFallback(
                    createAgent,
                    out entryId,
                    out entryState,
                    out resolutionSource))
            {
                return false;
            }

            contract = ExactTransferContractBuilder.Build(
                entryState,
                isPlayerControlledOrigin: false,
                teamIndex: createAgent.TeamIndex,
                formationIndex: createAgent.FormationIndex);
            validation = ExactTransferContractValidator.Validate(contract);
            ExactTransferContractRuntimeCache.RegisterClientObservedContract(
                contract,
                validation,
                createAgent.AgentIndex,
                createAgent.MountAgentIndex,
                "client mounted hero payload adapter fallback: " + (resolutionSource ?? "unknown"));
            ModLogger.Info(
                "BattleMapSpawnHandoffPatch: resolved mounted hero CreateAgent contract via payload fallback. " +
                "AgentIndex=" + createAgent.AgentIndex +
                " MountAgentIndex=" + createAgent.MountAgentIndex +
                " EntryId=" + (entryId ?? "null") +
                " PayloadCharacter=" + (createAgent.Character?.StringId ?? "null") +
                " ResolutionSource=" + (resolutionSource ?? "null") +
                " " + ExactTransferContractRuntimeCache.BuildContractSummary(entryId) +
                " " + ExactTransferContractRuntimeCache.BuildValidationSummary(entryId) +
                " " + ExactTransferContractRuntimeCache.BuildRuntimeStateSummary(entryId));
            return true;
        }

        private static bool TryResolveMountedHeroCreateAgentEntryFromPayloadFallback(
            CreateAgent createAgent,
            out string entryId,
            out RosterEntryState entryState,
            out string resolutionSource)
        {
            entryId = null;
            entryState = null;
            resolutionSource = null;

            if (createAgent == null || createAgent.MountAgentIndex < 0)
                return false;

            if (!ExactCreateAgentCorridorDiagnostics.TryResolveClientCreateAgentPayloadEntryId(
                    createAgent,
                    out string candidateEntryId,
                    out string resolutionState,
                    out string _))
            {
                return false;
            }

            if (string.IsNullOrWhiteSpace(candidateEntryId))
                return false;

            RosterEntryState candidateEntryState = BattleSnapshotRuntimeState.GetEntryState(candidateEntryId);
            if (candidateEntryState == null ||
                !candidateEntryState.IsHero ||
                !candidateEntryState.IsMounted)
            {
                return false;
            }

            entryId = candidateEntryId;
            entryState = candidateEntryState;
            resolutionSource = "payload-candidate-" + (resolutionState ?? "resolved");
            return true;
        }

        private static Equipment BuildMountedHeroExactVisualHybridSpawnEquipment(
            ExactTransferSpawnContract contract,
            CreateAgent createAgent)
        {
            Equipment hybridEquipment = contract?.Equipment?.SpawnEquipment?.Clone(false);
            if (hybridEquipment == null)
                return createAgent?.SpawnEquipment?.Clone(false);

            Equipment payloadSpawnEquipment = createAgent?.SpawnEquipment;
            for (EquipmentIndex slot = EquipmentIndex.Weapon0; slot <= EquipmentIndex.Weapon3; slot++)
            {
                if (hybridEquipment[slot].Item != null)
                    continue;

                hybridEquipment[slot] =
                    payloadSpawnEquipment != null
                        ? payloadSpawnEquipment.GetEquipmentFromSlot(slot)
                        : default;
            }

            return hybridEquipment;
        }

        private static MissionEquipment BuildMountedHeroExactVisualHybridMissionEquipment(
            Equipment hybridSpawnEquipment,
            CreateAgent createAgent,
            Banner banner)
        {
            if (hybridSpawnEquipment == null)
                return createAgent?.MissionEquipment;

            MissionEquipment hybridMissionEquipment = new MissionEquipment(hybridSpawnEquipment, banner);
            return hybridMissionEquipment;
        }

        private static void TryCanonicalizeStrictMountedHeroSynchronizeAgentEquipmentPayload(
            SynchronizeAgentSpawnEquipment synchronizeAgentSpawnEquipment,
            Agent agent)
        {
            try
            {
                if (synchronizeAgentSpawnEquipment?.SpawnEquipment == null || agent == null || agent.IsMount)
                    return;

                string entryId = null;
                if (!CoopMissionSpawnLogic.TryResolveAuthoritativeTrackedEntryId(agent, out entryId) &&
                    !CoopMissionSpawnLogic.TryResolveSelectableEntryId(agent, out entryId) &&
                    !ExactTransferContractRuntimeCache.TryGetEntryIdByRiderAgentIndex(agent.Index, out entryId))
                {
                    return;
                }

                RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
                if (entryState == null || !entryState.IsHero || !entryState.IsMounted)
                    return;

                if (!ExactTransferContractRuntimeCache.TryGetContract(entryId, out ExactTransferSpawnContract contract) ||
                    contract?.SpawnPolicy?.UseStrictExactHeroPath != true)
                {
                    return;
                }

                if (!ExactTransferContractRuntimeCache.TryGetValidation(entryId, out ExactTransferValidationResult validation) ||
                    !HasOnlyStrictHeroWeapon2RiskValidationFailure(validation))
                {
                    return;
                }

                Equipment exactEquipment =
                    contract.Equipment?.SpawnEquipment?.Clone(false) ??
                    CoopMissionSpawnLogic.BuildSnapshotEquipmentForExactRuntime(
                        entryState,
                        includeWeapons: true,
                        honorExactVisualContracts: false,
                        includeArmorVisuals: true,
                        includeMountVisuals: true);
                if (exactEquipment == null)
                    return;

                string beforeArmorSummary = BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Head,
                    EquipmentIndex.Body,
                    EquipmentIndex.Leg,
                    EquipmentIndex.Gloves,
                    EquipmentIndex.Cape);
                string beforeMountSummary = BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Horse,
                    EquipmentIndex.HorseHarness);
                var changedSlots = new List<string>();

                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    exactEquipment,
                    EquipmentIndex.Head,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    exactEquipment,
                    EquipmentIndex.Body,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    exactEquipment,
                    EquipmentIndex.Leg,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    exactEquipment,
                    EquipmentIndex.Gloves,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    exactEquipment,
                    EquipmentIndex.Cape,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    exactEquipment,
                    EquipmentIndex.Horse,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    exactEquipment,
                    EquipmentIndex.HorseHarness,
                    changedSlots);

                if (changedSlots.Count == 0)
                    return;

                string afterArmorSummary = BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Head,
                    EquipmentIndex.Body,
                    EquipmentIndex.Leg,
                    EquipmentIndex.Gloves,
                    EquipmentIndex.Cape);
                string afterMountSummary = BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Horse,
                    EquipmentIndex.HorseHarness);
                string weaponSummary = BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);

                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: canonicalized strict mounted hero SynchronizeAgentSpawnEquipment payload to exact armor/mount. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + (entryId ?? "null") +
                    " ChangedSlots=[" + string.Join(", ", changedSlots) + "]" +
                    " PayloadWeaponsAfter={" + weaponSummary + "}" +
                    " PayloadArmorBefore={" + beforeArmorSummary + "}" +
                    " PayloadArmorAfter={" + afterArmorSummary + "}" +
                    " PayloadMountBefore={" + beforeMountSummary + "}" +
                    " PayloadMountAfter={" + afterMountSummary + "}");
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                    "client-synchronize-agent-equipment-canonicalized-strict-mounted-hero",
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + (entryId ?? "null") +
                    " ChangedSlots=[" + string.Join(", ", changedSlots) + "]" +
                    " PayloadWeaponsAfter={" + weaponSummary + "}" +
                    " PayloadArmorBefore={" + beforeArmorSummary + "}" +
                    " PayloadArmorAfter={" + afterArmorSummary + "}" +
                    " PayloadMountBefore={" + beforeMountSummary + "}" +
                    " PayloadMountAfter={" + afterMountSummary + "}");
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: strict mounted hero SynchronizeAgentSpawnEquipment payload canonicalization failed open: " +
                    ex.Message);
            }
        }

        private static void TryCanonicalizeMountedRangedSynchronizeAgentEquipmentPayload(
            SynchronizeAgentSpawnEquipment synchronizeAgentSpawnEquipment,
            Agent agent)
        {
            try
            {
                Equipment spawnEquipment = synchronizeAgentSpawnEquipment?.SpawnEquipment;
                if (spawnEquipment == null || agent == null || agent.IsMount)
                    return;

                if (agent.Character?.IsHero == true || agent.MissionPeer != null)
                    return;

                if (!IsMountedSynchronizeAgentEquipmentCandidate(agent, spawnEquipment))
                    return;

                EquipmentElement slot0 = spawnEquipment.GetEquipmentFromSlot(EquipmentIndex.Weapon0);
                EquipmentElement slot1 = spawnEquipment.GetEquipmentFromSlot(EquipmentIndex.Weapon1);
                EquipmentElement slot2 = spawnEquipment.GetEquipmentFromSlot(EquipmentIndex.Weapon2);
                EquipmentElement slot3 = spawnEquipment.GetEquipmentFromSlot(EquipmentIndex.Weapon3);

                if (!TryBuildCanonicalMountedRangedSynchronizeWeaponOrder(
                        slot0,
                        slot1,
                        slot2,
                        slot3,
                        out EquipmentElement canonicalWeapon0,
                        out EquipmentElement canonicalWeapon1,
                        out EquipmentElement canonicalWeapon2,
                        out EquipmentElement canonicalWeapon3))
                {
                    return;
                }

                spawnEquipment[EquipmentIndex.Weapon0] = canonicalWeapon0;
                spawnEquipment[EquipmentIndex.Weapon1] = canonicalWeapon1;
                spawnEquipment[EquipmentIndex.Weapon2] = canonicalWeapon2;
                spawnEquipment[EquipmentIndex.Weapon3] = canonicalWeapon3;
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: mounted ranged SynchronizeAgentSpawnEquipment payload canonicalization failed open: " +
                    ex.Message);
            }
        }

        private static bool IsMountedSynchronizeAgentEquipmentCandidate(Agent agent, Equipment spawnEquipment)
        {
            if (agent?.MountAgent != null)
                return true;

            if (HasEquipmentItemInSlot(spawnEquipment, EquipmentIndex.Horse) ||
                HasEquipmentItemInSlot(spawnEquipment, EquipmentIndex.HorseHarness))
            {
                return true;
            }

            string entryId = null;
            if (!CoopMissionSpawnLogic.TryResolveAuthoritativeTrackedEntryId(agent, out entryId) &&
                !CoopMissionSpawnLogic.TryResolveSelectableEntryId(agent, out entryId) &&
                !ExactTransferContractRuntimeCache.TryGetEntryIdByRiderAgentIndex(agent.Index, out entryId))
            {
                return false;
            }

            RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
            return entryState?.IsMounted == true;
        }

        private static bool HasEquipmentItemInSlot(Equipment equipment, EquipmentIndex slot)
        {
            if (equipment == null)
                return false;

            EquipmentElement element = equipment.GetEquipmentFromSlot(slot);
            return !element.IsEmpty && element.Item != null;
        }

        private static bool TrySuppressExactSiegeHeroSurrogateSynchronizeAgentEquipmentPayload(
            Mission mission,
            SynchronizeAgentSpawnEquipment synchronizeAgentSpawnEquipment,
            Agent agent,
            out string reason)
        {
            reason = null;
            if (mission == null ||
                synchronizeAgentSpawnEquipment?.SpawnEquipment == null ||
                agent == null ||
                agent.IsMount ||
                GameNetwork.IsServer ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return false;
            }

            if (!agent.IsActive() || agent.Team == null || agent.Team.Side == BattleSideEnum.None)
                return false;

            string entryId = null;
            if (!CoopMissionSpawnLogic.TryResolveAuthoritativeTrackedEntryId(agent, out entryId) &&
                !CoopMissionSpawnLogic.TryResolveSelectableEntryId(agent, out entryId) &&
                !ExactTransferContractRuntimeCache.TryGetEntryIdByRiderAgentIndex(agent.Index, out entryId))
            {
                return false;
            }

            RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
            if (!IsExactHeroEntry(entryState))
                return false;

            if (!TryBuildExactHeroExpectedSpawnEquipment(
                    entryId,
                    entryState,
                    out Equipment expectedEquipment,
                    preferSnapshotWeaponOrder: true))
                return false;

            if (!HasExactHeroWeaponPayloadMismatch(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    expectedEquipment,
                    out string mismatchReason))
            {
                return false;
            }

            ExactTransferContractRuntimeCache.ObserveClientEquipmentSynchronized(
                agent.Index,
                "battle-map handoff exact siege hero surrogate SynchronizeAgentSpawnEquipment suppressed");
            CoopMissionSpawnLogic.ObserveClientSynchronizeAgentEquipment(
                agent.Index,
                "battle-map handoff exact siege hero surrogate SynchronizeAgentSpawnEquipment suppressed");
            ExactCreateAgentCorridorDiagnostics.ObserveClientSynchronizeAgentEquipment(
                synchronizeAgentSpawnEquipment,
                agent,
                "battle-map handoff exact siege hero surrogate SynchronizeAgentSpawnEquipment suppressed");

            bool exactVisualApplied = CoopMissionSpawnLogic.TryFinalizeClientExactCampaignVisualForAgent(
                mission,
                agent,
                preferredEntryId: entryId,
                source: "battle-map handoff exact siege hero surrogate SynchronizeAgentSpawnEquipment suppressed",
                includeWeaponsForClientRefresh: true,
                allowImmediateApply: true);
            bool localControlledAgent = IsLocalMissionPeerControlledAgent(agent);
            bool strictWieldApplied = false;
            string strictWieldResult = localControlledAgent ? "(none)" : "remote-hero-no-local-wield-refresh";
            string strictWieldIssue = "(none)";
            if (localControlledAgent)
            {
                CoopMissionSpawnLogic.InvalidateStrictExactHeroLocalInitialWieldAppliedMarker(
                    agent,
                    entryId,
                    "battle-map handoff exact siege hero surrogate SynchronizeAgentSpawnEquipment suppressed",
                    mismatchReason ?? "surrogate-synchronize-agent-equipment");
                strictWieldApplied = CoopMissionSpawnLogic.TryApplyStrictExactHeroLocalInitialWield(
                    agent,
                    entryId,
                    "battle-map handoff exact siege hero surrogate SynchronizeAgentSpawnEquipment suppressed",
                    out strictWieldResult,
                    out strictWieldIssue);
            }

            reason =
                (mismatchReason ?? "exact-siege-hero-surrogate-equipment-payload") +
                "|EntryId=" + (entryId ?? "null") +
                "|ExpectedWeapons={" + BuildEquipmentSummary(
                    expectedEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3) + "}" +
                "|PayloadWeapons={" + BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3) + "}" +
                "|ExactVisualApplied=" + exactVisualApplied +
                "|StrictWieldApplied=" + strictWieldApplied +
                "|StrictWieldResult=" + (strictWieldResult ?? "(none)") +
                "|StrictWieldIssue=" + (strictWieldIssue ?? "(none)");
            CoopMissionSpawnLogic.TraceClientMountedHeroNetworkContract(
                agent,
                "client-synchronize-agent-equipment-suppressed",
                "battle-map handoff exact siege hero surrogate SynchronizeAgentSpawnEquipment suppressed",
                reason);
            ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                "client-synchronize-agent-equipment-suppressed-exact-siege-hero-surrogate",
                "AgentIndex=" + agent.Index +
                " CharacterId=" + (agent.Character?.StringId ?? "null") +
                " " + reason);
            return true;
        }

        private static bool IsExactHeroEntry(RosterEntryState entryState)
        {
            return entryState != null &&
                   (entryState.IsHero ||
                    !string.IsNullOrWhiteSpace(entryState.HeroId) ||
                    string.Equals(entryState.OriginalCharacterId, "main_hero", StringComparison.OrdinalIgnoreCase));
        }

        private static bool IsLocalMissionPeerControlledAgent(Agent agent)
        {
            if (agent == null || GameNetwork.IsServer)
                return false;

            MissionPeer localMissionPeer = GameNetwork.MyPeer?.GetComponent<MissionPeer>();
            Agent controlledAgent = localMissionPeer?.ControlledAgent;
            return controlledAgent != null && ReferenceEquals(controlledAgent, agent);
        }

        private static bool TryBuildExactHeroExpectedSpawnEquipment(
            string entryId,
            RosterEntryState entryState,
            out Equipment expectedEquipment,
            bool preferSnapshotWeaponOrder = false)
        {
            expectedEquipment = null;
            if (entryState == null)
                return false;

            if (!preferSnapshotWeaponOrder &&
                !string.IsNullOrWhiteSpace(entryId) &&
                ExactTransferContractRuntimeCache.TryGetContract(entryId, out ExactTransferSpawnContract contract))
            {
                expectedEquipment = contract?.Equipment?.SpawnEquipment?.Clone(false);
            }

            if (expectedEquipment == null)
            {
                expectedEquipment = CoopMissionSpawnLogic.BuildSnapshotEquipmentForExactRuntime(
                    entryState,
                    includeWeapons: true,
                    honorExactVisualContracts: false,
                    includeArmorVisuals: true,
                    includeMountVisuals: false);
            }

            return expectedEquipment != null;
        }

        private static bool HasExactHeroWeaponPayloadMismatch(
            Equipment payloadEquipment,
            Equipment expectedEquipment,
            out string reason)
        {
            reason = null;
            if (payloadEquipment == null || expectedEquipment == null)
                return false;

            int expectedWeaponCount = 0;
            int payloadWeaponCount = 0;
            var mismatches = new List<string>();
            for (EquipmentIndex slot = EquipmentIndex.Weapon0; slot <= EquipmentIndex.Weapon3; slot++)
            {
                EquipmentElement expectedElement = expectedEquipment[slot];
                EquipmentElement payloadElement = payloadEquipment[slot];
                string expectedItemId = expectedElement.Item?.StringId;
                string payloadItemId = payloadElement.Item?.StringId;
                if (!string.IsNullOrWhiteSpace(expectedItemId))
                    expectedWeaponCount++;
                if (!string.IsNullOrWhiteSpace(payloadItemId))
                    payloadWeaponCount++;

                if (string.Equals(expectedItemId ?? string.Empty, payloadItemId ?? string.Empty, StringComparison.OrdinalIgnoreCase))
                    continue;

                if (mismatches.Count < 6)
                {
                    mismatches.Add(
                        slot +
                        ":expected=" + (string.IsNullOrWhiteSpace(expectedItemId) ? "empty" : expectedItemId) +
                        ",payload=" + (string.IsNullOrWhiteSpace(payloadItemId) ? "empty" : payloadItemId));
                }
            }

            if (expectedWeaponCount <= 0 || mismatches.Count <= 0)
                return false;

            reason =
                "exact-siege-hero-weapon-payload-mismatch" +
                "|ExpectedWeaponCount=" + expectedWeaponCount +
                "|PayloadWeaponCount=" + payloadWeaponCount +
                "|Mismatches=[" + string.Join("; ", mismatches) + "]";
            return true;
        }

        private static bool TryBuildCanonicalMountedRangedSynchronizeWeaponOrder(
            EquipmentElement slot0,
            EquipmentElement slot1,
            EquipmentElement slot2,
            EquipmentElement slot3,
            out EquipmentElement canonicalWeapon0,
            out EquipmentElement canonicalWeapon1,
            out EquipmentElement canonicalWeapon2,
            out EquipmentElement canonicalWeapon3)
        {
            canonicalWeapon0 = default;
            canonicalWeapon1 = default;
            canonicalWeapon2 = default;
            canonicalWeapon3 = default;

            EquipmentElement[] sourceSlots =
            {
                slot0,
                slot1,
                slot2,
                slot3
            };
            SynchronizeMountedWeaponRole[] sourceRoles =
            {
                ResolveSynchronizeMountedWeaponRole(slot0.Item),
                ResolveSynchronizeMountedWeaponRole(slot1.Item),
                ResolveSynchronizeMountedWeaponRole(slot2.Item),
                ResolveSynchronizeMountedWeaponRole(slot3.Item)
            };

            bool hasRanged = sourceRoles.Any(role => role == SynchronizeMountedWeaponRole.Ranged);
            bool hasAmmo = sourceRoles.Any(role => role == SynchronizeMountedWeaponRole.Ammo);
            if (!hasRanged || !hasAmmo)
                return false;

            var usedIndices = new HashSet<int>();
            if (!TryTakeSynchronizeWeaponSlotByRole(
                    sourceSlots,
                    sourceRoles,
                    usedIndices,
                    SynchronizeMountedWeaponRole.Ranged,
                    out canonicalWeapon0))
            {
                return false;
            }

            if (!TryTakeSynchronizeWeaponSlotByRole(
                    sourceSlots,
                    sourceRoles,
                    usedIndices,
                    SynchronizeMountedWeaponRole.Ammo,
                    out canonicalWeapon1))
            {
                return false;
            }

            if (!TryTakeSynchronizeWeaponSlotByRole(
                    sourceSlots,
                    sourceRoles,
                    usedIndices,
                    SynchronizeMountedWeaponRole.Polearm,
                    out canonicalWeapon2) &&
                !TryTakeSynchronizeWeaponSlotByRole(
                    sourceSlots,
                    sourceRoles,
                    usedIndices,
                    SynchronizeMountedWeaponRole.Melee,
                    out canonicalWeapon2))
            {
                if (!TryTakeSynchronizeWeaponSlotByRole(
                        sourceSlots,
                        sourceRoles,
                        usedIndices,
                        SynchronizeMountedWeaponRole.Shield,
                        out canonicalWeapon2))
                {
                    TryTakeNextUnusedSynchronizeWeaponSlot(
                        sourceSlots,
                        usedIndices,
                        out canonicalWeapon2);
                }
            }

            if (!TryTakeSynchronizeWeaponSlotByRole(
                    sourceSlots,
                    sourceRoles,
                    usedIndices,
                    SynchronizeMountedWeaponRole.Shield,
                    out canonicalWeapon3))
            {
                TryTakeNextUnusedSynchronizeWeaponSlot(
                    sourceSlots,
                    usedIndices,
                    out canonicalWeapon3);
            }

            return true;
        }

        private static bool TryTakeSynchronizeWeaponSlotByRole(
            EquipmentElement[] sourceSlots,
            SynchronizeMountedWeaponRole[] sourceRoles,
            HashSet<int> usedIndices,
            SynchronizeMountedWeaponRole role,
            out EquipmentElement element)
        {
            element = default;
            if (sourceSlots == null || sourceRoles == null || usedIndices == null)
                return false;

            for (int i = 0; i < sourceSlots.Length && i < sourceRoles.Length; i++)
            {
                if (usedIndices.Contains(i) || sourceRoles[i] != role)
                    continue;

                usedIndices.Add(i);
                element = sourceSlots[i];
                return true;
            }

            return false;
        }

        private static bool TryTakeNextUnusedSynchronizeWeaponSlot(
            EquipmentElement[] sourceSlots,
            HashSet<int> usedIndices,
            out EquipmentElement element)
        {
            element = default;
            if (sourceSlots == null || usedIndices == null)
                return false;

            for (int i = 0; i < sourceSlots.Length; i++)
            {
                if (usedIndices.Contains(i))
                    continue;

                usedIndices.Add(i);
                element = sourceSlots[i];
                return true;
            }

            return false;
        }

        private static SynchronizeMountedWeaponRole ResolveSynchronizeMountedWeaponRole(ItemObject item)
        {
            if (item == null)
                return SynchronizeMountedWeaponRole.Other;

            WeaponComponentData primaryWeapon = item.PrimaryWeapon;
            if (primaryWeapon != null)
            {
                if (primaryWeapon.IsShield)
                    return SynchronizeMountedWeaponRole.Shield;
                if (primaryWeapon.IsPolearm)
                    return SynchronizeMountedWeaponRole.Polearm;
                if (primaryWeapon.IsAmmo)
                    return SynchronizeMountedWeaponRole.Ammo;
                if (primaryWeapon.IsRangedWeapon ||
                    primaryWeapon.WeaponClass == WeaponClass.Javelin ||
                    primaryWeapon.WeaponClass == WeaponClass.ThrowingAxe ||
                    primaryWeapon.WeaponClass == WeaponClass.ThrowingKnife ||
                    primaryWeapon.WeaponClass == WeaponClass.Stone ||
                    primaryWeapon.WeaponClass == WeaponClass.SlingStone)
                {
                    return SynchronizeMountedWeaponRole.Ranged;
                }

                if (primaryWeapon.IsOneHanded || primaryWeapon.IsTwoHanded || primaryWeapon.IsMeleeWeapon)
                    return SynchronizeMountedWeaponRole.Melee;
            }

            switch (item.ItemType)
            {
                case ItemObject.ItemTypeEnum.Shield:
                    return SynchronizeMountedWeaponRole.Shield;
                case ItemObject.ItemTypeEnum.Polearm:
                    return SynchronizeMountedWeaponRole.Polearm;
                case ItemObject.ItemTypeEnum.Bow:
                case ItemObject.ItemTypeEnum.Crossbow:
                case ItemObject.ItemTypeEnum.Sling:
                case ItemObject.ItemTypeEnum.Thrown:
                    return SynchronizeMountedWeaponRole.Ranged;
                case ItemObject.ItemTypeEnum.Arrows:
                case ItemObject.ItemTypeEnum.Bolts:
                case ItemObject.ItemTypeEnum.SlingStones:
                    return SynchronizeMountedWeaponRole.Ammo;
                case ItemObject.ItemTypeEnum.OneHandedWeapon:
                case ItemObject.ItemTypeEnum.TwoHandedWeapon:
                    return SynchronizeMountedWeaponRole.Melee;
                default:
                    return SynchronizeMountedWeaponRole.Other;
            }
        }

        private static void CanonicalizeSynchronizeAgentEquipmentSlot(
            Equipment targetEquipment,
            Equipment sourceEquipment,
            EquipmentIndex slot,
            List<string> changedSlots)
        {
            if (targetEquipment == null || sourceEquipment == null)
                return;

            EquipmentElement currentElement = targetEquipment.GetEquipmentFromSlot(slot);
            EquipmentElement exactElement = sourceEquipment.GetEquipmentFromSlot(slot);
            string currentItemId = currentElement.Item?.StringId ?? string.Empty;
            string exactItemId = exactElement.Item?.StringId ?? string.Empty;
            if (string.Equals(currentItemId, exactItemId, StringComparison.Ordinal))
                return;

            targetEquipment[slot] = exactElement;
            changedSlots?.Add(
                slot + "=" +
                (currentItemId.Length > 0 ? currentItemId : "empty") +
                "->" +
                (exactItemId.Length > 0 ? exactItemId : "empty"));
        }

        private static bool TryCopyHybridWeaponSlotsFromMissionEquipment(
            Equipment targetEquipment,
            MissionEquipment missionEquipment)
        {
            if (targetEquipment == null || missionEquipment == null)
                return false;

            bool copiedAny = false;
            for (EquipmentIndex slot = EquipmentIndex.Weapon0; slot <= EquipmentIndex.Weapon3; slot++)
            {
                MissionWeapon payloadMissionWeapon = missionEquipment[slot];
                if (payloadMissionWeapon.IsEmpty || payloadMissionWeapon.Item == null)
                    continue;

                targetEquipment[slot] = new EquipmentElement(
                    payloadMissionWeapon.Item,
                    payloadMissionWeapon.ItemModifier,
                    null,
                    false);
                copiedAny = true;
            }

            return copiedAny;
        }

        private static bool DoesRosterEntryStateMatchBattleSide(RosterEntryState entryState, BattleSideEnum side)
        {
            if (entryState == null || side == BattleSideEnum.None)
                return false;

            string sideId = entryState.SideId ?? string.Empty;
            return side == BattleSideEnum.Attacker
                ? string.Equals(sideId, "Attacker", StringComparison.OrdinalIgnoreCase)
                : side == BattleSideEnum.Defender &&
                  string.Equals(sideId, "Defender", StringComparison.OrdinalIgnoreCase);
        }

        private static Team ResolveCreateAgentMissionTeam(Mission mission, int teamIndex)
        {
            if (mission == null)
                return null;

            Team teamFromTeamIndex = Mission.MissionNetworkHelper.GetTeamFromTeamIndex(teamIndex);
            if (teamFromTeamIndex != null && teamFromTeamIndex.Side != BattleSideEnum.None)
                return teamFromTeamIndex;

            BattleSideEnum payloadSide = ResolveCreateAgentPayloadBattleSideForPatch(teamIndex);
            if (payloadSide == BattleSideEnum.Attacker)
                return mission.AttackerTeam ?? mission.Teams?.Attacker;

            if (payloadSide == BattleSideEnum.Defender)
                return mission.DefenderTeam ?? mission.Teams?.Defender;

            return teamFromTeamIndex;
        }

        private static Formation ResolveCreateAgentFormationForProjection(
            Mission mission,
            Team team,
            CreateAgent createAgent,
            BasicCharacterObject character)
        {
            if (mission == null ||
                team == null ||
                createAgent == null ||
                createAgent.FormationIndex < 0 ||
                GameNetwork.IsReplay)
            {
                return null;
            }

            FormationClass formationClass = (FormationClass)createAgent.FormationIndex;
            if (ShouldUseDismountedSiegeCreateAgentFormation(mission, team, character))
            {
                try
                {
                    formationClass = mission.GetAgentTroopClass(team.Side, character).FallbackClass();
                }
                catch
                {
                    formationClass = character?.DefaultFormationClass.FallbackClass() ?? FormationClass.Infantry;
                }

                formationClass = DismountSiegeCreateAgentFormationClass(formationClass);
            }

            int formationIndex = (int)formationClass;
            if (formationIndex < 0 || formationIndex >= (int)FormationClass.NumberOfRegularFormations)
                formationClass = FormationClass.Infantry;

            return team.GetFormation(formationClass);
        }

        private static bool ShouldUseDismountedSiegeCreateAgentFormation(
            Mission mission,
            Team team,
            BasicCharacterObject character)
        {
            if (mission == null || team == null || character == null || team.Side == BattleSideEnum.None)
                return false;

            BattleScenarioContextMessage scenarioContext =
                BattleSnapshotRuntimeState.GetScenarioContext() ??
                BattleSnapshotRuntimeState.GetCurrent()?.ScenarioContext ??
                BattleSnapshotRuntimeState.GetState()?.ScenarioContext;
            if (!ExactCampaignSiegeAssaultWithDeploymentRuntime.IsExactSiegeWithDeploymentScenario(scenarioContext))
                return false;

            if (CoopMissionSpawnLogic.ShouldUseFieldMaterializedSiegeReplayRuntime(mission))
                return true;

            if (ExactCampaignArmyBootstrap.TryGetSpawnHorses(mission, team.Side, out bool spawnHorses))
                return !spawnHorses;

            try
            {
                return mission.IsSiegeBattle;
            }
            catch
            {
                return true;
            }
        }

        private static FormationClass DismountSiegeCreateAgentFormationClass(FormationClass formationClass)
        {
            if (formationClass == FormationClass.Cavalry)
                return FormationClass.Infantry;

            if (formationClass == FormationClass.HorseArcher)
                return FormationClass.Ranged;

            return formationClass;
        }

        private static BattleSideEnum ResolveCreateAgentPayloadBattleSideForPatch(int teamIndex)
        {
            Team missionTeam = Mission.MissionNetworkHelper.GetTeamFromTeamIndex(teamIndex);
            if (missionTeam != null && missionTeam.Side != BattleSideEnum.None)
                return missionTeam.Side;

            if (teamIndex == 0)
                return BattleSideEnum.Attacker;

            if (teamIndex == 1)
                return BattleSideEnum.Defender;

            return BattleSideEnum.None;
        }

        private static bool IsMountedHeroTemplatePayload(CreateAgent createAgent)
        {
            if (createAgent?.Character == null || createAgent.MountAgentIndex < 0)
                return false;

            string characterId = createAgent.Character.StringId ?? string.Empty;
            return createAgent.Character.IsHero ||
                   characterId.EndsWith("_hero", StringComparison.Ordinal);
        }

        private static BasicCharacterObject ResolveStrictExactHeroCreateAgentCharacter(
            CreateAgent createAgent,
            ExactTransferSpawnContract contract)
        {
            if (contract?.EntryId != null)
            {
                BasicCharacterObject contractCharacter = BattleSnapshotRuntimeState.TryResolveCharacterObject(contract.EntryId);
                if (contractCharacter != null)
                    return contractCharacter;
            }

            if (!string.IsNullOrWhiteSpace(contract?.Identity?.NativeMultiplayerCharacterId))
            {
                try
                {
                    BasicCharacterObject character =
                        MBObjectManager.Instance.GetObject<BasicCharacterObject>(contract.Identity.NativeMultiplayerCharacterId);
                    if (character != null)
                        return character;
                }
                catch
                {
                }
            }

            return createAgent?.Character;
        }

        private static Equipment ResolveStrictExactHeroCreateAgentSpawnEquipment(
            ExactTransferSpawnContract contract,
            CreateAgent createAgent)
        {
            if (contract?.Equipment?.SpawnEquipment != null)
                return contract.Equipment.SpawnEquipment.Clone(false);

            return createAgent?.SpawnEquipment?.Clone(false);
        }

        private static MissionEquipment ResolveStrictExactHeroCreateAgentMissionEquipment(
            Equipment createTimeSpawnEquipment,
            Banner banner,
            CreateAgent createAgent)
        {
            if (createTimeSpawnEquipment != null)
                return new MissionEquipment(createTimeSpawnEquipment, banner);

            return createAgent?.MissionEquipment;
        }

        private static Banner ResolveStrictExactHeroCreateAgentBanner(Team team, Formation formation)
        {
            if (team == null)
                return null;

            string fallbackBannerCode =
                !string.IsNullOrWhiteSpace(formation?.BannerCode)
                    ? formation.BannerCode
                    : team.Banner?.BannerCode;
            string bannerCode = BattleSnapshotRuntimeState.ResolveSideBannerCode(team.Side, fallbackBannerCode);
            if (string.IsNullOrWhiteSpace(bannerCode))
                return formation?.Banner ?? team.Banner;

            if (formation != null &&
                string.Equals(formation.BannerCode ?? string.Empty, bannerCode, StringComparison.Ordinal) &&
                formation.Banner != null)
            {
                return formation.Banner;
            }

            uint color = BattleSnapshotRuntimeState.ResolveSideColor(team.Side, team.Color);
            uint color2 = BattleSnapshotRuntimeState.ResolveSideColor2(team.Side, team.Color2);
            try
            {
                Banner banner = new Banner(bannerCode, color, color2);
                if (formation != null)
                {
                    formation.BannerCode = bannerCode;
                    formation.Banner = banner;
                }

                return banner;
            }
            catch
            {
            }

            return formation?.Banner ?? team.Banner;
        }

        private static void TryEnsureExactSiegeAgentOriginBanner(
            Mission mission,
            Agent agent)
        {
            if (GameNetwork.IsServer ||
                mission == null ||
                agent == null ||
                agent.IsMount ||
                !agent.IsHuman ||
                !agent.IsActive() ||
                agent.Team == null ||
                agent.Team.Side == BattleSideEnum.None ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return;
            }

            Banner banner = ResolveStrictExactHeroCreateAgentBanner(agent.Team, agent.Formation);
            if (banner == null)
                return;

            IAgentOriginBase origin = agent.Origin;
            if (origin == null)
            {
                if (agent.Character == null)
                    return;

                origin = new BasicBattleAgentOrigin(agent.Character);
            }

            IAgentOriginBase bannerAwareOrigin = BannerAwareAgentOrigin.Ensure(origin, banner);
            if (bannerAwareOrigin == null)
                return;

            agent.Origin = bannerAwareOrigin;
        }

        private static void CanonicalizeCreateAgentPayloadForBattleMap(CreateAgent createAgent)
        {
            if (createAgent == null)
                return;

            bool coercedRemotePlayerAgent = false;
            bool strippedRemotePeer = false;
            bool canonicalizedCharacter = false;
            bool repairedBodyPropertyRange = false;
            string characterSource = null;
            string bodyPropertyRangeSource = null;

            canonicalizedCharacter = TryCanonicalizeCreateAgentCharacterToResolvedSurrogate(
                createAgent,
                out characterSource);

            if (ShouldCoerceRemotePlayerCreateAgentToNonPlayer(createAgent))
            {
                TrySetInstanceMemberValue(createAgent, "IsPlayerAgent", false);
                TrySetInstanceMemberValue(createAgent, "<IsPlayerAgent>k__BackingField", false);
                coercedRemotePlayerAgent = !createAgent.IsPlayerAgent;
            }

            if (ShouldStripRemotePeerFromCreateAgentPayload(createAgent))
            {
                TrySetInstanceMemberValue(createAgent, "Peer", null);
                TrySetInstanceMemberValue(createAgent, "<Peer>k__BackingField", null);
                strippedRemotePeer = createAgent.Peer == null;
            }

            repairedBodyPropertyRange = TryEnsureCreateAgentCharacterBodyPropertyRange(
                createAgent.Character,
                out bodyPropertyRangeSource);

            if (!coercedRemotePlayerAgent &&
                !strippedRemotePeer &&
                !canonicalizedCharacter &&
                !repairedBodyPropertyRange)
            {
                return;
            }

            string details =
                "AgentIndex=" + createAgent.AgentIndex +
                " Character=" + (createAgent.Character?.StringId ?? "null") +
                " PeerIndex=" + (createAgent.Peer?.Index.ToString() ?? "null") +
                " MountAgentIndex=" + createAgent.MountAgentIndex +
                " CoercedRemotePlayerAgent=" + coercedRemotePlayerAgent +
                " StrippedRemotePeer=" + strippedRemotePeer +
                " EffectiveIsPlayerAgent=" + createAgent.IsPlayerAgent +
                " CanonicalizedCharacter=" + canonicalizedCharacter +
                " CharacterSource=" + (characterSource ?? "none") +
                " RepairedBodyPropertyRange=" + repairedBodyPropertyRange +
                " BodyPropertyRangeSource=" + (bodyPropertyRangeSource ?? "none");
            ModLogger.Info(
                "BattleMapSpawnHandoffPatch: canonicalized CreateAgent payload before native handler. " +
                details);
            ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                "client-create-agent-payload-canonicalized",
                details + " Source=battle-map handoff CreateAgent prefix");
            ExactCreateAgentCorridorDiagnostics.ObserveClientCreateAgentMutation(
                createAgent,
                details,
                "battle-map handoff CreateAgent prefix");
        }

        private static bool ShouldCoerceRemotePlayerCreateAgentToNonPlayer(CreateAgent createAgent)
        {
            if (createAgent == null ||
                !createAgent.IsPlayerAgent ||
                createAgent.Peer == null ||
                createAgent.Peer.IsMine ||
                createAgent.MountAgentIndex < 0)
            {
                return false;
            }

            string characterId = createAgent.Character?.StringId ?? string.Empty;
            return createAgent.Character?.IsHero == true ||
                   characterId.EndsWith("_hero", StringComparison.Ordinal);
        }

        private static bool ShouldStripRemotePeerFromCreateAgentPayload(CreateAgent createAgent)
        {
            if (createAgent?.Peer == null || createAgent.Peer.IsMine || createAgent.MountAgentIndex < 0)
                return false;

            string characterId = createAgent.Character?.StringId ?? string.Empty;
            return createAgent.Character?.IsHero == true ||
                   characterId.EndsWith("_hero", StringComparison.Ordinal);
        }

        private static bool TryCanonicalizeCreateAgentCharacterToResolvedSurrogate(
            CreateAgent createAgent,
            out string source)
        {
            source = null;
            if (createAgent?.Character == null)
                return false;

            if (!CampaignMultiplayerHeroClassResolver.TryResolve(
                    createAgent.Character,
                    out MultiplayerClassDivisions.MPHeroClass resolvedClass,
                    out bool treatAsTroop,
                    out string _))
            {
                return false;
            }

            BasicCharacterObject canonicalCharacter = treatAsTroop
                ? resolvedClass?.TroopCharacter ?? resolvedClass?.HeroCharacter
                : resolvedClass?.HeroCharacter ?? resolvedClass?.TroopCharacter;
            if (canonicalCharacter == null)
                return false;

            string originalCharacterId = createAgent.Character.StringId ?? string.Empty;
            string canonicalCharacterId = canonicalCharacter.StringId ?? string.Empty;
            if (ReferenceEquals(canonicalCharacter, createAgent.Character) ||
                string.Equals(originalCharacterId, canonicalCharacterId, StringComparison.Ordinal))
            {
                return false;
            }

            TrySetInstanceMemberValue(createAgent, "Character", canonicalCharacter);
            TrySetInstanceMemberValue(createAgent, "<Character>k__BackingField", canonicalCharacter);
            source = (treatAsTroop ? "resolved-class-troop" : "resolved-class-hero") +
                     ":" + canonicalCharacterId;
            return ReferenceEquals(createAgent.Character, canonicalCharacter) ||
                   string.Equals(createAgent.Character?.StringId, canonicalCharacterId, StringComparison.Ordinal);
        }

        private static bool TryEnsureCreateAgentCharacterBodyPropertyRange(
            BasicCharacterObject character,
            out string source)
        {
            source = null;
            if (character == null)
                return false;

            try
            {
                if (character.BodyPropertyRange != null)
                    return false;
            }
            catch
            {
            }

            if (!CampaignMultiplayerHeroClassResolver.TryResolve(
                    character,
                    out MultiplayerClassDivisions.MPHeroClass resolvedClass,
                    out bool treatAsTroop,
                    out string _))
            {
                return false;
            }

            var fallbackCharacters = new List<(BasicCharacterObject Character, string Source)>();
            if (treatAsTroop)
            {
                fallbackCharacters.Add((resolvedClass?.TroopCharacter, "resolved-class-troop"));
                fallbackCharacters.Add((resolvedClass?.HeroCharacter, "resolved-class-hero"));
            }
            else
            {
                fallbackCharacters.Add((resolvedClass?.HeroCharacter, "resolved-class-hero"));
                fallbackCharacters.Add((resolvedClass?.TroopCharacter, "resolved-class-troop"));
            }

            foreach ((BasicCharacterObject fallbackCharacter, string fallbackSource) in fallbackCharacters)
            {
                if (fallbackCharacter == null || ReferenceEquals(fallbackCharacter, character))
                    continue;

                MBBodyProperty fallbackRange = null;
                try
                {
                    fallbackRange = fallbackCharacter.BodyPropertyRange;
                }
                catch
                {
                }

                if (fallbackRange == null)
                    continue;

                TrySetInstanceMemberValue(character, "BodyPropertyRange", fallbackRange);
                TrySetInstanceMemberValue(character, "<BodyPropertyRange>k__BackingField", fallbackRange);
                source = fallbackSource + ":" + (fallbackCharacter.StringId ?? "null");
                try
                {
                    return character.BodyPropertyRange != null;
                }
                catch
                {
                    return true;
                }
            }

            return false;
        }

        private static bool MissionNetworkComponent_HandleServerEventSynchronizeAgentEquipment_Prefix(GameNetworkMessage baseMessage)
        {
            try
            {
                if (!(baseMessage is SynchronizeAgentSpawnEquipment synchronizeAgentSpawnEquipment))
                    return true;

                Mission mission = Mission.Current;
                if (!ShouldRunAgentMaterializationHandoff(mission))
                    return true;

                if (!ShouldUseSafeStringIdCreateAgentPathOnClient(mission))
                    return true;

                if (!CoopMissionNetworkBridge.IsClientCurrentBattleSnapshotApplied(out string snapshotReadinessSummary))
                {
                    RegisterDeferredClientSynchronizeAgentEquipmentPayload(
                        synchronizeAgentSpawnEquipment,
                        "snapshot-not-ready:" + (snapshotReadinessSummary ?? "unknown"));
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: deferred client SynchronizeAgentSpawnEquipment until current battle snapshot is applied. " +
                        "AgentIndex=" + synchronizeAgentSpawnEquipment.AgentIndex +
                        " Reason=" + (snapshotReadinessSummary ?? "unknown"));
                    return false;
                }

                Agent agent = Mission.MissionNetworkHelper.GetAgentFromIndex(synchronizeAgentSpawnEquipment.AgentIndex, canBeNull: true);
                if (agent != null)
                {
                    TryEnsureExactSiegeAgentOriginBanner(
                        mission,
                        agent);
                }
                if (agent == null && HasDeferredClientCreateAgentPayload(synchronizeAgentSpawnEquipment.AgentIndex))
                {
                    RegisterDeferredClientSynchronizeAgentEquipmentPayload(
                        synchronizeAgentSpawnEquipment,
                        "agent-createagent-deferred");
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: deferred client SynchronizeAgentSpawnEquipment because CreateAgent is still deferred. " +
                        "AgentIndex=" + synchronizeAgentSpawnEquipment.AgentIndex);
                    return false;
                }

                if (agent == null)
                    return false;

                if (agent != null &&
                    CoopMissionSpawnLogic.ShouldClearDismountedSiegeSynchronizeAgentMountVisuals(
                        mission,
                        agent,
                        synchronizeAgentSpawnEquipment.SpawnEquipment))
                {
                    synchronizeAgentSpawnEquipment.SpawnEquipment[EquipmentIndex.Horse] = default(EquipmentElement);
                    synchronizeAgentSpawnEquipment.SpawnEquipment[EquipmentIndex.HorseHarness] = default(EquipmentElement);
                }

                if (agent != null &&
                    TrySuppressExactSiegeHeroSurrogateSynchronizeAgentEquipmentPayload(
                        mission,
                        synchronizeAgentSpawnEquipment,
                        agent,
                        out string exactSiegeHeroSurrogateSyncReason))
                {
                    string payloadSummary = BuildEquipmentSummary(
                        synchronizeAgentSpawnEquipment.SpawnEquipment,
                        EquipmentIndex.Weapon0,
                        EquipmentIndex.Weapon1,
                        EquipmentIndex.Weapon2,
                        EquipmentIndex.Weapon3,
                        EquipmentIndex.Head,
                        EquipmentIndex.Body,
                        EquipmentIndex.Leg,
                        EquipmentIndex.Gloves,
                        EquipmentIndex.Cape,
                        EquipmentIndex.Horse,
                        EquipmentIndex.HorseHarness);
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: suppressed exact siege hero surrogate SynchronizeAgentSpawnEquipment payload before native handler. " +
                        "AgentIndex=" + agent.Index +
                        " CharacterId=" + (agent.Character?.StringId ?? "null") +
                        " Reason=" + (exactSiegeHeroSurrogateSyncReason ?? "unknown") +
                        " PayloadEquipment={" + payloadSummary + "}");
                    return false;
                }

                if (agent != null &&
                    TrySuppressExactSiegeCreateTimeMaterializedSynchronizeAgentEquipmentPayload(
                        mission,
                        synchronizeAgentSpawnEquipment,
                        agent,
                        out string createTimeMaterializedSyncReason))
                {
                    ExactTransferContractRuntimeCache.ObserveClientEquipmentSynchronized(
                        agent.Index,
                        "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-create-time-materialized");
                    CoopMissionSpawnLogic.ObserveClientSynchronizeAgentEquipment(
                        agent.Index,
                        "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-create-time-materialized");
                    ExactCreateAgentCorridorDiagnostics.ObserveClientSynchronizeAgentEquipment(
                        synchronizeAgentSpawnEquipment,
                        agent,
                        "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-create-time-materialized");

                    if (ExperimentalFeatures.EnableExactCreateAgentCorridorDiagnostics)
                    {
                        string payloadSummary = BuildEquipmentSummary(
                            synchronizeAgentSpawnEquipment.SpawnEquipment,
                            EquipmentIndex.Weapon0,
                            EquipmentIndex.Weapon1,
                            EquipmentIndex.Weapon2,
                            EquipmentIndex.Weapon3,
                            EquipmentIndex.Head,
                            EquipmentIndex.Body,
                            EquipmentIndex.Leg,
                            EquipmentIndex.Gloves,
                            EquipmentIndex.Cape,
                            EquipmentIndex.Horse,
                            EquipmentIndex.HorseHarness);
                        string missionWeaponSummary = BuildMissionEquipmentWeaponSummary(agent.Equipment);
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: suppressed exact siege create-time materialized SynchronizeAgentSpawnEquipment payload before native refresh. " +
                            "AgentIndex=" + agent.Index +
                            " CharacterId=" + (agent.Character?.StringId ?? "null") +
                            " Reason=" + (createTimeMaterializedSyncReason ?? "unknown") +
                            " MissionWeapons={" + missionWeaponSummary + "}" +
                            " PayloadEquipment={" + payloadSummary + "}");
                        ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                            "client-synchronize-agent-equipment-suppressed-create-time-materialized",
                            "AgentIndex=" + agent.Index +
                            " CharacterId=" + (agent.Character?.StringId ?? "null") +
                            " Reason=" + (createTimeMaterializedSyncReason ?? "unknown") +
                            " MissionWeapons={" + missionWeaponSummary + "}" +
                            " PayloadEquipment={" + payloadSummary + "}" +
                            " Source=battle-map handoff SynchronizeAgentSpawnEquipment suppressed-create-time-materialized");
                    }

                    return false;
                }

                TryCanonicalizeExactHeroSynchronizeAgentEquipmentWeaponSlots(
                    mission,
                    synchronizeAgentSpawnEquipment,
                    agent);
                TryCanonicalizeStrictMountedHeroSynchronizeAgentEquipmentPayload(
                    synchronizeAgentSpawnEquipment,
                    agent);
                // SynchronizeAgentSpawnEquipment and every later weapon-state message use the
                // server's slot indices as one shared contract. Reordering a non-hero payload
                // only on the client makes a later SetWieldedItemIndex target another item.

                if (agent != null &&
                    ShouldSuppressCorruptedClientSynchronizeAgentEquipmentPayload(
                        synchronizeAgentSpawnEquipment,
                        out string corruptionReason))
                {
                    ExactTransferContractRuntimeCache.ObserveClientEquipmentSynchronized(
                        agent.Index,
                        "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-corrupt");
                    CoopMissionSpawnLogic.ObserveClientSynchronizeAgentEquipment(
                        agent.Index,
                        "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-corrupt");
                    ExactCreateAgentCorridorDiagnostics.ObserveClientSynchronizeAgentEquipment(
                        synchronizeAgentSpawnEquipment,
                        agent,
                        "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-corrupt");

                    bool heroExactVisualApplied = CoopMissionSpawnLogic.TryFinalizeClientExactCampaignVisualForAgent(
                        mission,
                        agent,
                        preferredEntryId: null,
                        source: "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-corrupt",
                        includeWeaponsForClientRefresh: true,
                        allowImmediateApply: true);
                    bool troopExactVisualApplied = false;
                    if (!heroExactVisualApplied)
                    {
                        troopExactVisualApplied = CoopMissionSpawnLogic.TryFinalizeClientExactCampaignTroopVisualForPeerAgent(
                            mission,
                            agent,
                            "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-corrupt",
                            includeWeaponsForClientRefresh: true,
                            allowImmediateApply: true);
                    }

                    string payloadSummary = BuildEquipmentSummary(
                        synchronizeAgentSpawnEquipment.SpawnEquipment,
                        EquipmentIndex.Weapon0,
                        EquipmentIndex.Weapon1,
                        EquipmentIndex.Weapon2,
                        EquipmentIndex.Weapon3,
                        EquipmentIndex.Head,
                        EquipmentIndex.Body,
                        EquipmentIndex.Leg,
                        EquipmentIndex.Gloves,
                        EquipmentIndex.Cape,
                        EquipmentIndex.Horse,
                        EquipmentIndex.HorseHarness);
                    CoopMissionSpawnLogic.TraceClientMountedHeroNetworkContract(
                        agent,
                        "client-synchronize-agent-equipment-suppressed-corrupt",
                        "battle-map handoff SynchronizeAgentSpawnEquipment suppressed-corrupt",
                        "PayloadEquipment={" + payloadSummary + "}" +
                        " CorruptionReason=" + (corruptionReason ?? "unknown") +
                        " ExactVisualApplied=" + heroExactVisualApplied +
                        " TroopExactVisualApplied=" + troopExactVisualApplied);
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: suppressed corrupt client SynchronizeAgentSpawnEquipment payload before native handler. " +
                        "AgentIndex=" + agent.Index +
                        " CharacterId=" + (agent.Character?.StringId ?? "null") +
                        " Reason=" + (corruptionReason ?? "unknown") +
                        " ExactVisualApplied=" + heroExactVisualApplied +
                        " TroopExactVisualApplied=" + troopExactVisualApplied +
                        " PayloadEquipment={" + payloadSummary + "}");
                    ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                        "client-synchronize-agent-equipment-suppressed-corrupt",
                        "AgentIndex=" + agent.Index +
                        " CharacterId=" + (agent.Character?.StringId ?? "null") +
                        " Reason=" + (corruptionReason ?? "unknown") +
                        " ExactVisualApplied=" + heroExactVisualApplied +
                        " TroopExactVisualApplied=" + troopExactVisualApplied +
                        " PayloadEquipment={" + payloadSummary + "}" +
                        " Source=battle-map handoff SynchronizeAgentSpawnEquipment suppressed-corrupt");
                    return false;
                }

                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: SynchronizeAgentSpawnEquipment prefix failed open: " + ex.Message);
                return true;
            }
        }

        private static void TryCanonicalizeExactHeroSynchronizeAgentEquipmentWeaponSlots(
            Mission mission,
            SynchronizeAgentSpawnEquipment synchronizeAgentSpawnEquipment,
            Agent agent)
        {
            try
            {
                if (GameNetwork.IsServer ||
                    mission == null ||
                    synchronizeAgentSpawnEquipment?.SpawnEquipment == null ||
                    agent == null ||
                    agent.IsMount ||
                    !agent.IsHuman ||
                    !SceneRuntimeClassifier.IsExactCampaignBattleScene(mission.SceneName ?? string.Empty))
                {
                    return;
                }

                string entryId = null;
                if (!CoopMissionSpawnLogic.TryResolveAuthoritativeTrackedEntryId(agent, out entryId) &&
                    !CoopMissionSpawnLogic.TryResolveSelectableEntryId(agent, out entryId) &&
                    !ExactTransferContractRuntimeCache.TryGetEntryIdByRiderAgentIndex(agent.Index, out entryId))
                {
                    return;
                }

                RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
                if (!IsExactHeroEntry(entryState))
                    return;

                if (!TryBuildExactHeroExpectedSpawnEquipment(
                        entryId,
                        entryState,
                        out Equipment expectedEquipment,
                        preferSnapshotWeaponOrder: SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty)))
                    return;

                if (!HasExactHeroWeaponPayloadMismatch(
                        synchronizeAgentSpawnEquipment.SpawnEquipment,
                        expectedEquipment,
                        out string mismatchReason))
                {
                    return;
                }

                string beforePayloadWeapons = BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);
                string beforeMissionWeapons = BuildMissionEquipmentWeaponSummary(agent.Equipment);
                string beforeSpawnWeapons = BuildEquipmentSummary(
                    agent.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);

                var changedSlots = new List<string>();
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    expectedEquipment,
                    EquipmentIndex.Weapon0,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    expectedEquipment,
                    EquipmentIndex.Weapon1,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    expectedEquipment,
                    EquipmentIndex.Weapon2,
                    changedSlots);
                CanonicalizeSynchronizeAgentEquipmentSlot(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    expectedEquipment,
                    EquipmentIndex.Weapon3,
                    changedSlots);

                if (changedSlots.Count == 0)
                    return;

                string afterPayloadWeapons = BuildEquipmentSummary(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);
                string expectedWeapons = BuildEquipmentSummary(
                    expectedEquipment,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3);

                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: canonicalized exact hero SynchronizeAgentSpawnEquipment weapon payload before native refresh. " +
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + (entryId ?? "null") +
                    " CharacterId=" + (agent.Character?.StringId ?? "null") +
                    " Reason=" + (mismatchReason ?? "unknown") +
                    " ChangedSlots=[" + string.Join(", ", changedSlots) + "]" +
                    " ExpectedWeapons={" + expectedWeapons + "}" +
                    " PayloadWeaponsBefore={" + beforePayloadWeapons + "}" +
                    " PayloadWeaponsAfter={" + afterPayloadWeapons + "}" +
                    " MissionWeaponsBefore={" + beforeMissionWeapons + "}" +
                    " SpawnWeaponsBefore={" + beforeSpawnWeapons + "}");
                ExactBattleRuntimeBundleBridgeFile.AppendContractEvent(
                    "client-synchronize-agent-equipment-canonicalized-exact-hero-weapons",
                    "AgentIndex=" + agent.Index +
                    " EntryId=" + (entryId ?? "null") +
                    " CharacterId=" + (agent.Character?.StringId ?? "null") +
                    " Reason=" + (mismatchReason ?? "unknown") +
                    " ChangedSlots=[" + string.Join(", ", changedSlots) + "]" +
                    " ExpectedWeapons={" + expectedWeapons + "}" +
                    " PayloadWeaponsBefore={" + beforePayloadWeapons + "}" +
                    " PayloadWeaponsAfter={" + afterPayloadWeapons + "}" +
                    " MissionWeaponsBefore={" + beforeMissionWeapons + "}" +
                    " SpawnWeaponsBefore={" + beforeSpawnWeapons + "}");
            }
            catch (Exception ex)
            {
                ModLogger.Info(
                    "BattleMapSpawnHandoffPatch: exact hero SynchronizeAgentSpawnEquipment weapon payload canonicalization failed open: " +
                    ex.Message);
            }
        }

        private static bool TrySuppressExactSiegeCreateTimeMaterializedSynchronizeAgentEquipmentPayload(
            Mission mission,
            SynchronizeAgentSpawnEquipment synchronizeAgentSpawnEquipment,
            Agent agent,
            out string reason)
        {
            reason = null;
            if (GameNetwork.IsServer ||
                mission == null ||
                synchronizeAgentSpawnEquipment?.SpawnEquipment == null ||
                agent == null ||
                agent.IsMount ||
                !agent.IsHuman ||
                !agent.IsActive() ||
                !SceneRuntimeClassifier.IsExactSiegeAssaultWithDeploymentScene(mission.SceneName ?? string.Empty))
            {
                return false;
            }

            if (!CoopMissionSpawnLogic.TryResolveAuthoritativeTrackedEntryId(agent, out string entryId) ||
                string.IsNullOrWhiteSpace(entryId))
            {
                return false;
            }

            RosterEntryState entryState = BattleSnapshotRuntimeState.GetEntryState(entryId);
            if (entryState == null || IsExactHeroEntry(entryState))
                return false;

            Equipment expectedEquipment = CoopMissionSpawnLogic.BuildSnapshotEquipmentForExactRuntime(
                entryState,
                includeWeapons: true,
                honorExactVisualContracts: false,
                includeArmorVisuals: true,
                includeMountVisuals: false);
            if (expectedEquipment == null)
                return false;

            if (!DoMissionWeaponSlotsMatchExpectedEquipment(
                    agent.Equipment,
                    expectedEquipment,
                    out string liveWeaponMismatch))
            {
                reason = "create-time-mission-weapons-not-authoritative:" + (liveWeaponMismatch ?? "unknown");
                return false;
            }

            if (!DoEquipmentSlotsMatchExpectedEquipment(
                    synchronizeAgentSpawnEquipment.SpawnEquipment,
                    expectedEquipment,
                    out string payloadMismatch,
                    EquipmentIndex.Weapon0,
                    EquipmentIndex.Weapon1,
                    EquipmentIndex.Weapon2,
                    EquipmentIndex.Weapon3,
                    EquipmentIndex.Head,
                    EquipmentIndex.Body,
                    EquipmentIndex.Leg,
                    EquipmentIndex.Gloves,
                    EquipmentIndex.Cape,
                    EquipmentIndex.Horse,
                    EquipmentIndex.HorseHarness))
            {
                reason = "sync-payload-not-duplicate:" + (payloadMismatch ?? "unknown");
                return false;
            }

            reason =
                "exact-siege-create-time-materialized-agent" +
                "|EntryId=" + entryId +
                "|PayloadMatchesSnapshot=True" +
                "|MissionWeaponsMatchSnapshot=True";
            return true;
        }

        private static bool DoMissionWeaponSlotsMatchExpectedEquipment(
            MissionEquipment missionEquipment,
            Equipment expectedEquipment,
            out string mismatch)
        {
            mismatch = null;
            if (missionEquipment == null || expectedEquipment == null)
            {
                mismatch = "missing-equipment";
                return false;
            }

            var mismatches = new List<string>();
            for (EquipmentIndex slot = EquipmentIndex.Weapon0; slot <= EquipmentIndex.Weapon3; slot++)
            {
                string expectedItemId = expectedEquipment[slot].Item?.StringId ?? string.Empty;
                string actualItemId = missionEquipment[slot].Item?.StringId ?? string.Empty;
                if (string.Equals(expectedItemId, actualItemId, StringComparison.OrdinalIgnoreCase))
                    continue;

                if (mismatches.Count < 6)
                {
                    mismatches.Add(
                        slot +
                        ":expected=" + (string.IsNullOrWhiteSpace(expectedItemId) ? "empty" : expectedItemId) +
                        ",actual=" + (string.IsNullOrWhiteSpace(actualItemId) ? "empty" : actualItemId));
                }
            }

            if (mismatches.Count == 0)
                return true;

            mismatch = string.Join("; ", mismatches);
            return false;
        }

        private static bool DoEquipmentSlotsMatchExpectedEquipment(
            Equipment actualEquipment,
            Equipment expectedEquipment,
            out string mismatch,
            params EquipmentIndex[] slots)
        {
            mismatch = null;
            if (actualEquipment == null || expectedEquipment == null)
            {
                mismatch = "missing-equipment";
                return false;
            }

            var mismatches = new List<string>();
            for (int i = 0; i < slots.Length; i++)
            {
                EquipmentIndex slot = slots[i];
                string expectedItemId = expectedEquipment[slot].Item?.StringId ?? string.Empty;
                string actualItemId = actualEquipment[slot].Item?.StringId ?? string.Empty;
                if (string.Equals(expectedItemId, actualItemId, StringComparison.OrdinalIgnoreCase))
                    continue;

                if (mismatches.Count < 6)
                {
                    mismatches.Add(
                        slot +
                        ":expected=" + (string.IsNullOrWhiteSpace(expectedItemId) ? "empty" : expectedItemId) +
                        ",actual=" + (string.IsNullOrWhiteSpace(actualItemId) ? "empty" : actualItemId));
                }
            }

            if (mismatches.Count == 0)
                return true;

            mismatch = string.Join("; ", mismatches);
            return false;
        }

        private static bool ShouldSuppressCorruptedClientSynchronizeAgentEquipmentPayload(
            SynchronizeAgentSpawnEquipment synchronizeAgentSpawnEquipment,
            out string reason)
        {
            reason = null;
            Equipment spawnEquipment = synchronizeAgentSpawnEquipment?.SpawnEquipment;
            if (spawnEquipment == null)
                return false;

            var corruptionReasons = new List<string>();
            AppendCorruptedWeaponSlotReasons(spawnEquipment, corruptionReasons);
            AppendCorruptedMountSlotReasons(spawnEquipment, corruptionReasons);
            if (corruptionReasons.Count == 0)
                return false;

            reason = string.Join(" | ", corruptionReasons);
            return true;
        }

        private static void AppendCorruptedWeaponSlotReasons(Equipment spawnEquipment, List<string> corruptionReasons)
        {
            if (spawnEquipment == null || corruptionReasons == null)
                return;

            for (EquipmentIndex slot = EquipmentIndex.Weapon0; slot <= EquipmentIndex.Weapon3; slot++)
            {
                ItemObject item = spawnEquipment.GetEquipmentFromSlot(slot).Item;
                if (item == null)
                    continue;

                if (item.PrimaryWeapon != null)
                    continue;

                corruptionReasons.Add(
                    slot + "=" + item.StringId +
                    "(non-weapon:" + item.Type + ")");
            }
        }

        private static void AppendCorruptedMountSlotReasons(Equipment spawnEquipment, List<string> corruptionReasons)
        {
            if (spawnEquipment == null || corruptionReasons == null)
                return;

            ItemObject horse = spawnEquipment.GetEquipmentFromSlot(EquipmentIndex.Horse).Item;
            if (horse != null && horse.Type != ItemObject.ItemTypeEnum.Horse)
            {
                corruptionReasons.Add(
                    EquipmentIndex.Horse + "=" + horse.StringId +
                    "(invalid-mount:" + horse.Type + ")");
            }

            ItemObject harness = spawnEquipment.GetEquipmentFromSlot(EquipmentIndex.HorseHarness).Item;
            if (harness != null && harness.Type != ItemObject.ItemTypeEnum.HorseHarness)
            {
                corruptionReasons.Add(
                    EquipmentIndex.HorseHarness + "=" + harness.StringId +
                    "(invalid-harness:" + harness.Type + ")");
            }
        }

        private static bool MissionNetworkComponent_HandleServerEventSynchronizeMissionObject_Prefix(
            GameNetworkMessage baseMessage,
            out bool __state)
        {
            __state = false;
            try
            {
                if (!(baseMessage is SynchronizeMissionObject synchronizeMissionObject))
                    return true;

                Mission mission = Mission.Current;
                if (!ShouldRunAgentMaterializationHandoff(mission))
                    return true;

                if (!ShouldUseSafeStringIdCreateAgentPathOnClient(mission))
                    return true;

                bool remappedExactSiegeMissionObjectId = TryRemapExactSiegeMissionObjectIdMessage(
                    synchronizeMissionObject,
                    "MissionObjectId",
                    SiegeMissionObjectIdBridgeTarget.SynchedMissionObject,
                    "SynchronizeMissionObject");
                if (!remappedExactSiegeMissionObjectId &&
                    ShouldSuppressUnmappedExactSiegeSynchronizeMissionObject(
                        mission,
                        synchronizeMissionObject,
                        out string suppressedSynchronizeReason))
                {
                    TryLogExactSiegeMissionObjectSyncDiagnostic(
                        mission,
                        synchronizeMissionObject,
                        "suppressed-unmapped-mission-object-id",
                        extraDetails: suppressedSynchronizeReason);
                    return false;
                }

                if (!CoopMissionNetworkBridge.IsClientCurrentBattleSnapshotApplied(out string snapshotReadinessSummary))
                {
                    TryLogExactSiegeMissionObjectSyncDiagnostic(
                        mission,
                        synchronizeMissionObject,
                        "deferred-snapshot-not-ready",
                        extraDetails: "SnapshotReadiness=" + (snapshotReadinessSummary ?? "unknown"));
                    RegisterDeferredClientSynchronizeMissionObjectPayload(
                        synchronizeMissionObject,
                        "snapshot-not-ready:" + (snapshotReadinessSummary ?? "unknown"),
                        remappedExactSiegeMissionObjectId);
                    if (ExperimentalFeatures.EnableExactSiegeMissionObjectSyncDiagnostics)
                    {
                        ModLogger.Info(
                            "BattleMapSpawnHandoffPatch: deferred client SynchronizeMissionObject until current battle snapshot is applied. " +
                            "MissionObjectId=" + GetMissionObjectIdValue(synchronizeMissionObject.MissionObjectId) +
                            " Reason=" + (snapshotReadinessSummary ?? "unknown"));
                    }
                    return false;
                }

                if (ShouldDeferExactSiegeMissionObjectSyncUntilClientContractReady(
                        mission,
                        synchronizeMissionObject.MissionObjectId,
                        out string siegeClientContractReason))
                {
                    TryLogExactSiegeMissionObjectSyncDiagnostic(
                        mission,
                        synchronizeMissionObject,
                        "deferred-client-contract-not-ready",
                        extraDetails: "ContractReason=" + (siegeClientContractReason ?? "unknown"));
                    RegisterDeferredClientSynchronizeMissionObjectPayload(
                        synchronizeMissionObject,
                        "siege-client-contract-not-ready:" + (siegeClientContractReason ?? "unknown"),
                        remappedExactSiegeMissionObjectId);
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: deferred client SynchronizeMissionObject until exact siege client contract is ready. " +
                        "MissionObjectId=" + GetMissionObjectIdValue(synchronizeMissionObject.MissionObjectId) +
                        " Reason=" + (siegeClientContractReason ?? "unknown"));
                    return false;
                }

                if (HasDeferredClientSpawnWeaponWithNewEntityPayload(synchronizeMissionObject.MissionObjectId))
                {
                    TryLogExactSiegeMissionObjectSyncDiagnostic(
                        mission,
                        synchronizeMissionObject,
                        "deferred-spawn-weapon-pending");
                    RegisterDeferredClientSynchronizeMissionObjectPayload(
                        synchronizeMissionObject,
                        "spawn-weapon-deferred",
                        remappedExactSiegeMissionObjectId);
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: deferred client SynchronizeMissionObject because SpawnWeaponWithNewEntity is still deferred. " +
                        "MissionObjectId=" + GetMissionObjectIdValue(synchronizeMissionObject.MissionObjectId));
                    return false;
                }

                if (TryGetLocalMissionObject(synchronizeMissionObject.MissionObjectId) == null)
                {
                    TryLogExactSiegeMissionObjectSyncDiagnostic(
                        mission,
                        synchronizeMissionObject,
                        "deferred-local-mission-object-missing");
                    RegisterDeferredClientSynchronizeMissionObjectPayload(
                        synchronizeMissionObject,
                        "local-mission-object-missing",
                        remappedExactSiegeMissionObjectId);
                    ModLogger.Info(
                        "BattleMapSpawnHandoffPatch: deferred client SynchronizeMissionObject because local mission object is not materialized yet. " +
                        "MissionObjectId=" + GetMissionObjectIdValue(synchronizeMissionObject.MissionObjectId));
                    return false;
                }

                __state = true;
                return true;
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: SynchronizeMissionObject prefix failed open: " + ex.Message);
                return true;
            }
        }

        private static Exception MissionNetworkComponent_HandleServerEventSynchronizeMissionObject_Finalizer(
            Exception __exception,
            GameNetworkMessage baseMessage,
            bool __state)
        {
            if (__exception == null)
            {
                if (__state)
                    TryRemoveDeferredClientSynchronizeMissionObjectAfterDirectApply(baseMessage);
                return null;
            }

            try
            {
                if (!(baseMessage is SynchronizeMissionObject synchronizeMissionObject))
                    return __exception;

                Mission mission = Mission.Current;
                if (!ShouldRunAgentMaterializationHandoff(mission))
                    return __exception;

                TryLogExactSiegeMissionObjectSyncDiagnostic(
                    mission,
                    synchronizeMissionObject,
                    "native-handler-exception",
                    __exception);
            }
            catch (Exception ex)
            {
                ModLogger.Info("BattleMapSpawnHandoffPatch: SynchronizeMissionObject finalizer failed open: " + ex.Message);
            }

            return __exception;
        }

